const EMP_PRINTED_KEY = 'emp_printed_labels_v1';
let empPrintedSet = null;
function empPrintedLoad() { if (empPrintedSet) return empPrintedSet; try { empPrintedSet = new Set(JSON.parse(localStorage.getItem(EMP_PRINTED_KEY) || '[]')); } catch { empPrintedSet = new Set(); } return empPrintedSet; }
function isLabelPrinted(mp, id) { if (id == null || id === '') return false; return empPrintedLoad().has(`${mp}:${id}`); }
function markLabelPrinted(mp, id) { if (id == null || id === '') return; const s = empPrintedLoad(); const k = `${mp}:${id}`; if (s.has(k)) return; s.add(k); try { localStorage.setItem(EMP_PRINTED_KEY, JSON.stringify([...s].slice(-2000))); } catch {} render(); }

