function productImageLoaded(image) {
  if (!image) return;
  image.style.visibility = 'visible';
  image.style.display = '';
  image.dataset.imageRetryCount = '0';
}
function retryProductImage(image) {
  if (!image) return;
  const source = image.dataset.imageSource || image.dataset.photo || image.getAttribute('src') || '';
  const attempt = Number(image.dataset.imageRetryCount || 0);
  if (!source || attempt >= 3) {
    image.style.visibility = 'hidden';
    return;
  }
  const nextAttempt = attempt + 1;
  image.dataset.imageSource = source;
  image.dataset.imageRetryCount = String(nextAttempt);
  window.setTimeout(() => {
    try {
      const retryUrl = new URL(source, window.location.href);
      retryUrl.searchParams.set('_image_retry', `${Date.now()}-${nextAttempt}`);
      image.src = retryUrl.toString();
    } catch {
      image.style.visibility = 'hidden';
    }
  }, nextAttempt * 500);
}
window.productImageLoaded = productImageLoaded;
window.retryProductImage = retryProductImage;

function renderCardThumb(url) {
  if (!url) return '';
  return `<img class="card-thumb" src="${esc(url)}" data-photo="${esc(url)}" loading="lazy" alt="фото товара" style="width:54px;height:54px;object-fit:cover;border-radius:8px;border:1px solid #e2e6ee;flex:0 0 auto;cursor:zoom-in;background:#f4f6f9" onload="window.productImageLoaded(this)" onerror="window.retryProductImage(this)" />`;
}
function renderOrderThumb(url) {
  return url
    ? `<img src="${esc(url)}" data-photo="${esc(url)}" loading="lazy" alt="Фото товара" style="width:40px;height:40px;object-fit:cover;border-radius:6px;border:1px solid #e2e6ee;cursor:zoom-in;background:#f4f6f9" onload="window.productImageLoaded(this)" onerror="window.retryProductImage(this)" />`
    : '<div style="width:40px;height:40px;border-radius:6px;background:#f1f3f7"></div>';
}
function renderPickPhotoRow(url) {
  if (!url) return '';
  return `<div style="grid-column:1/-1;display:flex;justify-content:center;padding:6px 0" data-pick-photo-row><img class="card-thumb" src="${esc(url)}" data-photo="${esc(url)}" loading="lazy" alt="фото товара" style="width:96px;height:96px;object-fit:cover;border-radius:8px;border:1px solid #e2e6ee;cursor:zoom-in;background:#f4f6f9" onload="window.productImageLoaded(this)" onerror="window.retryProductImage(this)" /></div>`;
}
function sortPickItems(items) {
  const arr = Array.isArray(items) ? [...items] : [];
  return arr.sort((a, b) => {
    const aDone = Number(a.requiredQty || 0) > 0 && Number(a.pickedQty || 0) >= Number(a.requiredQty || 0) ? 1 : 0;
    const bDone = Number(b.requiredQty || 0) > 0 && Number(b.pickedQty || 0) >= Number(b.requiredQty || 0) ? 1 : 0;
    if (aDone !== bDone) return aDone - bDone;
    return Number(b.requiredQty || 0) - Number(a.requiredQty || 0);
  });
}
function openPhotoFullscreen(url) {
  if (!url) return;
  const existing = document.getElementById('photo-fs-overlay');
  if (existing) closePhotoFullscreen();
  const ov = document.createElement('div');
  ov.id = 'photo-fs-overlay';
  ov.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.93);display:flex;align-items:center;justify-content:center;padding:14px;cursor:zoom-out;';
  const img = document.createElement('img');
  img.src = url;
  img.dataset.imageSource = url;
  img.addEventListener('load', () => productImageLoaded(img));
  img.addEventListener('error', () => retryProductImage(img));
  img.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;border-radius:12px;box-shadow:0 8px 40px rgba(0,0,0,.5);';
  ov.appendChild(img);
  const hint = document.createElement('div');
  hint.textContent = 'Нажмите в любом месте, чтобы закрыть';
  hint.style.cssText = 'position:absolute;bottom:16px;left:0;right:0;text-align:center;color:rgba(255,255,255,.75);font-size:13px;';
  ov.appendChild(hint);
  const close = () => closePhotoFullscreen();
  const onKey = (event) => {
    if (!event || event.key === 'Control') return;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    close();
  };
  ov._photoKeyHandler = onKey;
  ov.addEventListener('click', (event) => { event.preventDefault(); event.stopPropagation(); close(); });
  document.addEventListener('keydown', onKey, true);
  document.body.appendChild(ov);
}
function closePhotoFullscreen() {
  const overlay = document.getElementById('photo-fs-overlay');
  if (!overlay) return false;
  if (overlay._photoKeyHandler) document.removeEventListener('keydown', overlay._photoKeyHandler, true);
  overlay.remove();
  return true;
}
function bindPhotoThumbs() {
  $$('[data-photo]').forEach((el) => {
    if (el.dataset.photoBound) return;
    el.dataset.photoBound = '1';
    el.addEventListener('pointerdown', (e) => e.stopPropagation());
    el.addEventListener('click', (e) => { e.stopPropagation(); e.preventDefault(); openPhotoFullscreen(el.dataset.photo); });
  });
}

