function getFullscreenElementCompat() {
  return document.fullscreenElement
    || document.webkitFullscreenElement
    || document.msFullscreenElement
    || document.mozFullScreenElement
    || null;
}

function isBrowserFullscreenActive() {
  return !!getFullscreenElementCompat();
}

function canToggleBrowserFullscreen() {
  const root = document.documentElement;
  return !!(root?.requestFullscreen
    || root?.webkitRequestFullscreen
    || root?.msRequestFullscreen
    || root?.mozRequestFullScreen);
}

async function enterBrowserFullscreen() {
  const root = document.documentElement;
  if (!root) throw new Error('FULLSCREEN_UNAVAILABLE');
  if (root.requestFullscreen) {
    try {
      await root.requestFullscreen({ navigationUI: 'hide' });
    } catch (_) {
      await root.requestFullscreen();
    }
    return;
  }
  if (root.webkitRequestFullscreen) {
    root.webkitRequestFullscreen();
    return;
  }
  if (root.msRequestFullscreen) {
    root.msRequestFullscreen();
    return;
  }
  if (root.mozRequestFullScreen) {
    root.mozRequestFullScreen();
    return;
  }
  throw new Error('FULLSCREEN_UNAVAILABLE');
}

async function exitBrowserFullscreen() {
  if (document.exitFullscreen) {
    await document.exitFullscreen();
    return;
  }
  if (document.webkitExitFullscreen) {
    document.webkitExitFullscreen();
    return;
  }
  if (document.msExitFullscreen) {
    document.msExitFullscreen();
    return;
  }
  if (document.mozCancelFullScreen) {
    document.mozCancelFullScreen();
    return;
  }
  throw new Error('FULLSCREEN_UNAVAILABLE');
}

async function toggleBrowserFullscreen() {
  if (!canToggleBrowserFullscreen()) {
    throw new Error('FULLSCREEN_UNAVAILABLE');
  }
  if (isBrowserFullscreenActive()) {
    await exitBrowserFullscreen();
    return false;
  }
  await enterBrowserFullscreen();
  return true;
}

function renderEmployeeFullscreenButton() {
  const title = isBrowserFullscreenActive()
    ? '\u0412\u044b\u0439\u0442\u0438 \u0438\u0437 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u044d\u043a\u0440\u0430\u043d\u0430'
    : '\u0412\u043e \u0432\u0435\u0441\u044c \u044d\u043a\u0440\u0430\u043d';
  return `<button class="btn btn-sm employee-fullscreen-btn" id="btn-employee-fullscreen" type="button" title="${title}" aria-label="${title}">&lt;&gt;</button>`;
}

function bindEmployeeFullscreenButton(onUnsupported) {
  const button = $('#btn-employee-fullscreen');
  if (!button) return;
  button.onclick = async () => {
    try {
      await toggleBrowserFullscreen();
      render();
    } catch (err) {
      if ((err && err.message) === 'FULLSCREEN_UNAVAILABLE') {
        if (typeof onUnsupported === 'function') onUnsupported();
        return;
      }
      console.error('fullscreen toggle failed', err);
    }
  };
}

