// ─── URL Router (History API) ───────────────────────────────────────────────
const TAB_MAP_OZ = { new: 'new', assemblies: 'assemblies', problems: 'problems', earnings: 'earnings', employees: 'employees', settings: 'settings' };
const TAB_MAP_WB = { new: 'new', supplies: 'supplies', delivering: 'delivering', problems: 'problems', earnings: 'earnings', employees: 'employees', settings: 'settings' };
const ROUTE_OZ_TABS = new Set(['orders', 'items', 'shipment', 'settings']);
const ROUTE_WB_TABS = new Set(['orders', 'items', 'settings', 'qr']);
let pendingDeepRoute = null;
let routeSyncSuspended = false;

function readRouteParams() {
  return new URLSearchParams(window.location.search || '');
}

function routeQueryToObject(params) {
  const out = {};
  for (const [key, value] of params.entries()) out[key] = value;
  return out;
}

function getRouteEnum(value, allowed, fallback) {
  const normalized = String(value || '').trim();
  return allowed.has(normalized) ? normalized : fallback;
}

function getRouteId(value) {
  const normalized = String(value || '').trim();
  return normalized || '';
}

function getRoutePositiveInt(value) {
  const parsed = Number.parseInt(String(value || ''), 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function isRouteFlagEnabled(value) {
  return String(value || '') === '1';
}

function hasRouteQuery(query) {
  return Object.values(query || {}).some((value) => String(value || '').trim() !== '');
}

function loadMarketplaceAdminRouteData(marketplace, tab, { silent = false } = {}) {
  const user = shared.currentUser;
  if (!user || user.role !== 'admin') return;
  const nextTab = String(tab || '').trim();
  if (marketplace === 'oz') {
    if (nextTab === 'stock_problems') ozLoadStockProblems({ silent });
    else if (nextTab === 'earnings') loadEarningsDashboard({ silent });
    return;
  }
  if (marketplace === 'wb') {
    if (nextTab === 'stock_problems') wbLoadStockProblems({ silent });
    else if (nextTab === 'earnings') loadEarningsDashboard({ silent });
  }
}

// Parse current URL into { marketplace, tab }
function legacyParseRoute() {
  const path = window.location.pathname.replace(BASE_PATH, '').replace(/^\/+|\/+$/g, '');
  const parts = path.split('/').filter(Boolean);
  // /sborka/oz/new → ['oz', 'new']
  // /sborka/wb/supplies → ['wb', 'supplies']
  // /sborka/ → []
  return { marketplace: parts[0] || '', tab: parts[1] || '' };
}

// Build URL from marketplace + tab
function legacyBuildUrl(marketplace, tab) {
  if (!marketplace) return BASE_PATH + '/';
  if (!tab) return BASE_PATH + '/' + marketplace + '/';
  return BASE_PATH + '/' + marketplace + '/' + tab;
}

// Navigate: update URL and re-render
function legacyNavigate(marketplace, tab, replace = false) {
  const url = legacyBuildUrl(marketplace, tab);
  if (replace) {
    history.replaceState({ marketplace, tab }, '', url);
  } else {
    history.pushState({ marketplace, tab }, '', url);
  }
  legacyApplyRoute(marketplace, tab);
}

// Apply route to state and render
async function legacyApplyRoute(marketplace, tab) {
  const prevMp = shared.marketplace;
  if (marketplace && marketplace !== prevMp) {
    // Switching marketplace
    if (prevMp === 'oz') ozCleanup();
    if (prevMp === 'wb') wbCleanup();
    shared.marketplace = marketplace;
    localStorage.setItem('sborka_marketplace', marketplace);
    if (marketplace === 'oz' && tab) ozState.tab = tab;
    if (marketplace === 'wb' && tab) wbState.tab = tab;
    render(); // Show empty interface immediately
    // Load data
    try {
      if (marketplace === 'oz') await ozInit();
      if (marketplace === 'wb') await wbInit();
    } catch (e) { console.error('init error:', e); }
  } else if (marketplace) {
    // Same marketplace, different tab
    if (marketplace === 'oz' && tab && tab !== ozState.tab) { ozState.tab = tab; render(); }
    if (marketplace === 'wb' && tab && tab !== wbState.tab) { wbState.tab = tab; render(); }
    if (!tab) render();
  } else {
    // No marketplace — show selector
    if (prevMp === 'oz') ozCleanup();
    if (prevMp === 'wb') wbCleanup();
    shared.marketplace = '';
    localStorage.removeItem('sborka_marketplace');
    render();
  }
}

function buildRouteQuery(query = {}) {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    const text = String(value ?? '').trim();
    if (!text) continue;
    params.set(key, text);
  }
  return params.toString();
}

function parseRoute() {
  const path = window.location.pathname.replace(BASE_PATH, '').replace(/^\/+|\/+$/g, '');
  const parts = path.split('/').filter(Boolean);
  return {
    marketplace: parts[0] || '',
    tab: parts[1] || '',
    query: routeQueryToObject(readRouteParams()),
  };
}

function buildUrl(marketplace, tab, query = {}) {
  let path = BASE_PATH + '/';
  if (marketplace === 'settings') path = `${BASE_PATH}/settings`;
  else if (marketplace) path = `${BASE_PATH}/${marketplace}/${tab || ''}`.replace(/\/+$/, '/');
  const queryText = buildRouteQuery(query);
  return queryText ? `${path}?${queryText}` : path;
}

function getCurrentRouteQuery(marketplace = shared.marketplace) {
  const user = shared.currentUser;
  if (!user || !marketplace) return {};
  if (marketplace === 'oz' && user.role === 'admin') {
    const query = {};
    if (ozState.storeId) query.store = String(ozState.storeId);
    if (ozState.createOpen) query.create = '1';
    if (ozState.selectedAssembly?.id) {
      query.assembly = String(ozState.selectedAssembly.id);
      query.assemblyTab = ozState.assemblyTab || 'orders';
    }
    if (ozState.employeeStatsUser?.id) query.statsUser = String(ozState.employeeStatsUser.id);
    return query;
  }
  if (marketplace === 'wb' && user.role === 'admin') {
    const query = {};
    if (wbState.storeId) query.store = String(wbState.storeId);
    if (wbState.createOpen) query.create = '1';
    if (wbState.selectedSupply?.id) {
      query.supply = String(wbState.selectedSupply.id);
      query.supplyTab = wbState.supplyTab || 'orders';
    }
    if (wbState.employeeStatsUser?.id) query.statsUser = String(wbState.employeeStatsUser.id);
    return query;
  }
  return {};
}

function syncRouteFromState(replace = true) {
  if (routeSyncSuspended || !shared.authChecked) return;
  const marketplace = shared.currentUser ? shared.marketplace : '';
  const tab = marketplace === 'oz' ? ozState.tab : marketplace === 'wb' ? wbState.tab : marketplace === 'ym' ? ymState.tab : '';
  const query = getCurrentRouteQuery(marketplace);
  const nextUrl = buildUrl(marketplace, tab, query);
  const currentUrl = `${window.location.pathname}${window.location.search || ''}`;
  if (nextUrl === currentUrl) return;
  const nextState = { marketplace, tab, query };
  if (replace) history.replaceState(nextState, '', nextUrl);
  else history.pushState(nextState, '', nextUrl);
}

function setPendingDeepRoute(route) {
  const normalized = route && hasRouteQuery(route.query || {}) ? route : null;
  pendingDeepRoute = normalized;
  routeSyncSuspended = Boolean(normalized);
}

function clearPendingDeepRoute() {
  pendingDeepRoute = null;
  routeSyncSuspended = false;
}

function tryApplyPendingDeepRoute() {
  if (!pendingDeepRoute || !shared.currentUser || pendingDeepRoute.marketplace !== shared.marketplace) return;
  const route = pendingDeepRoute;
  const query = route.query || {};
  const user = shared.currentUser;
  let unresolved = false;
  let shouldRender = false;

  if (shared.marketplace === 'oz' && user.role === 'admin') {
    const nextCreateOpen = isRouteFlagEnabled(query.create);
    if (ozState.createOpen !== nextCreateOpen) {
      ozState.createOpen = nextCreateOpen;
      shouldRender = true;
    }

    const nextAssemblyId = getRouteId(query.assembly);
    const nextAssemblyTab = getRouteEnum(query.assemblyTab, ROUTE_OZ_TABS, 'orders');
    if (nextAssemblyId) {
      if (!ozState.assembliesLoaded) {
        unresolved = true;
      } else {
        const nextAssembly = ozState.assemblies.find((item) => String(item.id) === nextAssemblyId) || null;
        if (nextAssembly) {
          const changedAssembly = !ozState.selectedAssembly || String(ozState.selectedAssembly.id) !== nextAssemblyId;
          if (changedAssembly) {
            ozState.selectedAssembly = nextAssembly;
            ozState.assemblySettingsNotice = '';
            ozState.assemblySettingsError = '';
            ozState.assemblyOrdersError = '';
            ozState.shipmentError = '';
            ozState.shipmentNotice = '';
            shouldRender = true;
          }
          if (ozState.assemblyTab !== nextAssemblyTab) {
            ozState.assemblyTab = nextAssemblyTab;
            shouldRender = true;
          }
          if (changedAssembly || nextAssemblyTab === 'settings') ozLoadAssemblySettings(nextAssembly.id, { silent: true });
          if (changedAssembly || nextAssemblyTab !== 'settings') ozLoadAssemblyOrders(nextAssembly.id, { silent: true });
          if (changedAssembly) ozLoadAssemblyLabelDiagnostics(nextAssembly.id, { silent: true });
        } else if (ozState.selectedAssembly) {
          ozState.selectedAssembly = null;
          shouldRender = true;
        }
      }
    } else if (ozState.selectedAssembly) {
      ozState.selectedAssembly = null;
      shouldRender = true;
    }

    const nextStatsUserId = getRoutePositiveInt(query.statsUser);
    if (nextStatsUserId) {
      if (!ozState.usersLoaded) {
        unresolved = true;
      } else {
        const nextStatsUser = ozState.users.find((item) => Number(item.id) === nextStatsUserId) || null;
        if (nextStatsUser) {
          if (!ozState.employeeStatsUser || Number(ozState.employeeStatsUser.id) !== nextStatsUserId) {
            ozState.employeeStatsUser = nextStatsUser;
            ozState.employeeStatsData = null;
            ozState.employeeStatsError = '';
            ozLoadEmployeeStats(nextStatsUser);
            shouldRender = true;
          }
        } else if (ozState.employeeStatsUser) {
          ozState.employeeStatsUser = null;
          ozState.employeeStatsData = null;
          shouldRender = true;
        }
      }
    } else if (ozState.employeeStatsUser) {
      ozState.employeeStatsUser = null;
      ozState.employeeStatsData = null;
      shouldRender = true;
    }
  }

  if (shared.marketplace === 'wb' && user.role === 'admin') {
    const nextCreateOpen = isRouteFlagEnabled(query.create);
    if (wbState.createOpen !== nextCreateOpen) {
      wbState.createOpen = nextCreateOpen;
      shouldRender = true;
    }

    const nextSupplyId = getRouteId(query.supply);
    const nextSupplyTab = getRouteEnum(query.supplyTab, ROUTE_WB_TABS, 'orders');
    if (nextSupplyId) {
      if (!wbState.adminDataLoaded) {
        unresolved = true;
      } else {
        const nextSupply = [...(Array.isArray(wbState.supplies) ? wbState.supplies : []), ...(Array.isArray(wbState.deliveringSupplies) ? wbState.deliveringSupplies : [])]
          .find((item) => String(item.id) === nextSupplyId) || null;
        if (nextSupply) {
          const changedSupply = !wbState.selectedSupply || String(wbState.selectedSupply.id) !== nextSupplyId;
          if (changedSupply) {
            wbState.selectedSupply = nextSupply;
            wbState.supplyError = '';
            wbState.supplySettingsError = '';
            wbState.supplySettingsNotice = '';
            wbState.supplyQr = null;
            wbState.supplyQrError = '';
            wbState.supplyQrAmount = '1';
            shouldRender = true;
          }
          if (wbState.supplyTab !== nextSupplyTab) {
            wbState.supplyTab = nextSupplyTab;
            shouldRender = true;
          }
          if (changedSupply || nextSupplyTab === 'settings' || nextSupplyTab === 'qr') wbLoadSupplySettings(nextSupply, { silent: true });
          if (changedSupply || nextSupplyTab === 'qr') wbLoadSupplyQr(nextSupply, { silent: true });
          if (changedSupply || (nextSupplyTab !== 'settings' && nextSupplyTab !== 'qr')) wbLoadSupplyOrders(nextSupply, { silent: true });
        } else if (wbState.selectedSupply) {
          wbState.selectedSupply = null;
          shouldRender = true;
        }
      }
    } else if (wbState.selectedSupply) {
      wbState.selectedSupply = null;
      shouldRender = true;
    }

    const nextStatsUserId = getRoutePositiveInt(query.statsUser);
    if (nextStatsUserId) {
      if (!wbState.usersLoaded) {
        unresolved = true;
      } else {
        const nextStatsUser = wbState.users.find((item) => Number(item.id) === nextStatsUserId) || null;
        if (nextStatsUser) {
          if (!wbState.employeeStatsUser || Number(wbState.employeeStatsUser.id) !== nextStatsUserId) {
            wbState.employeeStatsUser = nextStatsUser;
            wbState.employeeStatsData = null;
            wbState.employeeStatsError = '';
            wbLoadEmployeeStats(nextStatsUser);
            shouldRender = true;
          }
        } else if (wbState.employeeStatsUser) {
          wbState.employeeStatsUser = null;
          wbState.employeeStatsData = null;
          shouldRender = true;
        }
      }
    } else if (wbState.employeeStatsUser) {
      wbState.employeeStatsUser = null;
      wbState.employeeStatsData = null;
      shouldRender = true;
    }
  }

  if (unresolved) {
    if (shouldRender) render();
    return;
  }

  clearPendingDeepRoute();
  if (shouldRender) render();
  else syncRouteFromState(true);
}

function navigate(marketplace, tab, replace = false) {
  clearPendingDeepRoute();
  const query = getCurrentRouteQuery(marketplace);
  const url = buildUrl(marketplace, tab, query);
  const state = { marketplace, tab, query };
  if (replace) {
    history.replaceState(state, '', url);
  } else {
    history.pushState(state, '', url);
  }
  applyRoute(marketplace, tab);
}

async function applyRoute(marketplace, tab, route = null) {
  if (route) setPendingDeepRoute(route);
  else clearPendingDeepRoute();
  const prevMp = shared.marketplace;
  if (marketplace === 'settings') {
    if (prevMp === 'oz') ozCleanup();
    if (prevMp === 'wb') wbCleanup();
    if (prevMp === 'ym') ymCleanup();
    shared.marketplace = 'settings';
    localStorage.removeItem('sborka_marketplace');
    render();
    loadGlobalSettings({ silent: true });
    return;
  }
  if (marketplace && marketplace !== prevMp) {
    if (prevMp === 'oz') ozCleanup();
    if (prevMp === 'wb') wbCleanup();
    if (prevMp === 'ym') ymCleanup();
    shared.marketplace = marketplace;
    localStorage.setItem('sborka_marketplace', marketplace);
    if (marketplace === 'oz' && tab) ozState.tab = tab;
    if (marketplace === 'wb' && tab) wbState.tab = tab;
    if (marketplace === 'ym' && tab) ymState.tab = tab;
    render();
    try {
      if (marketplace === 'oz') await ozInit();
      if (marketplace === 'wb') await wbInit();
      if (marketplace === 'ym') await ymInit();
    } catch (e) {
      console.error('init error:', e);
    }
    tryApplyPendingDeepRoute();
    if (marketplace === 'ym' && ymState.tab === 'shipments' && !ymState.shipments.length) ymLoadShipments();
    loadMarketplaceAdminRouteData(marketplace, tab || (marketplace === 'oz' ? ozState.tab : marketplace === 'wb' ? wbState.tab : ymState.tab));
    return;
  }

  if (marketplace) {
    if (marketplace === 'oz' && tab && tab !== ozState.tab) {
      ozState.tab = tab;
      render();
    }
    if (marketplace === 'wb' && tab && tab !== wbState.tab) {
      wbState.tab = tab;
      render();
    }
    if (marketplace === 'ym' && tab && tab !== ymState.tab) {
      ymState.tab = tab;
      render();
      if (ymState.tab === 'shipments' && !ymState.shipments.length) ymLoadShipments();
    }
    if (!tab) render();
    tryApplyPendingDeepRoute();
    loadMarketplaceAdminRouteData(marketplace, tab || (marketplace === 'oz' ? ozState.tab : marketplace === 'wb' ? wbState.tab : ymState.tab));
    return;
  }

  if (prevMp === 'oz') ozCleanup();
  if (prevMp === 'wb') wbCleanup();
  if (prevMp === 'ym') ymCleanup();
  shared.marketplace = '';
  localStorage.removeItem('sborka_marketplace');
  clearPendingDeepRoute();
  render();
}

// Handle browser back/forward
window.addEventListener('popstate', (e) => {
  if (!shared.authChecked || !shared.currentUser) return;
  const route = parseRoute();
  applyRoute(route.marketplace || '', route.tab || '', route);
});

let _loginCompletedAt = 0;

// --- Utility functions (shared) ---
function esc(s) {
  if (s == null) return '';
  const d = document.createElement('div');
  d.textContent = String(s);
  return d.innerHTML.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function $(sel, root) { return (root || document).querySelector(sel); }
function $$(sel, root) { return Array.from((root || document).querySelectorAll(sel)); }

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function bindSafeOverlayClose(selector, onClose) {
  const overlay = $(selector);
  if (!overlay) return;
  let press = null;

  overlay.onpointerdown = (event) => {
    if (event.button !== 0 || event.target !== overlay) {
      press = null;
      return;
    }
    press = { x: event.clientX, y: event.clientY };
  };

  overlay.onpointercancel = () => {
    press = null;
  };

  overlay.onpointerup = (event) => {
    if (!press || event.target !== overlay) {
      press = null;
      return;
    }
    const moved = Math.hypot(event.clientX - press.x, event.clientY - press.y);
    press = null;
    if (moved > 6) return;
    onClose();
  };

  overlay.onclick = (event) => {
    if (event.target === overlay) {
      event.preventDefault();
      event.stopPropagation();
    }
  };
}

function createClientEventId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return `client-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function limitClientLogText(value, maxLength = 4000) {
  const text = String(value ?? '').trim();
  return text ? text.slice(0, maxLength) : '';
}

function sanitizeClientLogValue(value, depth = 0) {
  if (depth > 5) return '[MAX_DEPTH]';
  if (value == null || typeof value === 'number' || typeof value === 'boolean') return value;
  if (typeof value === 'string') return value.slice(0, 4000);
  if (Array.isArray(value)) return value.slice(0, 100).map((item) => sanitizeClientLogValue(item, depth + 1));
  if (typeof value !== 'object') return String(value).slice(0, 4000);
  const out = {};
  for (const [key, child] of Object.entries(value).slice(0, 100)) {
    if (/password|authorization|cookie|session|secret|token|template/i.test(key)) out[key] = '[REDACTED]';
    else out[key] = sanitizeClientLogValue(child, depth + 1);
  }
  return out;
}

function sanitizeClientRequestBody(body) {
  if (body == null) return null;
  if (typeof body !== 'string') return sanitizeClientLogValue(body);
  try {
    return sanitizeClientLogValue(JSON.parse(body));
  } catch {
    return limitClientLogText(body, 4000);
  }
}

function getClientWorkContext() {
  const marketplace = shared.marketplace || '';
  let entityId = '';
  let stage = '';
  if (marketplace === 'oz') {
    entityId = ozState.employeeSelectedAssembly?.id || ozState.selectedAssembly?.id || '';
    stage = ozState.employeeAssemblySession?.workflow?.currentStage || ozState.employeeSelectedAssembly?.currentStage || '';
  } else if (marketplace === 'wb') {
    entityId = wbState.employeeSelectedSupply?.id || wbState.selectedSupply?.id || '';
    stage = wbState.employeeSupplySession?.workflow?.currentStage || wbState.employeeSelectedSupply?.currentStage || '';
  } else if (marketplace === 'ym') {
    entityId = ymState.employeeAssemblyId || ymState.selectedAssemblyId || '';
  }
  return {
    marketplace,
    entityId: String(entityId || ''),
    stage: String(stage || ''),
    user: shared.currentUser ? {
      id: shared.currentUser.id,
      role: shared.currentUser.role,
      name: shared.currentUser.fullName || [shared.currentUser.surname, shared.currentUser.name].filter(Boolean).join(' ') || shared.currentUser.login || '',
    } : null,
  };
}

function isTechnicalClientError(error) {
  const status = Number(error?.status || 0);
  const code = String(error?.code || '').toUpperCase();
  const message = String(error?.message || '').toUpperCase();
  return (
    status >= 500 ||
    status === 0 ||
    code === 'REQUEST_TIMEOUT' ||
    code === 'FAILED_TO_FETCH' ||
    message === 'REQUEST_TIMEOUT' ||
    message === 'PROXY_TIMEOUT' ||
    message === 'PROXY_ERROR' ||
    message === 'FAILED_TO_FETCH' ||
    message === 'INTERNAL_ERROR'
  );
}

function reportClientError(error, details = {}) {
  const eventId = details.eventId || error?.eventId || createClientEventId();
  const workContext = getClientWorkContext();
  const message = limitClientLogText(error?.message || details.message || error || 'Client error');
  const fingerprint = `${details.source || 'client'}|${details.method || ''}|${details.url || ''}|${details.status || error?.status || 0}|${message}`;
  const previousAt = Number(reportedClientErrors.get(fingerprint) || 0);
  if (Date.now() - previousAt < 5000) return eventId;
  reportedClientErrors.set(fingerprint, Date.now());
  if (reportedClientErrors.size > 200) {
    const oldest = reportedClientErrors.keys().next().value;
    reportedClientErrors.delete(oldest);
  }

  const payload = {
    eventId,
    source: details.source || 'client',
    severity: details.severity || (isTechnicalClientError(error) ? 'error' : 'warning'),
    marketplace: details.marketplace || workContext.marketplace || '',
    message,
    stack: limitClientLogText(error?.stack || details.stack || '', 12000),
    pageUrl: location.href,
    viewport: { width: window.innerWidth, height: window.innerHeight, devicePixelRatio: window.devicePixelRatio || 1 },
    online: navigator.onLine,
    clientCreatedAt: new Date().toISOString(),
    context: {
      ...workContext,
      code: error?.code || null,
      errorName: error?.name || null,
      ...(details.context || {}),
    },
    request: {
      method: details.method || null,
      url: details.url || null,
      status: Number(details.status || error?.status || 0) || null,
      durationMs: Number(details.durationMs || 0) || null,
      body: sanitizeClientRequestBody(details.requestBody),
      responseBody: sanitizeClientLogValue(details.responseBody),
    },
  };
  fetch(CLIENT_ERROR_API, {
    method: 'POST',
    credentials: 'include',
    cache: 'no-store',
    keepalive: true,
    headers: { 'Content-Type': 'application/json', 'X-Client-Request-Id': eventId },
    body: JSON.stringify(payload),
  }).catch(() => {});
  return eventId;
}

function showTechnicalError(error, details = {}) {
  const eventId = reportClientError(error, details);
  if (isTechnicalClientError(error)) {
    const compactEventId = String(eventId || '').replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
    showToast(error?.message || 'Техническая ошибка сайта', 'error', {
      persistent: true,
      code: compactEventId.slice(-8) || 'NO-CODE',
    });
  }
  return eventId;
}

async function fetchJson(url, options = {}) {
  const method = String(options.method || 'GET').toUpperCase();
  const isReadOnly = method === 'GET' || method === 'HEAD';
  const timeoutMs = Math.max(
    1000,
    Number(options.timeoutMs || (isReadOnly ? FETCH_TIMEOUT_MS : WRITE_FETCH_TIMEOUT_MS)) || (isReadOnly ? FETCH_TIMEOUT_MS : WRITE_FETCH_TIMEOUT_MS)
  );
  const retryCount = Number.isFinite(Number(options.retryCount))
    ? Math.max(0, Number(options.retryCount))
    : (isReadOnly ? 1 : 0);
  const headers = new Headers(options.headers || {});
  const requestEventId = createClientEventId();
  headers.set('X-Client-Request-Id', requestEventId);
  const requestStartedAt = Date.now();
  const requestKey = isReadOnly
    ? JSON.stringify([method, String(url || ''), Array.from(headers.entries()).sort((a, b) => String(a[0]).localeCompare(String(b[0])))])
    : '';
  if (requestKey && inflightJsonRequests.has(requestKey)) {
    return inflightJsonRequests.get(requestKey);
  }

  let requestPromise;
  requestPromise = (async () => {
    for (let attempt = 0; attempt <= retryCount; attempt += 1) {
      const controller = typeof AbortController === 'function' ? new AbortController() : null;
      const originalSignal = options.signal || null;
      let timeoutId = null;
      let abortRelay = null;
      try {
        if (controller) {
          if (originalSignal) {
            if (originalSignal.aborted) controller.abort();
            else {
              abortRelay = () => controller.abort();
              originalSignal.addEventListener('abort', abortRelay, { once: true });
            }
          }
          timeoutId = setTimeout(() => controller.abort(), timeoutMs);
        }

        const fetchOptions = {
          cache: 'no-store',
          credentials: 'include',
          ...options,
          headers,
          signal: controller ? controller.signal : originalSignal,
        };
        delete fetchOptions.timeoutMs;
        delete fetchOptions.retryCount;

        const res = await fetch(url, fetchOptions);
        const text = await res.text();
        let data = null;
        if (text) { try { data = JSON.parse(text); } catch { data = text; } }
        if (!res.ok) {
          const message =
            (data && typeof data === 'object' && (data.error || data.message)) ||
            (typeof data === 'string' ? data : null) ||
            `HTTP ${res.status}`;
          const err = new Error(message);
          err.status = res.status;
          err.eventId = requestEventId;
          err.responseBody = sanitizeClientLogValue(data);
          throw err;
        }
        return data ?? {};
      } catch (error) {
        let nextError = error;
        if (error?.name === 'AbortError') {
          nextError = new Error('REQUEST_TIMEOUT');
          nextError.code = 'REQUEST_TIMEOUT';
          nextError.timeoutMs = timeoutMs;
        } else if (error instanceof TypeError && !error?.status) {
          nextError = new Error('FAILED_TO_FETCH');
          nextError.code = 'FAILED_TO_FETCH';
          nextError.cause = error;
        }

        const status = Number(nextError?.status || 0);
        const code = String(nextError?.code || '').toUpperCase();
        const message = String(nextError?.message || '').toUpperCase();
        const retryable =
          isReadOnly &&
          (status === 502 || status === 503 || status === 504 || code === 'REQUEST_TIMEOUT' || code === 'FAILED_TO_FETCH' || message === 'PROXY_ERROR');
        if (attempt >= retryCount || !retryable) {
          showTechnicalError(nextError, {
            eventId: requestEventId,
            source: 'api_request',
            method,
            url: String(url || ''),
            status: Number(nextError?.status || 0),
            durationMs: Date.now() - requestStartedAt,
            requestBody: options.body,
            responseBody: nextError?.responseBody || null,
            context: { attempt: attempt + 1, retryCount },
          });
          throw nextError;
        }
        await wait(250 * (attempt + 1));
      } finally {
        if (timeoutId) clearTimeout(timeoutId);
        if (abortRelay && originalSignal) originalSignal.removeEventListener('abort', abortRelay);
      }
    }
    throw new Error('REQUEST_FAILED');
  })().finally(() => {
    if (requestKey && inflightJsonRequests.get(requestKey) === requestPromise) {
      inflightJsonRequests.delete(requestKey);
    }
  });

  if (requestKey) inflightJsonRequests.set(requestKey, requestPromise);
  return requestPromise;
}

function isTransientWriteTimeout(err) {
  const status = Number(err?.status || 0);
  const code = String(err?.code || '').toUpperCase();
  const message = String(err?.message || '').toUpperCase();
  return (
    status === 502 ||
    status === 503 ||
    status === 504 ||
    code === 'REQUEST_TIMEOUT' ||
    code === 'FAILED_TO_FETCH' ||
    message === 'REQUEST_TIMEOUT' ||
    message === 'PROXY_TIMEOUT' ||
    message === 'PROXY_ERROR' ||
    message === 'FAILED_TO_FETCH'
  );
}

function jsonEqual(a, b) {
  if (a === b) return true;
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return false;
  }
}

function assignIfChanged(target, key, nextValue) {
  const changed = !jsonEqual(target[key], nextValue);
  if (changed) target[key] = nextValue;
  return changed;
}

function formatDate(iso) {
  if (!iso) return '\u2014';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '\u2014';
  return d.toLocaleString('ru-RU');
}

function formatDateTime(iso) {
  if (!iso) return '\u2014';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '\u2014';
  return d.toLocaleString('ru-RU');
}

function formatDateOnly(iso) {
  if (!iso) return '\u2014';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '\u2014';
  return d.toLocaleDateString('ru-RU');
}

function timeAgo(iso) {
  if (!iso) return '\u2014';
  const diffMs = Date.now() - new Date(iso).getTime();
  if (!Number.isFinite(diffMs)) return '\u2014';
  const totalMin = Math.max(0, Math.floor(diffMs / 60000));
  const hours = Math.floor(totalMin / 60);
  const minutes = totalMin % 60;
  return `${hours} ч ${minutes} мин назад`;
}

const ORDER_AGE_DAY_MS = 24 * 60 * 60 * 1000;

function sortOrdersOldestFirst(orders) {
  const source = Array.isArray(orders) ? orders : [];
  return source
    .map((order, index) => {
      const createdAt = new Date(order?.createdAt || '').getTime();
      return { order, index, createdAt: Number.isFinite(createdAt) ? createdAt : Number.POSITIVE_INFINITY };
    })
    .sort((left, right) => left.createdAt - right.createdAt || left.index - right.index)
    .map((item) => item.order);
}

function orderAgeClass(createdAt) {
  const createdAtMs = new Date(createdAt || '').getTime();
  if (!Number.isFinite(createdAtMs)) return 'order-age-unknown';
  const ageMs = Math.max(0, Date.now() - createdAtMs);
  if (ageMs < ORDER_AGE_DAY_MS) return 'order-age-fresh';
  if (ageMs < ORDER_AGE_DAY_MS * 2) return 'order-age-warning';
  return 'order-age-critical';
}

function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return `${h} ч ${m} мин`;
  if (m > 0) return `${m} мин ${s} сек`;
  return `${s} сек`;
}

function formatDurationLong(seconds) {
  const total = Math.max(0, Number(seconds) || 0);
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total - hours * 3600 - minutes * 60;
  const secsText = Number(secs.toFixed(2)).toString();
  if (hours > 0) return `${hours} ч ${minutes} мин ${secsText} сек`;
  if (minutes > 0) return `${minutes} мин ${secsText} сек`;
  return `${Number(total.toFixed(2)).toString()} сек`;
}

function formatDurationShort(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;
  if (hours > 0) return `${hours} ч ${minutes} мин`;
  if (minutes > 0) return `${minutes} мин ${secs} сек`;
  return `${secs} сек`;
}

function formatShortDate(iso) {
  if (!iso) return '\u2014';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '\u2014';
  return d.toLocaleDateString('ru-RU', { day: '2-digit', month: 'short' });
}

function formatNumber(value, maxFrac = 1) {
  return new Intl.NumberFormat('ru-RU', { minimumFractionDigits: 0, maximumFractionDigits: maxFrac }).format(Number(value) || 0);
}

const GRA_TO_RUB_RATE = 0.01;

function graToRub(value) {
  return (Number(value) || 0) * GRA_TO_RUB_RATE;
}

function rubToGra(value) {
  return Math.round((Number(value) || 0) * 10000) / 100;
}

function formatRubFromGra(value, maxFrac = 2) {
  return `${formatNumber(graToRub(value), maxFrac)} ₽`;
}

function formatRubInputFromGra(value, maxFrac = 2) {
  return formatNumber(graToRub(value), maxFrac);
}

function formatRubDraftFromGra(value, maxFrac = 2) {
  if (value == null || value === '') return '';
  return formatRubInputFromGra(value, maxFrac);
}

function displayUserName(user) {
  return user?.fullName || `${user?.surname || ''} ${user?.name || ''}`.trim() || user?.login || '\u2014';
}

function isAdminUser(user = shared.currentUser) {
  return user?.role === 'admin' || user?.role === 'super_admin';
}

function isEmployeeUser(user = shared.currentUser) {
  return user?.role === 'employee';
}

function clearEmployeeCoinBurst() {
  if (employeeCoinBurstTimer) {
    clearTimeout(employeeCoinBurstTimer);
    employeeCoinBurstTimer = null;
  }
  employeeCoinState.burstVisible = false;
}

function resetEmployeeCoinState() {
  clearEmployeeCoinBurst();
  employeeCoinState.summary = null;
  employeeCoinState.loading = false;
  employeeCoinState.error = '';
  employeeCoinState.burstText = '';
  employeeCoinState.lastEventId = null;
}

function resetEarningsState() {
  earningsState.dashboard = null;
  earningsState.detail = null;
  earningsState.loading = false;
  earningsState.detailLoading = false;
  earningsState.error = '';
  earningsState.detailError = '';
  earningsState.view = 'summary';
  earningsState.rangeKey = 'all';
  earningsState.customFrom = '';
  earningsState.customTo = '';
  earningsState.marketplace = 'all';
  earningsState.storeId = '';
  earningsState.userId = '';
  earningsState.search = '';
  earningsState.pickRateDraft = '';
  earningsState.orderRateDraft = '';
  earningsState.saveBusy = false;
  earningsState.adjustBusyUserId = null;
  earningsState.detailUserId = '';
  earningsState.detailRequestKey = '';
}

function ensureEarningsRangeDefaults() {
  if (!earningsState.customFrom) earningsState.customFrom = shiftDateString(getMoscowDateString(), -6);
  if (!earningsState.customTo) earningsState.customTo = getMoscowDateString();
}

function getEarningsRange() {
  ensureEarningsRangeDefaults();
  return resolveStatsRange(earningsState.rangeKey, earningsState.customFrom, earningsState.customTo);
}

function getCoinMarketplaceLabel() {
  return shared.marketplace === 'wb' ? 'WB' : 'OZON';
}

async function loadEmployeeCoinSummary({ silent = false } = {}) {
  if (!isEmployeeUser()) {
    resetEmployeeCoinState();
    return null;
  }
  if (!silent) {
    employeeCoinState.loading = true;
    employeeCoinState.error = '';
    render();
  }
  try {
    const data = await fetchJson(`${AUTH_API}/earnings/me`);
    employeeCoinState.summary = data?.summary || null;
    employeeCoinState.error = '';
    return employeeCoinState.summary;
  } catch (err) {
    employeeCoinState.error = err?.message || 'Ошибка загрузки баланса';
    return null;
  } finally {
    if (!silent) {
      employeeCoinState.loading = false;
      render();
    } else {
      render();
    }
  }
}

function triggerEmployeeCoinBurst(text) {
  clearEmployeeCoinBurst();
  employeeCoinState.burstText = text || '';
  employeeCoinState.burstVisible = Boolean(text);
  if (!employeeCoinState.burstVisible) return;
  employeeCoinBurstTimer = setTimeout(() => {
    employeeCoinState.burstVisible = false;
    employeeCoinBurstTimer = null;
    render();
  }, 1650);
}

function applyEmployeeCoinReward(reward, summary = null) {
  if (summary) employeeCoinState.summary = summary;
  if (!reward) return;
  const rewardId = Number(reward?.id || 0) || null;
  if (summary) employeeCoinState.summary = summary;
  if (!rewardId || rewardId === employeeCoinState.lastEventId) {
    render();
    return;
  }
  employeeCoinState.lastEventId = rewardId;
  const amount = Number(reward?.amountDelta || 0);
  triggerEmployeeCoinBurst(amount > 0 ? `+${formatRubFromGra(amount, 2)}` : formatRubFromGra(amount, 2));
  render();
}

function buildEarningsDashboardQuery() {
  const range = getEarningsRange();
  const params = new URLSearchParams();
  if (range?.from) params.set('from', range.from);
  if (range?.to) params.set('to', range.to);
  if (earningsState.marketplace && earningsState.marketplace !== 'all') params.set('marketplace', earningsState.marketplace);
  if (earningsState.storeId) params.set('storeId', earningsState.storeId);
  if (earningsState.search.trim()) params.set('search', earningsState.search.trim());
  const text = params.toString();
  return text ? `?${text}` : '';
}

async function loadEarningsDashboard({ silent = false } = {}) {
  if (!isAdminUser()) return null;
  if (!silent) {
    earningsState.loading = true;
    earningsState.error = '';
    render();
  }
  try {
    const data = await fetchJson(`${AUTH_API}/earnings/dashboard${buildEarningsDashboardQuery()}`);
    earningsState.dashboard = data || null;
    earningsState.error = '';
    if (!earningsState.pickRateDraft) earningsState.pickRateDraft = formatRubDraftFromGra(data?.settings?.pickItemRatePerUnit ?? data?.settings?.ratePerUnit ?? '');
    if (!earningsState.orderRateDraft) earningsState.orderRateDraft = formatRubDraftFromGra(data?.settings?.orderCollectRatePerUnit ?? 0);
    const employees = Array.isArray(data?.employees) ? data.employees : [];
    const currentUserId = Number(earningsState.userId || 0);
    const nextUserId = employees.some((entry) => Number(entry?.userId || 0) === currentUserId)
      ? currentUserId
      : Number(employees?.[0]?.userId || 0);
    if (nextUserId > 0) {
      earningsState.userId = String(nextUserId);
      await loadEarningsEmployeeDetail(nextUserId, { silent: true });
    } else {
      earningsState.userId = '';
      earningsState.detail = null;
      earningsState.detailError = '';
      earningsState.detailUserId = '';
    }
    return data;
  } catch (err) {
    earningsState.error = err?.message || 'Ошибка загрузки заработка';
    return null;
  } finally {
    if (!silent) {
      earningsState.loading = false;
      render();
    } else {
      render();
    }
  }
}

async function loadEarningsEmployeeDetail(userId, { silent = false } = {}) {
  const normalizedUserId = Number(userId || 0);
  if (!isAdminUser() || normalizedUserId < 1) {
    earningsState.detail = null;
    earningsState.detailLoading = false;
    earningsState.detailError = '';
    earningsState.detailUserId = '';
    render();
    return null;
  }
  const requestKey = `${normalizedUserId}:${Date.now()}`;
  earningsState.detailRequestKey = requestKey;
  earningsState.detailLoading = true;
  earningsState.detailError = '';
  if (!silent) render();
  try {
    const data = await fetchJson(`${AUTH_API}/earnings/employees/${encodeURIComponent(normalizedUserId)}${buildEarningsDashboardQuery()}`);
    if (earningsState.detailRequestKey !== requestKey) return data;
    earningsState.detail = data || null;
    earningsState.detailError = '';
    earningsState.detailUserId = String(normalizedUserId);
    return data;
  } catch (err) {
    if (earningsState.detailRequestKey !== requestKey) return null;
    earningsState.detail = null;
    earningsState.detailError = err?.message || 'Не удалось загрузить детализацию сотрудника';
    earningsState.detailUserId = '';
    return null;
  } finally {
    if (earningsState.detailRequestKey === requestKey) earningsState.detailLoading = false;
    render();
  }
}

async function saveEarningsRate() {
  if (!isAdminUser() || earningsState.saveBusy) return;
  const nextPickRateRub = Number(String(earningsState.pickRateDraft || '').replace(',', '.'));
  const nextOrderRateRub = Number(String(earningsState.orderRateDraft || '').replace(',', '.'));
  if (!Number.isFinite(nextPickRateRub) || nextPickRateRub < 0) {
    earningsState.error = 'Укажите корректную ставку за сборку товара';
    render();
    return;
  }
  if (!Number.isFinite(nextOrderRateRub) || nextOrderRateRub < 0) {
    earningsState.error = 'Укажите корректную ставку за сборку заказа';
    render();
    return;
  }
  const nextPickRate = rubToGra(nextPickRateRub);
  const nextOrderRate = rubToGra(nextOrderRateRub);
  earningsState.saveBusy = true;
  earningsState.error = '';
  render();
  try {
    const data = await fetchJson(`${AUTH_API}/earnings/settings`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        pickItemRatePerUnit: nextPickRate,
        orderCollectRatePerUnit: nextOrderRate,
      }),
    });
    earningsState.pickRateDraft = formatRubDraftFromGra(data?.settings?.pickItemRatePerUnit ?? nextPickRate);
    earningsState.orderRateDraft = formatRubDraftFromGra(data?.settings?.orderCollectRatePerUnit ?? nextOrderRate);
    if (earningsState.dashboard?.settings) {
      earningsState.dashboard.settings.pickItemRatePerUnit = Number(data?.settings?.pickItemRatePerUnit ?? nextPickRate);
      earningsState.dashboard.settings.orderCollectRatePerUnit = Number(data?.settings?.orderCollectRatePerUnit ?? nextOrderRate);
      earningsState.dashboard.settings.ratePerUnit = Number(data?.settings?.pickItemRatePerUnit ?? nextPickRate);
    }
    await loadEarningsDashboard({ silent: true });
  } catch (err) {
    earningsState.error = err?.message || 'Не удалось сохранить ставку';
  } finally {
    earningsState.saveBusy = false;
    render();
  }
}

async function adjustEmployeeBalance(userId) {
  if (!isAdminUser() || earningsState.adjustBusyUserId) return;
  const employee = (earningsState.dashboard?.employees || []).find((entry) => Number(entry.userId) === Number(userId));
  if (!employee) return;
  const originalPrompt = typeof window.prompt === 'function' ? window.prompt.bind(window) : null;
  const promptValue = formatRubInputFromGra(employee.balance ?? 0, 2);
  if (originalPrompt) window.prompt = (message) => originalPrompt(`${message} (₽)`, promptValue);
  const nextBalance = window.prompt(`Новый баланс для ${employee.fullName}`, String(employee.balance ?? 0));
  if (originalPrompt) window.prompt = originalPrompt;
  if (nextBalance == null) return;
  const parsed = Number(String(nextBalance).replace(',', '.'));
  if (!Number.isFinite(parsed) || parsed < 0) {
    earningsState.error = 'Укажите корректный баланс';
    render();
    return;
  }
  earningsState.adjustBusyUserId = Number(userId);
  earningsState.error = '';
  render();
  try {
    await fetchJson(`${AUTH_API}/earnings/employees/${encodeURIComponent(userId)}/adjust`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ balance: rubToGra(parsed) }),
    });
    await loadEarningsDashboard({ silent: true });
  } catch (err) {
    earningsState.error = err?.message || 'Не удалось изменить баланс';
  } finally {
    earningsState.adjustBusyUserId = null;
    render();
  }
}

function renderEmployeeCoinCapsule({ compact = false, inline = false } = {}) {
  const summary = employeeCoinState.summary;
  // Superadmin can hide the widget (earnings still accrue silently).
  if (summary && summary.showEmployeeBalance === false) return '';
  const balance = summary ? formatRubInputFromGra(summary.balance || 0, 2) : '0';
  return `<div class="employee-coin-wrap${compact ? ' compact' : ''}${inline ? ' inline' : ''}">
    <div class="employee-coin-capsule${employeeCoinState.burstVisible ? ' is-rewarding' : ''}">
      <div class="employee-coin-core">
        <div class="employee-coin-token">₽</div>
        <div class="employee-coin-main">
          <div class="employee-coin-label">Оплата за точность</div>
          <div class="employee-coin-balance">${balance}<span> ₽</span></div>
        </div>
      </div>
      <div class="employee-coin-reward">${esc(employeeCoinState.burstText || '+0 ₽')}</div>
    </div>
    ${employeeCoinState.error ? `<div class="employee-coin-hint error">${esc(employeeCoinState.error)}</div>` : ''}
  </div>`;
}

function getDirectoryUsers(state) {
  return Array.isArray(state?.userDirectory) ? state.userDirectory : [];
}

function getAvailableDirectoryUsers(state) {
  return getDirectoryUsers(state).filter((entry) => !entry?.alreadyAdded);
}

function renderCreateUserModalClassic(state) {
  const allUsers = getDirectoryUsers(state);
  const availableUsers = getAvailableDirectoryUsers(state);
  const options = [...allUsers].sort((left, right) => {
    const leftAdded = left?.alreadyAdded ? 1 : 0;
    const rightAdded = right?.alreadyAdded ? 1 : 0;
    if (leftAdded !== rightAdded) return leftAdded - rightAdded;
    return displayUserName(left).localeCompare(displayUserName(right), 'ru');
  });
  const busy = Boolean(state?.userBusy || state?.userActionBusy);
  const alreadyAddedCount = Math.max(0, allUsers.length - availableUsers.length);
  return `<div class="modal-overlay" id="modal-create-user">
    <div class="modal-panel">
      <div class="modal-header">
        <div>
          <div class="modal-title">Добавить сотрудника</div>
          <div class="modal-subtitle">Логин и пароль берутся из общей базы сотрудников.</div>
        </div>
        <button class="btn-icon" id="btn-close-create-user">&times;</button>
      </div>
      <div class="modal-body">
        <div class="section-header" style="padding:0 0 12px; gap:10px;">
          <div class="section-subtitle">Всего в общей базе: <strong>${allUsers.length}</strong> · доступно для добавления: <strong>${availableUsers.length}</strong> · уже добавлено: <strong>${alreadyAddedCount}</strong></div>
          <div><button class="btn btn-sm" id="btn-refresh-user-directory" ${state.userDirectoryLoading || busy ? 'disabled' : ''}>ОБНОВИТЬ БАЗУ</button></div>
        </div>
        <div class="form-grid">
          <div class="field">
            <span>Сотрудник</span>
            <select class="input" id="create-user-select" ${state.userDirectoryLoading || busy ? 'disabled' : ''}>
              <option value="">Выберите сотрудника</option>
              ${options.map((entry) => {
                const externalUserId = entry?.externalUserId ?? entry?.id ?? '';
                const alreadyAddedLabel = entry?.alreadyAdded ? ' · уже добавлен' : '';
                return `<option value="${esc(externalUserId)}" ${String(state.createExternalUserId || '') === String(externalUserId) ? 'selected' : ''} ${entry?.alreadyAdded ? 'disabled' : ''}>${esc(displayUserName(entry))}${entry?.login ? ` · ${esc(entry.login)}` : ''}${alreadyAddedLabel}</option>`;
              }).join('')}
            </select>
          </div>
          <div class="field">
            <span>Роль</span>
            <div class="hint" style="padding-top:10px">По умолчанию будет создан упаковщик.</div>
          </div>
        </div>
        ${state.userDirectoryLoading ? '<div class="hint" style="padding-top:10px">Загрузка базы сотрудников...</div>' : ''}
        ${!state.userDirectoryLoading && allUsers.length === 0 ? '<div class="hint" style="padding-top:10px">В общей базе пока нет активных сотрудников.</div>' : ''}
        ${!state.userDirectoryLoading && allUsers.length > 0 && availableUsers.length === 0 ? '<div class="hint" style="padding-top:10px">Все сотрудники из общей базы уже добавлены на сайт.</div>' : ''}
        ${state.userDirectoryError ? `<div class="alert alert-error">${esc(state.userDirectoryError)}</div>` : ''}
        ${state.userActionError ? `<div class="alert alert-error">${esc(state.userActionError)}</div>` : ''}
      </div>
      <div class="modal-footer">
        <button class="btn btn-sm" id="btn-cancel-create-user">ОТМЕНА</button>
        <button class="btn btn-primary" id="btn-do-create-user" ${busy || state.userDirectoryLoading || !String(state.createExternalUserId || '').trim() ? 'disabled' : ''}>${busy ? 'ДОБАВЛЯЕМ...' : 'ДОБАВИТЬ'}</button>
      </div>
    </div>
  </div>`;
}

function sanitizeFilePart(value, fallback = 'export') {
  const n = String(value || '').trim().replace(/[\\/:*?"<>|]+/g, '_').replace(/\s+/g, '_').replace(/_+/g, '_').replace(/^_+|_+$/g, '');
  return n || fallback;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url; link.download = filename;
  document.body.appendChild(link); link.click(); link.remove();
  URL.revokeObjectURL(url);
}

async function exportExcel(rows, header, colWidths, filename) {
  try {
    const XLSX = await import('https://cdn.sheetjs.com/xlsx-0.20.1/package/xlsx.mjs');
    const sheet = XLSX.utils.json_to_sheet(rows, { header });
    sheet['!cols'] = colWidths.map(w => ({ wch: w }));
    const book = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(book, sheet, 'Данные');
    const data = XLSX.write(book, { bookType: 'xlsx', type: 'array' });
    downloadBlob(new Blob([data], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), filename);
  } catch (err) { console.error('Excel export failed', err); }
}

// --- Десктоп-приложение (kiosk-обёртка): прямая печать этикеток ---
const IS_DESKTOP_APP = !!(typeof window !== 'undefined' && window.desktopBridge && window.desktopBridge.isDesktop);
// Кулдаун кнопки печати этикетки (одинаково на OZ и WB): после печати кнопка на 3с
// блокируется с обратным отсчётом, затем снова доступна — можно перепечатать без ошибок.
// Кнопка печати на экране всегда одна (открытый заказ), поэтому кулдаун глобальный.
let labelPrintCooldownUntil = 0;
let labelPrintCooldownTimer = null;
let labelPrintCooldownRestore = '';
function labelDefaultPrintText() { return IS_DESKTOP_APP ? 'Напечатать этикетку' : 'Открыть этикетку'; }
function applyLabelPrintCooldown(btnEl) {
  if (!btnEl) return;
  if (labelPrintCooldownTimer) { clearInterval(labelPrintCooldownTimer); labelPrintCooldownTimer = null; }
  const btnId = btnEl.id || '';
  const tick = () => {
    // берём актуальную кнопку по id — переживает ре-рендер во время отсчёта.
    const btn = (btnId && document.getElementById(btnId)) || btnEl;
    const remaining = Math.ceil((labelPrintCooldownUntil - Date.now()) / 1000);
    if (remaining > 0) {
      btn.disabled = true;
      btn.dataset.printing = '1';
      btn.classList.add('is-printed'); btn.classList.remove('is-printing');
      btn.textContent = 'Напечатано ✓ · ' + remaining + ' с';
    } else {
      if (labelPrintCooldownTimer) { clearInterval(labelPrintCooldownTimer); labelPrintCooldownTimer = null; }
      labelPrintCooldownUntil = 0;
      delete btn.dataset.printing;
      // перерисовываем через render(): кнопка печати получает вид «жёлтая · Перепечатать ✓»,
      // а кнопка «Завершить» разблокируется (этикетка уже напечатана хотя бы раз).
      render();
    }
  };
  tick();
  labelPrintCooldownTimer = setInterval(tick, 250);
}
function startLabelPrintCooldown(btnEl, restoreText, seconds) {
  labelPrintCooldownUntil = Date.now() + Math.max(1, Number(seconds) || 3) * 1000;
  labelPrintCooldownRestore = restoreText || labelDefaultPrintText();
  applyLabelPrintCooldown(btnEl);
}

async function desktopPrintLabel(url, copies, btnEl, options = {}) {
  if (!url) { showToast('Этикетка ещё не загружена', 'error'); return false; }
  if (!IS_DESKTOP_APP) { window.open(url, '_blank', 'noopener'); return false; }
  // Кулдаун активен — молча игнорируем (защита от повторной печати кликом/Alt/сканером).
  if (labelPrintCooldownUntil > Date.now()) return false;
  // Защита от повторных нажатий: блокируем кнопку и показываем статус на ней + в тосте.
  if (btnEl && btnEl.dataset.printing === '1') return false;
  const prevText = btnEl ? btnEl.textContent : '';
  if (btnEl) { btnEl.dataset.printing = '1'; btnEl.disabled = true; btnEl.textContent = 'Печатается…'; btnEl.classList.add('is-printing'); btnEl.classList.remove('is-printed'); }
  // URL этикетки часто относительный (/OZ/files/...); приложение делает fetch и требует
  // абсолютный адрес с хостом — приводим относительный путь к абсолютному по origin страницы.
  let absUrl = url;
  try { absUrl = new URL(url, window.location.href).href; } catch (_e) {}
  try {
    showToast('Этикетка печатается…', 'info');
    const r = await window.desktopBridge.printLabel({ url: absUrl, copies: copies || 1, fitMode: options.fitMode });
    if (r && r.ok) {
      showToast('Этикетка отправлена на принтер', 'success');
      // 3с кулдаун с таймером, затем кнопка снова доступна (можно перепечатать).
      if (btnEl) startLabelPrintCooldown(btnEl, prevText || labelDefaultPrintText(), 3);
      return true;
    }
    showToast('Ошибка печати: ' + ((r && r.error) || 'неизвестно'), 'error');
    if (btnEl) { btnEl.disabled = false; btnEl.textContent = prevText; delete btnEl.dataset.printing; btnEl.classList.remove('is-printing', 'is-printed'); }
    return false;
  } catch (e) {
    showToast('Ошибка печати: ' + (e && e.message || e), 'error');
    if (btnEl) { btnEl.disabled = false; btnEl.textContent = prevText; delete btnEl.dataset.printing; btnEl.classList.remove('is-printing', 'is-printed'); }
    return false;
  }
}

// --- Shared toasts ---
const sharedToasts = [];
function showToast(message, type = 'success', options = {}) {
  const normalizedMessage = String(message || 'Ошибка').trim();
  const code = String(options.code || '').trim();
  const persistent = options.persistent === true || (options.persistent !== false && type === 'error');
  const duplicate = sharedToasts.find((toast) => toast.message === normalizedMessage && toast.type === type && toast.code === code);
  if (duplicate) {
    duplicate.count = Number(duplicate.count || 1) + 1;
    duplicate.createdAt = new Date().toISOString();
    duplicate.persistent = duplicate.persistent || persistent;
    renderToasts();
    return duplicate.id;
  }
  const id = Date.now() + Math.random();
  sharedToasts.push({ id, message: normalizedMessage, type, code, persistent, count: 1, createdAt: new Date().toISOString() });
  if (sharedToasts.length > 20) {
    const removableIndex = sharedToasts.findIndex((toast) => !toast.persistent);
    sharedToasts.splice(removableIndex >= 0 ? removableIndex : 0, 1);
  }
  renderToasts();
  if (!persistent) setTimeout(() => { removeToast(id); }, 5000);
  return id;
}
function removeToast(id) {
  const idx = sharedToasts.findIndex(t => t.id === id);
  if (idx >= 0) { sharedToasts.splice(idx, 1); renderToasts(); }
}
function renderToasts() {
  let c = document.getElementById('toast-container');
  if (!c) { c = document.createElement('div'); c.id = 'toast-container'; c.className = 'toast-container'; document.body.appendChild(c); }
  c.innerHTML = sharedToasts.map(t => {
    const title = t.type === 'error' ? 'Ошибка сайта' : t.type === 'warning' ? 'Предупреждение' : 'Готово';
    const timestamp = t.createdAt ? new Date(t.createdAt).toLocaleTimeString('ru-RU') : '';
    return `<div class="toast ${t.type}" role="${t.type === 'error' ? 'alert' : 'status'}">
      <div class="toast-body">
        <div class="toast-title">${esc(title)}${t.code ? ` · ${esc(t.code)}` : ''}${Number(t.count || 1) > 1 ? ` · ×${Number(t.count)}` : ''}</div>
        <div class="toast-message">${esc(t.message)}</div>
        ${timestamp ? `<div class="toast-time">${esc(timestamp)}${t.persistent ? ' · сообщение останется до закрытия' : ''}</div>` : ''}
      </div>
      <button class="toast-close" data-toast-id="${t.id}" type="button" aria-label="Закрыть сообщение">&times;</button>
    </div>`;
  }).join('');
  c.querySelectorAll('.toast-close').forEach(btn => btn.onclick = () => removeToast(Number(btn.dataset.toastId)));
}

window.addEventListener('error', (event) => {
  const error = event.error instanceof Error ? event.error : new Error(event.message || 'Ошибка JavaScript');
  showTechnicalError(error, {
    source: 'window_error',
    severity: 'error',
    context: { filename: event.filename || null, line: event.lineno || null, column: event.colno || null },
  });
});

window.addEventListener('unhandledrejection', (event) => {
  const reason = event.reason;
  const error = reason instanceof Error ? reason : new Error(typeof reason === 'string' ? reason : 'Необработанная ошибка операции');
  showTechnicalError(error, { source: 'unhandled_rejection', severity: 'error' });
});

// --- Shared audio ---
let sharedAudioCtx = null;
function initAudio() {
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return;
  const unlock = () => {
    if (!sharedAudioCtx) try { sharedAudioCtx = new Ctor(); } catch { return; }
    if (sharedAudioCtx.state === 'suspended') sharedAudioCtx.resume().catch(() => {});
  };
  window.addEventListener('pointerdown', unlock, { passive: true });
  window.addEventListener('keydown', unlock);
}

function playTone(kind = 'success') {
  if (!sharedAudioCtx) return;
  const schedule = () => {
    const now = sharedAudioCtx.currentTime;
    const notes = kind === 'error'
      ? [{ f: 220, o: 0, d: 0.1, g: 0.08, t: 'sawtooth' }, { f: 165, o: 0.11, d: 0.16, g: 0.07, t: 'triangle' }]
      : [{ f: 880, o: 0, d: 0.07, g: 0.05, t: 'sine' }, { f: 1174, o: 0.08, d: 0.09, g: 0.045, t: 'sine' }];
    notes.forEach(n => {
      const osc = sharedAudioCtx.createOscillator(), gain = sharedAudioCtx.createGain();
      osc.type = n.t; osc.frequency.setValueAtTime(n.f, now + n.o);
      gain.gain.setValueAtTime(0.0001, now + n.o); gain.gain.exponentialRampToValueAtTime(n.g, now + n.o + 0.01); gain.gain.exponentialRampToValueAtTime(0.0001, now + n.o + n.d);
      osc.connect(gain); gain.connect(sharedAudioCtx.destination); osc.start(now + n.o); osc.stop(now + n.o + n.d + 0.02);
    });
  };
  if (sharedAudioCtx.state === 'suspended') sharedAudioCtx.resume().then(schedule).catch(() => {}); else schedule();
}

// --- Shared pick cell sorting ---
function normalizePickCellName(v) {
  return String(v || '').trim().toUpperCase().replace(/\s+/g, '').replace(/C/g, '\u0421').replace(/P/g, '\u041F').replace(/K/g, '\u041A');
}
function parsePickCellSortValue(v) {
  const n = normalizePickCellName(v);
  if (!n) return { known: false, rack: Number.MAX_SAFE_INTEGER, shelf: Number.MAX_SAFE_INTEGER, box: Number.MAX_SAFE_INTEGER, tail: '', raw: '' };
  const m = n.match(/^\u0421(\d+)\u041F(\d+)(?:\u041A(\d+))?(.*)$/u);
  if (m) return { known: true, rack: Number(m[1]), shelf: Number(m[2]), box: m[3] ? Number(m[3]) : -1, tail: m[4] || '', raw: n };
  return { known: false, rack: Number.MAX_SAFE_INTEGER, shelf: Number.MAX_SAFE_INTEGER, box: Number.MAX_SAFE_INTEGER, tail: '', raw: n };
}
function comparePickCellNames(left, right) {
  const a = parsePickCellSortValue(left), b = parsePickCellSortValue(right);
  if (a.known !== b.known) return a.known ? -1 : 1;
  if (a.rack !== b.rack) return a.rack - b.rack;
  if (a.shelf !== b.shelf) return a.shelf - b.shelf;
  if (a.box !== b.box) return a.box - b.box;
  if (a.tail !== b.tail) return a.tail.localeCompare(b.tail, 'ru', { numeric: true, sensitivity: 'base' });
  return a.raw.localeCompare(b.raw, 'ru', { numeric: true, sensitivity: 'base' });
}
function sortPickCells(cells) {
  return [...(Array.isArray(cells) ? cells : [])].sort((a, b) => comparePickCellNames(a?.name || a?.id || '', b?.name || b?.id || ''));
}
function formatFbsCells(cells) {
  const list = sortPickCells(cells);
  if (!list.length) return '\u2014';
  const multi = list.length > 1;
  return list.map(c => { const n = String(c?.name || c?.id || '').trim() || '\u2014'; const s = Number(c?.stock ?? 0); return multi ? `${n} (${s})` : n; }).filter(Boolean).join(', ');
}
function formatFbsValueList(values) {
  const src = Array.isArray(values) ? values : [values];
  const list = [];
  for (const v of src) { const t = String(v ?? '').trim(); if (t && !list.includes(t)) list.push(t); }
  return list.length ? list.join(', ') : '\u2014';
}
function formatOzonMarketplaceCode(item) {
  return formatFbsValueList(item?.marketplaceBarcodes?.length ? item.marketplaceBarcodes : item?.marketplaceBarcode);
}
function formatWbBarcodeValue(item) {
  return formatFbsValueList(item?.barcodes?.length ? item.barcodes : item?.barcode);
}
function normalizeFbsProgress(progress, fallbackRunning = false) {
  const stage = String(progress?.stage || 'idle');
  const done = Number(progress?.done || 0);
  const total = Number(progress?.total || 0);
  const percentRaw = Number(progress?.percent);
  const percent = Number.isFinite(percentRaw) ? Math.max(0, Math.min(100, percentRaw)) : total > 0 ? Math.max(0, Math.min(100, (done / total) * 100)) : 0;
  return { stage, message: String(progress?.message || ''), done, total, percent, current: progress?.current || null, running: Boolean(progress?.running) || (fallbackRunning && stage !== 'idle' && stage !== 'done' && stage !== 'error') };
}
function hasUsableFbsStockResponse(data) {
  const items = Array.isArray(data?.items) ? data.items.length : 0;
  const total = Number(data?.totals?.all || 0);
  const scopeStores = Array.isArray(data?.scopeStores) ? data.scopeStores.length : 0;
  return items > 0 || total > 0 || scopeStores > 0 || Boolean(data?.updatedAt);
}
function hasUsableFbsStockState(state) {
  const items = Array.isArray(state?.fbsStockItems) ? state.fbsStockItems.length : 0;
  const total = Number(state?.fbsStockTotals?.all || 0);
  return items > 0 || total > 0 || Boolean(state?.fbsStockUpdatedAt);
}

function sortEmployeePickItems(items) {
  return [...(Array.isArray(items) ? items : [])].filter(i => Number(i?.remainingQty ?? 0) > 0).sort((l, r) => {
    const cell = (arr) => { const first = sortPickCells(arr?.msCells || [])[0]; return first?.name || first?.id || ''; };
    const byCell = comparePickCellNames(cell(l), cell(r));
    if (byCell !== 0) return byCell;
    const byArt = String(l?.article || '').localeCompare(String(r?.article || ''), 'ru', { numeric: true, sensitivity: 'base' });
    if (byArt !== 0) return byArt;
    return Number(l?.id || 0) - Number(r?.id || 0);
  });
}
function mergeEmployeePickItem(items, updated) {
  if (!updated?.id) return sortEmployeePickItems(items);
  if (Number(updated?.remainingQty ?? 0) <= 0) return sortEmployeePickItems((Array.isArray(items) ? items : []).filter(i => Number(i?.id) !== Number(updated.id)));
  let found = false;
  const next = (Array.isArray(items) ? items : []).map(i => {
    if (Number(i?.id) !== Number(updated.id)) return i;
    found = true;
    const keepMsCells = Array.isArray(i?.msCells) ? i.msCells : [];
    const nextMsCells = Array.isArray(updated?.msCells) && updated.msCells.length ? updated.msCells : keepMsCells;
    return { ...i, ...updated, msCells: nextMsCells };
  });
  if (!found) next.push(updated);
  return sortEmployeePickItems(next);
}

// Shared stats helpers
const MOSCOW_OFFSET = '+03:00';
function getMoscowDateString(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Moscow', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day}`;
}
function shiftDateString(dateStr, deltaDays) {
  if (!dateStr) return '';
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!m) return '';
  const next = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]) + deltaDays));
  if (Number.isNaN(next.getTime())) return '';
  return `${next.getUTCFullYear()}-${String(next.getUTCMonth() + 1).padStart(2, '0')}-${String(next.getUTCDate()).padStart(2, '0')}`;
}
function buildRangePayload(from, to) {
  if (!from || !to) return { from: null, to: null };
  const f = new Date(`${from}T00:00:00${MOSCOW_OFFSET}`);
  const t = new Date(`${shiftDateString(to, 1)}T00:00:00${MOSCOW_OFFSET}`);
  return {
    from: Number.isNaN(f.getTime()) ? null : from,
    to: Number.isNaN(t.getTime()) ? null : to,
  };
}
function resolveStatsRange(rangeKey, customFrom, customTo) {
  const today = getMoscowDateString();
  if (rangeKey === 'all') return { from: null, to: null };
  if (rangeKey === 'today') return buildRangePayload(today, today);
  if (rangeKey === '7d') return buildRangePayload(shiftDateString(today, -6), today);
  if (rangeKey === '30d') return buildRangePayload(shiftDateString(today, -29), today);
  if (rangeKey === 'month') { const [y, mo] = today.split('-'); return buildRangePayload(`${y}-${mo}-01`, today); }
  return buildRangePayload(customFrom, customTo);
}
function formatUnitsPerHour(units, seconds, unitLabel) {
  const c = Number(units || 0), t = Number(seconds || 0);
  if (c <= 0 || t <= 0) return '\u2014';
  return `${formatNumber((c * 3600) / t)} ${unitLabel}/ч`;
}
function formatSecondsPerUnit(seconds, units, unitLabel) {
  const c = Number(units || 0), t = Number(seconds || 0);
  if (c <= 0 || t <= 0) return '\u2014';
  return `${formatDuration(t / c)} / ${unitLabel}`;
}
function formatUnitsPerSession(units, sessions, unitLabel) {
  const c = Number(units || 0), s = Number(sessions || 0);
  if (c <= 0 || s <= 0) return '\u2014';
  return `${formatNumber(c / s)} ${unitLabel}`;
}

// h() for virtual DOM nodes (used by OZ employee modal)
function h(tag, attrs, ...children) {
  const el = document.createElement(tag);
  if (attrs) {
    for (const [key, value] of Object.entries(attrs)) {
      if (key === 'className') el.className = value;
      else if (key === 'style' && typeof value === 'object') Object.assign(el.style, value);
      else if (key.startsWith('on') && typeof value === 'function') el.addEventListener(key.slice(2).toLowerCase(), value);
      else if (key === 'disabled') { if (value) el.setAttribute('disabled', ''); }
      else if (key === 'checked') { el.checked = Boolean(value); }
      else if (key === 'value') el.value = value;
      else if (key === 'readOnly') { if (value) el.readOnly = true; }
      else if (key === 'selected') { el.selected = Boolean(value); }
      else if (key === 'type') el.type = value;
      else if (key === 'placeholder') el.placeholder = value;
      else if (key === 'htmlFor') el.htmlFor = value;
      else if (key === 'href') el.href = value;
      else if (key === 'target') el.target = value;
      else if (key === 'rel') el.rel = value;
      else if (key === 'innerHTML') el.innerHTML = value;
      else if (key === 'min') el.min = value;
      else if (key === 'list') el.setAttribute('list', value);
      else if (key === 'dataset') { for (const [k, v] of Object.entries(value)) el.dataset[k] = v; }
      else if (key === 'id') el.id = value;
      else if (key === 'tabIndex') el.tabIndex = value;
      else if (key === 'maxLength') el.maxLength = value;
      else el.setAttribute(key, value);
    }
  }
  for (const child of children) {
    if (child == null || child === false) continue;
    if (typeof child === 'string' || typeof child === 'number') el.appendChild(document.createTextNode(String(child)));
    else if (child instanceof Node) el.appendChild(child);
    else if (Array.isArray(child)) child.forEach(c => { if (c instanceof Node) el.appendChild(c); });
  }
  return el;
}


// ================================================================
// SECTION 2: LOGIN SCREEN
// ================================================================

function renderLoginScreen() {
  // В десктоп-приложении вход — по отпечатку пальца (обрабатывает оболочка). Форму
  // логина/пароля показываем только если сотрудник/админ явно нажал «Войти по паролю».
  if (IS_DESKTOP_APP && !shared.showPasswordLogin) {
    return `<div class="login-screen">
      <div class="login-card login-card-fp">
        <div class="login-fp-icon">☝</div>
        <div class="login-title">Приложите палец к датчику</div>
        <div class="login-subtitle">Вход в личный кабинет по отпечатку пальца</div>
        <div class="login-fp-hint">Хочет поработать другой сотрудник — просто приложите свой палец.</div>
        ${shared.loginError ? `<div class="alert alert-error">${esc(shared.loginError)}</div>` : ''}
        <div class="login-actions">
          <button class="btn btn-sm" id="btn-login-password-fallback" type="button">Войти по паролю</button>
        </div>
      </div>
    </div>`;
  }
  return `<div class="login-screen">
    <div class="login-card">
      <div class="login-title">FBS Сборка</div>
      <div class="login-subtitle">Единая система сборки заказов</div>
      <div class="form-grid">
        <div class="field"><span>Логин</span><input class="input" id="login-login" value="${esc(shared.loginLogin)}" placeholder="Данила Пущин" /></div>
        <div class="field"><span>Пароль</span><input class="input" id="login-password" type="password" value="${esc(shared.loginPassword)}" placeholder="••••••" /></div>
      </div>
      ${shared.loginError ? `<div class="alert alert-error">${esc(shared.loginError)}</div>` : ''}
      <div class="login-actions">
        ${IS_DESKTOP_APP ? '<button class="btn btn-sm" id="btn-login-back-fp" type="button">← К отпечатку</button>' : ''}
        <button class="btn btn-primary" id="btn-login" ${shared.loginBusy ? 'disabled' : ''}>${shared.loginBusy ? 'ВХОД...' : 'ВОЙТИ'}</button>
      </div>
    </div>
  </div>`;
}

function bindLoginScreen() {
  // Десктоп: экран отпечатка. Нуджим оболочку вернуться на fingerprint (на случай,
  // если сигнал site:logout не дошёл — напр. старая версия оболочки), один раз.
  if (IS_DESKTOP_APP && !shared.showPasswordLogin) {
    if (!shared._fpNudgeSent && window.desktopBridge && typeof window.desktopBridge.logout === 'function') {
      shared._fpNudgeSent = true;
      try { window.desktopBridge.logout(); } catch {}
    }
    const fallbackBtn = $('#btn-login-password-fallback');
    if (fallbackBtn) fallbackBtn.onclick = () => { shared.showPasswordLogin = true; shared.loginError = ''; render(); };
    return;
  }
  shared._fpNudgeSent = false;
  const backFp = $('#btn-login-back-fp');
  if (backFp) backFp.onclick = () => { shared.showPasswordLogin = false; shared.loginError = ''; shared.loginPassword = ''; render(); };
  const loginInput = $('#login-login');
  const passInput = $('#login-password');
  if (loginInput) {
    loginInput.oninput = e => { shared.loginLogin = e.target.value; };
    loginInput.onkeydown = e => { if (e.key === 'Enter') handleSharedLogin(); };
  }
  if (passInput) {
    passInput.oninput = e => { shared.loginPassword = e.target.value; };
    passInput.onkeydown = e => { if (e.key === 'Enter') handleSharedLogin(); };
  }
  const btn = $('#btn-login');
  if (btn) btn.onclick = handleSharedLogin;
}

async function handleSharedLogin() {
  shared.loginError = '';
  const login = shared.loginLogin.trim();
  if (!login || !shared.loginPassword) { shared.loginError = 'Введите логин и пароль'; render(); return; }
  shared.loginBusy = true; render();
  try {
    const data = await fetchJson(`${AUTH_API}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ login, password: shared.loginPassword }) });
    if (!data?.user) { shared.loginError = 'Не удалось авторизоваться'; shared.loginBusy = false; render(); return; }
    _loginCompletedAt = Date.now();
    shared.currentUser = data.user;
    resetEarningsState();
    if (isEmployeeUser(data.user)) loadEmployeeCoinSummary({ silent: true });
    else resetEmployeeCoinState();
    shared.loginPassword = '';
    shared.loginLogin = '';
    shared.loginError = '';
    shared.authChecked = true;
    shared.loginBusy = false;
    const route = parseRoute();
    if (route.marketplace) {
      applyRoute(route.marketplace, route.tab || 'new', route);
    } else {
      navigate('', '', true);
      render();
    }
  } catch (err) {
    shared.loginError = err?.message || 'Ошибка входа';
    shared.loginBusy = false;
    render();
  }
}

async function handleSharedLogout() {
  // Cleanup active marketplace
  if (shared.marketplace === 'oz') ozCleanup();
  if (shared.marketplace === 'wb') wbCleanup();
  if (shared.marketplace === 'ym') ymCleanup();
  try { await fetchJson(`${AUTH_API}/auth/logout`, { method: 'POST' }); } catch {}
  // В десктоп-приложении выход возвращает на экран отпечатка (не на форму логина сайта)
  if (IS_DESKTOP_APP && window.desktopBridge && typeof window.desktopBridge.logout === 'function') {
    try { window.desktopBridge.logout(); } catch {}
  }
  shared.currentUser = null;
  shared.marketplace = '';
  shared.loginPassword = '';
  shared.loginBusy = false;
  shared.loginError = '';
  shared.authChecked = true;
  shared.showPasswordLogin = false;
  shared._fpNudgeSent = false;
  resetEmployeeCoinState();
  resetEarningsState();
  localStorage.removeItem('sborka_marketplace');
  history.replaceState({ marketplace: '', tab: '' }, '', `${BASE_PATH}/`);
  render();
}


// ================================================================
// SECTION 3: MARKETPLACE SELECTOR
// ================================================================

function renderMarketplaceSelector() {
  const isSuper = shared.currentUser?.role === 'super_admin';
  return `<div class="login-screen marketplace-select-screen">
    <div class="marketplace-select-panel">
      <div class="marketplace-select-head">
        <div>
          <div class="login-title">FBS Сборка</div>
          <div class="login-subtitle">Добро пожаловать, ${esc(displayUserName(shared.currentUser))}</div>
        </div>
        <button class="btn btn-sm" id="btn-logout-selector">ВЫЙТИ</button>
      </div>
      <div class="marketplace-select-grid">
        ${isSuper ? `<button class="marketplace-tile marketplace-tile-settings" id="btn-select-global-settings" type="button">
          <span class="marketplace-tile-kicker">Superadmin</span>
          <strong>Глобальные настройки</strong>
          <span>Сотрудники, админы, локации и настройки складов.</span>
        </button>` : `<button class="marketplace-tile marketplace-tile-oz" id="btn-select-oz" type="button">
          <span class="marketplace-tile-kicker">Ozon</span>
          <strong>Сборки Ozon</strong>
          <span>Новые заказы, поставки, этикетки и отгрузка.</span>
        </button>
        <button class="marketplace-tile marketplace-tile-wb" id="btn-select-wb" type="button">
          <span class="marketplace-tile-kicker">WB</span>
          <strong>Поставки WB</strong>
          <span>Создание поставок, разделение, QR и контроль сборки.</span>
        </button>
        <button class="marketplace-tile marketplace-tile-ym" id="btn-select-ym" type="button">
          <span class="marketplace-tile-kicker">Яндекс</span>
          <strong>Все FBS-магазины</strong>
          <span>Заказы, сборки, этикетки и отгрузки Яндекс Маркета.</span>
        </button>`}
      </div>
    </div>
  </div>`;
}

function bindMarketplaceSelector() {
  const ozBtn = $('#btn-select-oz');
  const wbBtn = $('#btn-select-wb');
  const ymBtn = $('#btn-select-ym');
  const settingsBtn = $('#btn-select-global-settings');
  const logoutBtn = $('#btn-logout-selector');
  if (ozBtn) ozBtn.onclick = () => activateMarketplace('oz', 'new');
  if (wbBtn) wbBtn.onclick = () => activateMarketplace('wb', 'new');
  if (ymBtn) ymBtn.onclick = () => activateMarketplace('ym', 'new');
  if (settingsBtn) settingsBtn.onclick = () => navigate('settings', '');
  if (logoutBtn) logoutBtn.onclick = handleSharedLogout;
}

function activateMarketplace(mp, tab) {
  const defaultTab = mp === 'oz' ? 'new' : 'new';
  navigate(mp, tab || defaultTab);
}

function switchMarketplace() {
  navigate('', '');
}

function isGlobalSettingsUser() {
  return shared.currentUser?.role === 'super_admin';
}

function globalRoleLabel(role) {
  if (role === 'super_admin') return 'Superadmin';
  if (role === 'admin') return 'Admin';
  if (role === 'employee') return 'Сотрудник';
  if (role === 'archived') return 'Архив';
  return role || '—';
}

function globalLocationLabel(code) {
  const configuredLocations = globalSettingsState.data?.locations;
  const locations = Array.isArray(configuredLocations) && configuredLocations.length ? configuredLocations : SITE_LOCATIONS;
  const item = locations.find((loc) => loc.code === code);
  return item?.label || (code === 'moscow' ? 'Москва' : code === 'izhevsk' ? 'Ижевск' : 'Не настроен');
}

function globalSkladWarehouseOptions(selectedId = '') {
  const warehouses = Array.isArray(globalSettingsState.data?.skladWarehouses)
    ? globalSettingsState.data.skladWarehouses
    : [];
  if (!warehouses.length) return '<option value="">Склады не загружены</option>';
  return `<option value="">Выберите склад</option>${warehouses.map((item) => `<option value="${esc(item.id)}" ${String(selectedId || '') === String(item.id) ? 'selected' : ''}>${esc(`${item.name} · #${item.id}`)}</option>`).join('')}`;
}

function globalLocationOptions(selectedCode = '', includeEmpty = true, emptyLabel = 'Не настроен') {
  const configuredLocations = globalSettingsState.data?.locations;
  const locations = Array.isArray(configuredLocations) && configuredLocations.length ? configuredLocations : SITE_LOCATIONS;
  return `${includeEmpty ? `<option value="">${esc(emptyLabel)}</option>` : ''}${locations.map((loc) => `<option value="${esc(loc.code)}" ${selectedCode === loc.code ? 'selected' : ''}>${esc(loc.label)}</option>`).join('')}`;
}

async function loadGlobalSettings({ silent = false } = {}) {
  if (!isGlobalSettingsUser()) return;
  if (!silent) { globalSettingsState.loading = true; globalSettingsState.error = ''; render(); }
  try {
    const data = await fetchJson(`${AUTH_API}/global/settings`);
    globalSettingsState.data = data || null;
    globalSettingsState.error = '';
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось загрузить глобальные настройки';
  } finally {
    globalSettingsState.loading = false;
    render();
  }
}

function getGlobalStoreScopeOptions(locationCode) {
  const data = globalSettingsState.data || {};
  const out = [{ value: 'all||', label: 'Все маркетплейсы и магазины', skladWarehouseId: '' }];
  const wbStores = Array.isArray(data.marketplaceOptions?.wb?.stores) ? data.marketplaceOptions.wb.stores : [];
  const ozStores = Array.isArray(data.marketplaceOptions?.oz?.stores) ? data.marketplaceOptions.oz.stores : [];
  for (const store of wbStores) {
    const warehouses = Array.isArray(store.warehouses) ? store.warehouses : [];
    if (!warehouses.length) {
      out.push({ value: `wb|${store.id || ''}|`, label: `WB · ${store.name || store.id || 'магазин'}` });
      continue;
    }
    for (const wh of warehouses) {
      const whId = wh.warehouseId || wh.id || '';
      const whName = wh.warehouseName || wh.name || wh.label || whId || 'склад';
      out.push({ value: `wb|${store.id || ''}|${whId}`, label: `WB · ${store.name || store.id || 'магазин'} · ${whName}` });
    }
  }
  for (const store of ozStores) {
    const warehouses = Array.isArray(store.warehouses) ? store.warehouses : [];
    if (!warehouses.length) {
      out.push({ value: `oz|${store.id || ''}|`, label: `Ozon · ${store.name || store.id || 'магазин'}` });
      continue;
    }
    for (const wh of warehouses) {
      const whId = wh.warehouseId || wh.id || '';
      const whName = wh.warehouseName || wh.name || wh.label || whId || 'склад';
      out.push({ value: `oz|${store.id || ''}|${whId}`, label: `Ozon · ${store.name || store.id || 'магазин'} · ${whName}` });
    }
  }
  return out.map((item) => `<option value="${esc(item.value)}">${esc(item.label)}</option>`).join('');
}

function renderGlobalUsersTab() {
  const data = globalSettingsState.data || {};
  const users = Array.isArray(data.users) ? data.users : [];
  const directory = (Array.isArray(data.directory) ? data.directory : [])
    .filter((item) => {
      const q = String(globalSettingsState.directoryQuery || '').trim().toLowerCase();
      if (!q) return true;
      return `${item.fullName || ''} ${item.login || ''}`.toLowerCase().includes(q);
    })
    .slice(0, 250);
  const activeUsers = users.filter((user) => !user.archived);
  const needsSetup = activeUsers.filter((user) => user.needsSetup).length;
  return `<div class="global-settings-stack">
    <section class="card global-settings-card">
      <div class="section-header">
        <div>
          <div class="section-title">Добавить пользователя</div>
          <div class="section-subtitle">В справочнике показаны только активные сотрудники из общей базы.</div>
        </div>
      </div>
      <div class="global-user-create">
        <input class="input" id="global-directory-search" value="${esc(globalSettingsState.directoryQuery)}" placeholder="Поиск по ФИО или логину" />
        <select class="input" id="global-create-user">
          <option value="">Выберите сотрудника</option>
          ${directory.map((item) => `<option value="${esc(item.id)}" ${item.alreadyAdded ? 'disabled' : ''}>${esc(item.fullName || item.login)}${item.alreadyAdded ? ' · уже добавлен' : ''}</option>`).join('')}
        </select>
        <select class="input" id="global-create-role">
          <option value="employee" ${globalSettingsState.createRole === 'employee' ? 'selected' : ''}>Сотрудник</option>
          <option value="admin" ${globalSettingsState.createRole === 'admin' ? 'selected' : ''}>Admin</option>
        </select>
        <select class="input" id="global-create-location" ${globalSettingsState.createRole === 'admin' ? 'disabled' : ''}>
          ${globalLocationOptions(globalSettingsState.createLocationCode)}
        </select>
        <button class="btn btn-primary btn-sm" id="global-create-user-btn">Добавить</button>
      </div>
    </section>
    <section class="card global-settings-card">
      <div class="section-header">
        <div>
          <div class="section-title">Пользователи</div>
          <div class="section-subtitle">${activeUsers.length} активных · ${needsSetup} сотрудников требуют настройки локации.</div>
        </div>
      </div>
      <table class="tbl global-users-table">
        <thead><tr><th>Пользователь</th><th>Роль</th><th>Локация</th><th>Статус</th><th class="r">Действия</th></tr></thead>
        <tbody>${users.length ? users.map((user) => {
          const isSuper = user.role === 'super_admin';
          const busy = String(globalSettingsState.userBusyId) === String(user.id);
          return `<tr class="${user.archived ? 'muted-row' : ''}">
            <td><div class="cell-primary">${esc(user.fullName || user.login || '—')}</div><div class="cell-muted">${esc(user.externalLogin || user.login || '')}${user.balance != null ? ` · ${esc(user.balance)} GRA` : ''}</div></td>
            <td>${isSuper ? `<span class="pill">Superadmin</span>` : `<select class="input input-sm" data-global-user-role="${esc(user.id)}">
              <option value="employee" ${user.role === 'employee' ? 'selected' : ''}>Сотрудник</option>
              <option value="admin" ${user.role === 'admin' ? 'selected' : ''}>Admin</option>
            </select>`}</td>
            <td>${isSuper ? '<span class="hint">—</span>' : `<select class="input input-sm" data-global-user-location="${esc(user.id)}" ${user.role === 'admin' || user.archived ? 'disabled' : ''}>${globalLocationOptions(user.locationCode || '')}</select>`}</td>
            <td>${user.archived ? '<span class="pill danger">Архив</span>' : user.needsSetup ? '<span class="pill danger">Нужно настроить</span>' : `<span class="pill">${esc(globalRoleLabel(user.role))}</span>`}${user.externalStatus && user.externalStatus !== 'active' ? ` <span class="pill danger">${esc(user.externalStatus)}</span>` : ''}</td>
            <td class="r">${isSuper ? '' : `<button class="btn btn-sm" data-global-save-user="${esc(user.id)}" ${busy ? 'disabled' : ''}>${busy ? 'Сохраняю...' : 'Сохранить'}</button> <button class="btn btn-sm btn-danger" data-global-archive-user="${esc(user.id)}" ${busy ? 'disabled' : ''}>Удалить</button>`}</td>
          </tr>`;
        }).join('') : '<tr><td colspan="5" class="tbl-empty">Пользователи не загружены</td></tr>'}</tbody>
      </table>
    </section>
  </div>`;
}

function renderGlobalWarehouseColumn(location) {
  const settings = (globalSettingsState.data?.warehouseSettings || []).filter((item) => item.locationCode === location.code);
  const defaultSetting = settings.find((item) => item.marketplace === 'all' && !item.storeId && !item.marketplaceWarehouseId) || {};
  const preciseSettings = settings.filter((item) => item.storeId || item.marketplaceWarehouseId);
  const busyDefault = globalSettingsState.warehouseBusyKey === `${location.code}:default`;
  return `<section class="card global-location-card">
    <div class="section-header">
      <div>
        <div class="section-title">${esc(location.label)}</div>
        <div class="section-subtitle">Склад остатков для поставок и сборок этой локации.</div>
      </div>
    </div>
    ${preciseSettings.length ? '' : `<div class="global-location-form">
      <label class="field"><span>Склад по умолчанию</span><select class="input" id="global-default-sklad-${esc(location.code)}">${globalSkladWarehouseOptions(defaultSetting.skladWarehouseId || '')}</select></label>
      <button class="btn btn-primary btn-sm" data-global-save-default="${esc(location.code)}" ${busyDefault ? 'disabled' : ''}>${busyDefault ? 'Сохраняю...' : 'Сохранить'}</button>
    </div>`}
    <div class="global-location-form">
      <label class="field"><span>Точная привязка</span><select class="input" id="global-map-scope-${esc(location.code)}">${getGlobalStoreScopeOptions(location.code)}</select></label>
      <label class="field"><span>Внутренний склад</span><select class="input" id="global-map-sklad-${esc(location.code)}">${globalSkladWarehouseOptions('')}</select></label>
      <button class="btn btn-sm" data-global-save-map="${esc(location.code)}">Добавить</button>
    </div>
    <div class="global-settings-list">${settings.length ? settings.map((item) => `<div class="global-setting-row">
      <div><strong>${esc(item.marketplace === 'all' ? 'Все' : item.marketplace.toUpperCase())}</strong><span>${esc([item.storeId, item.marketplaceWarehouseName || item.marketplaceWarehouseId].filter(Boolean).join(' · ') || 'по умолчанию')}</span></div>
      <div>${esc(item.skladWarehouseName || item.skladWarehouseId || '—')}</div>
      <button class="btn btn-sm btn-danger" data-global-delete-map="${esc(item.id)}">Удалить</button>
    </div>`).join('') : '<div class="hint">Настроек пока нет</div>'}</div>
  </section>`;
}

function renderGlobalWarehousesTab() {
  const data = globalSettingsState.data || {};
  const locations = Array.isArray(data.locations) ? data.locations : [];
  const skladError = data.skladWarehouses?.error;
  return `<div class="global-settings-stack">
    ${skladError ? `<div class="alert alert-error">${esc(skladError)}</div>` : ''}
    <div class="global-location-grid">${locations.map(renderGlobalWarehouseColumn).join('')}</div>
  </div>`;
}

function renderMovedEmployeesNotice() {
  const isSuper = isGlobalSettingsUser();
  return `<section class="card">
    <div class="section-header">
      <div>
        <div class="section-title">Сотрудники перенесены</div>
        <div class="section-subtitle">Управление сотрудниками теперь находится в глобальных настройках Superadmin.</div>
      </div>
      ${isSuper ? '<button class="btn btn-primary btn-sm" id="btn-open-global-settings">Открыть настройки</button>' : ''}
    </div>
  </section>`;
}

function renderGlobalSettingsPage() {
  const user = shared.currentUser;
  if (!isGlobalSettingsUser()) {
    return `<div class="login-screen"><div class="login-card"><div class="login-title">Нет доступа</div><div class="login-subtitle">Глобальные настройки доступны только Superadmin.</div><button class="btn btn-primary" id="btn-back-selector">Назад</button></div></div>`;
  }
  const tabs = [
    { key: 'employees', label: 'Сотрудники' },
    { key: 'warehouses', label: 'Настройки' },
    { key: 'earnings', label: 'Заработок' },
  ];
  return `<div>
    <div class="topbar">
      <div>
        <div class="brand">FBS Сборка</div>
        <div class="topbar-breadcrumb">Глобальные настройки</div>
      </div>
      <div class="topbar-controls">
        <button class="btn btn-sm" id="btn-global-oz">Ozon</button>
        <button class="btn btn-sm" id="btn-global-wb">WB</button>
        <button class="btn btn-sm" id="btn-global-refresh" ${globalSettingsState.loading ? 'disabled' : ''}>${globalSettingsState.loading ? 'Обновляю...' : 'Обновить'}</button>
        <div class="topbar-user">${esc(displayUserName(user))}</div>
        <button class="btn btn-sm" id="btn-global-logout">Выйти</button>
      </div>
    </div>
    <div class="tabs">${tabs.map((tab) => `<button class="tab ${globalSettingsState.tab === tab.key ? 'active' : ''}" data-global-tab="${esc(tab.key)}">${esc(tab.label)}</button>`).join('')}</div>
    <main class="main-content global-settings-page">
      ${globalSettingsState.notice ? `<div class="alert alert-success">${esc(globalSettingsState.notice)}</div>` : ''}
      ${globalSettingsState.error ? `<div class="alert alert-error">${esc(globalSettingsState.error)}</div>` : ''}
      ${globalSettingsState.loading && !globalSettingsState.data ? '<div class="hint" style="padding:20px;text-align:center">Загрузка...</div>' : ''}
      ${globalSettingsState.tab === 'employees' ? renderGlobalUsersTab() : globalSettingsState.tab === 'earnings' ? renderEarningsTabV6() : renderGlobalWarehousesTab()}
    </main>
  </div>`;
}

function parseGlobalScopeValue(value) {
  const [marketplace = 'all', storeId = '', marketplaceWarehouseId = ''] = String(value || 'all||').split('|');
  return { marketplace: marketplace || 'all', storeId, marketplaceWarehouseId };
}

async function createGlobalUser() {
  const externalUserId = $('#global-create-user')?.value || '';
  const role = $('#global-create-role')?.value || 'employee';
  const locationCode = role === 'employee' ? ($('#global-create-location')?.value || '') : '';
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  try {
    await fetchJson(`${AUTH_API}/global/users`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ externalUserId, role, locationCode }),
    });
    globalSettingsState.createExternalUserId = '';
    globalSettingsState.notice = 'Пользователь добавлен';
    await loadGlobalSettings({ silent: true });
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось добавить пользователя';
    render();
  }
}

async function saveGlobalUser(userId) {
  const role = $(`[data-global-user-role="${userId}"]`)?.value || 'employee';
  const locationCode = role === 'employee' ? ($(`[data-global-user-location="${userId}"]`)?.value || '') : '';
  globalSettingsState.userBusyId = String(userId);
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  render();
  try {
    const res = await fetchJson(`${AUTH_API}/global/users/${encodeURIComponent(userId)}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ role, locationCode }),
    });
    // Apply the server's answer locally right away — no waiting for a full reload.
    if (res?.user && Array.isArray(globalSettingsState.data?.users)) {
      globalSettingsState.data.users = globalSettingsState.data.users.map((u) =>
        String(u.id) === String(res.user.id) ? res.user : u
      );
    }
    globalSettingsState.notice = 'Пользователь сохранён';
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось сохранить пользователя';
  } finally {
    globalSettingsState.userBusyId = '';
    render();
  }
  loadGlobalSettings({ silent: true }).catch(() => {});
}

async function archiveGlobalUser(userId) {
  if (!confirm('Удалить пользователя из новой версии? История останется в базе.')) return;
  globalSettingsState.userBusyId = String(userId);
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  render();
  try {
    await fetchJson(`${AUTH_API}/global/users/${encodeURIComponent(userId)}`, { method: 'DELETE' });
    // Drop the user from the local list immediately.
    if (Array.isArray(globalSettingsState.data?.users)) {
      globalSettingsState.data.users = globalSettingsState.data.users.filter(
        (u) => String(u.id) !== String(userId)
      );
    }
    globalSettingsState.notice = 'Пользователь удалён из активных';
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось удалить пользователя';
  } finally {
    globalSettingsState.userBusyId = '';
    render();
  }
  loadGlobalSettings({ silent: true }).catch(() => {});
}

async function saveGlobalWarehouseDefault(locationCode) {
  const skladWarehouseId = $(`#global-default-sklad-${locationCode}`)?.value || '';
  globalSettingsState.warehouseBusyKey = `${locationCode}:default`;
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  render();
  try {
    const res = await fetchJson(`${AUTH_API}/global/warehouse-settings`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ locationCode, marketplace: 'all', skladWarehouseId }),
    });
    applyGlobalWarehouseSettingLocally(res?.setting);
    globalSettingsState.notice = `Склад для ${globalLocationLabel(locationCode)} сохранён`;
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось сохранить склад';
  } finally {
    globalSettingsState.warehouseBusyKey = '';
    render();
  }
  loadGlobalSettings({ silent: true }).catch(() => {});
}

// Upsert one warehouse-setting row into local state (instant UI, no full reload).
function applyGlobalWarehouseSettingLocally(setting) {
  if (!setting || !globalSettingsState.data) return;
  const list = Array.isArray(globalSettingsState.data.warehouseSettings)
    ? globalSettingsState.data.warehouseSettings
    : [];
  const idx = list.findIndex((s) => String(s.id) === String(setting.id));
  if (idx >= 0) list[idx] = setting;
  else list.push(setting);
  globalSettingsState.data.warehouseSettings = [...list];
}

async function saveGlobalWarehouseMap(locationCode) {
  const scope = parseGlobalScopeValue($(`#global-map-scope-${locationCode}`)?.value || '');
  const skladWarehouseId = $(`#global-map-sklad-${locationCode}`)?.value || '';
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  try {
    const res = await fetchJson(`${AUTH_API}/global/warehouse-settings`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ locationCode, ...scope, skladWarehouseId }),
    });
    applyGlobalWarehouseSettingLocally(res?.setting);
    globalSettingsState.notice = 'Привязка склада сохранена';
    render();
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось сохранить привязку';
    render();
  }
  loadGlobalSettings({ silent: true }).catch(() => {});
}

async function deleteGlobalWarehouseMap(settingId) {
  globalSettingsState.notice = '';
  globalSettingsState.error = '';
  try {
    await fetchJson(`${AUTH_API}/global/warehouse-settings/${encodeURIComponent(settingId)}`, { method: 'DELETE' });
    if (Array.isArray(globalSettingsState.data?.warehouseSettings)) {
      globalSettingsState.data.warehouseSettings = globalSettingsState.data.warehouseSettings.filter(
        (s) => String(s.id) !== String(settingId)
      );
    }
    globalSettingsState.notice = 'Привязка удалена';
    render();
  } catch (err) {
    globalSettingsState.error = err?.message || 'Не удалось удалить привязку';
    render();
  }
  loadGlobalSettings({ silent: true }).catch(() => {});
}

function bindGlobalSettingsPage() {
  const back = $('#btn-back-selector');
  if (back) back.onclick = () => navigate('', '');
  const ozBtn = $('#btn-global-oz');
  const wbBtn = $('#btn-global-wb');
  const refreshBtn = $('#btn-global-refresh');
  const logoutBtn = $('#btn-global-logout');
  if (ozBtn) ozBtn.onclick = () => navigate('oz', 'new');
  if (wbBtn) wbBtn.onclick = () => navigate('wb', 'new');
  if (refreshBtn) refreshBtn.onclick = () => loadGlobalSettings();
  if (logoutBtn) logoutBtn.onclick = handleSharedLogout;
  $$('[data-global-tab]').forEach((button) => {
    button.onclick = () => {
      globalSettingsState.tab = button.dataset.globalTab || 'employees';
      if (globalSettingsState.tab === 'earnings' && !earningsState.dashboard && !earningsState.loading) {
        loadEarningsDashboard({ silent: false });
      }
      render();
    };
  });
  if (globalSettingsState.tab === 'earnings') bindEarningsTabV6();
  const directorySearch = $('#global-directory-search');
  if (directorySearch) directorySearch.oninput = (event) => { globalSettingsState.directoryQuery = event.target.value || ''; render(); };
  const createRole = $('#global-create-role');
  if (createRole) createRole.onchange = (event) => { globalSettingsState.createRole = event.target.value || 'employee'; render(); };
  const createLocation = $('#global-create-location');
  if (createLocation) createLocation.onchange = (event) => { globalSettingsState.createLocationCode = event.target.value || ''; };
  const createUserBtn = $('#global-create-user-btn');
  if (createUserBtn) createUserBtn.onclick = createGlobalUser;
  $$('[data-global-save-user]').forEach((button) => {
    button.onclick = () => saveGlobalUser(button.dataset.globalSaveUser);
  });
  $$('[data-global-archive-user]').forEach((button) => {
    button.onclick = () => archiveGlobalUser(button.dataset.globalArchiveUser);
  });
  $$('[data-global-user-role]').forEach((select) => {
    select.onchange = () => {
      const locationSelect = $(`[data-global-user-location="${select.dataset.globalUserRole}"]`);
      if (locationSelect) locationSelect.disabled = select.value === 'admin';
    };
  });
  $$('[data-global-save-default]').forEach((button) => {
    button.onclick = () => saveGlobalWarehouseDefault(button.dataset.globalSaveDefault);
  });
  $$('[data-global-save-map]').forEach((button) => {
    button.onclick = () => saveGlobalWarehouseMap(button.dataset.globalSaveMap);
  });
  $$('[data-global-delete-map]').forEach((button) => {
    button.onclick = () => deleteGlobalWarehouseMap(button.dataset.globalDeleteMap);
  });
  const movedBtn = $('#btn-open-global-settings');
  if (movedBtn) movedBtn.onclick = () => navigate('settings', '');
}


