const ozTimers = { newOrders: null, assemblies: null, employee: null, fbsStockPoll: null, collector: null, scanDebounce: null, labelScanDebounce: null, lookupDebounce: null, pickScanDebounce: null, pickIssueDebounce: null };
const ozRefs = { lastAssembliesRefresh: 0, lastOrdersRefresh: 0, lastSessionRefresh: 0, liveRefreshBlockedUntil: 0, pickFocusCanFocus: false };
let ozSseSource = null;

// The full OZ module is too large to inline — we dynamically load the OZ app.js
// Instead, we embed all OZ functions as a self-contained module.

function ozAdminFetch(url, options = {}) {
  const headers = { ...(ozState.storeId ? { 'X-Store-Id': ozState.storeId } : {}), ...(options.headers || {}) };
  return fetchJson(url, { ...options, headers });
}

function ozHandleAuthError(err) {
  if (err?.status === 401) {
    if (Date.now() - _loginCompletedAt < 5000) return true;
    shared.currentUser = null; shared.authChecked = true; render(); return true;
  }
  return false;
}

function ozCleanup() {
  Object.keys(ozTimers).forEach(key => { if (ozTimers[key]) { clearInterval(ozTimers[key]); clearTimeout(ozTimers[key]); ozTimers[key] = null; } });
  if (ozSseSource) { ozSseSource.close(); ozSseSource = null; }
  ozState.sseConnected = false;
}

async function ozInit() {
  ozConnectSSE();
  const user = shared.currentUser;
  if (!user) return;
  const isSuper = user.role === 'super_admin';
  const isAdmin = user.role === 'admin';
  const isEmployee = user.role === 'employee';
  const isCollector = isEmployee && user.position === 'collector';

  if (isSuper) { ozLoadUsers(); ozLoadUserDirectory(); render(); return; }
  if (isAdmin) {
    try {
      const API_BASE = getApiBase();
      const storesData = await fetchJson(`${API_BASE}/stores`);
      const stores = Array.isArray(storesData?.stores) ? storesData.stores : [];
      ozState.storeOptions = stores;
      const defaultId = storesData?.defaultStoreId || stores[0]?.id || '';
      const routeStoreId = pendingDeepRoute?.marketplace === 'oz' ? getRouteId(pendingDeepRoute?.query?.store) : '';
      let next = routeStoreId && stores.find(s => String(s.id) === routeStoreId) ? routeStoreId : (ozState.storeId || defaultId);
      if (next && !stores.find(s => s.id === next)) next = defaultId;
      if (next && next !== ozState.storeId) ozState.storeId = next;
      if (ozState.storeId) localStorage.setItem('oz_store_id', ozState.storeId);
    } catch (e) { console.error('ozInit stores error:', e); }
    render();
    await ozInitAdminData();
    return;
  }
  if (isEmployee && isCollector) { ozLoadCollectorAssemblies(); ozSetupCollectorPolling(); }
  else if (isEmployee) { ozLoadEmployeeAssemblies(); ozSetupEmployeePolling(); }
  render();
}

async function ozInitAdminData() {
  const API_BASE = getApiBase();
  try {
    const [newData, asmData] = await Promise.all([
      ozAdminFetch(`${API_BASE}/new-orders`).catch(() => null),
      ozAdminFetch(`${API_BASE}/assemblies`).catch(() => null),
    ]);
    if (newData) { ozState.newOrders = Array.isArray(newData?.orders) ? newData.orders : []; ozState.newUpdatedAt = new Date(); }
    if (asmData) { ozState.assemblies = Array.isArray(asmData?.assemblies) ? asmData.assemblies : []; ozState.assembliesLoaded = true; }
  } catch {}
  render();
  tryApplyPendingDeepRoute();
  ozLoadStockProblems({ silent: true });
  ozLoadScanIssues({ silent: true });
  ozLoadUsers();
  ozLoadUserDirectory();
  ozSetupAdminPolling();
}

// --- OZ SSE ---
function ozConnectSSE() {
  if (ozSseSource) { ozSseSource.close(); ozSseSource = null; }
  if (!shared.currentUser) return;
  const EVENTS_BASE = getEventsBase();
  ozSseSource = new EventSource(`${EVENTS_BASE}/events`, { withCredentials: true });
  ozSseSource.addEventListener('open', () => { ozState.sseConnected = true; render(); });
  ozSseSource.addEventListener('error', () => { ozState.sseConnected = false; });
  ozSseSource.addEventListener('assembly_update', () => {
    const user = shared.currentUser;
    if (!user) return;
    if (user.role === 'admin') {
      ozLoadAssemblies({ silent: true });
      if (ozState.selectedAssembly) {
        if (ozState.assemblyTab !== 'settings') ozLoadAssemblyOrders(ozState.selectedAssembly.id, { silent: true });
        ozLoadAssemblySettings(ozState.selectedAssembly.id, { silent: true, preserveEditorState: ozState.assemblyTab === 'settings' && (ozState.assemblyAccessDirty || ozState.settingsBusy), skipSync: ozState.assemblyTab === 'settings' });
      }
    }
    if (user.role === 'employee' && user.position !== 'collector') {
      if (!ozState.employeeSelectedAssembly) { ozLoadEmployeeAssemblies({ silent: true }); return; }
      if (Date.now() < ozRefs.liveRefreshBlockedUntil) return;
      ozLoadEmployeeAssemblySession(ozState.employeeSelectedAssembly.id, { silent: true }).then(sd => {
        const stage = sd?.workflow?.currentStage || '';
        if (stage === 'picking') { ozLoadEmployeePickItems(ozState.employeeSelectedAssembly.id, { silent: true }); return; }
        if (!ozState.employeeSelectedOrder) ozLoadEmployeeOrders(ozState.employeeSelectedAssembly.id, { silent: true });
      });
    }
  });
  ozSseSource.addEventListener('scan_issue_update', async () => {
    if (shared.currentUser?.role !== 'admin') return;
    const prevCount = ozState.scanIssues.length;
    await ozLoadScanIssues({ silent: true });
    if (ozState.scanIssues.length > prevCount) { showToast('Новая ошибка от упаковщицы (Ozon)', 'error'); playTone('error'); }
  });
  ozSseSource.addEventListener('scan_issue_fixed', (event) => {
    let payload = {};
    try { payload = JSON.parse(event.data || '{}'); } catch {}
    if (shared.currentUser?.role === 'admin') ozLoadScanIssues({ silent: true });
    if (shared.currentUser?.role === 'employee' && shared.currentUser?.position !== 'collector' && ozState.employeeSelectedAssembly) {
      if (payload?.issueStage === 'pick_scan') {
        const fixedId = Number(payload?.pickItemId);
        if (Number.isFinite(fixedId) && fixedId > 0) {
          ozState.employeePickItems = sortEmployeePickItems(ozState.employeePickItems.map(item => Number(item.id) === fixedId ? { ...item, bypassWithoutScanAllowed: true } : item));
        }
        ozState.employeeFlowNotice = 'Админ разрешил собрать товар без штрихкода — засчитываем автоматически.';
        render();
        ozAutoCollectBypassedPickItems();
        return;
      }
      ozLoadEmployeeOrders(ozState.employeeSelectedAssembly.id, { silent: true });
      ozLoadEmployeeAssemblySession(ozState.employeeSelectedAssembly.id, { silent: true });
      ozState.employeeIssueOpen = false; ozState.employeeIssueValue = ''; ozState.employeeIssueLineNos = [];
      ozState.employeeFlowNotice = 'Админ выполнил фикс. Можно продолжать сборку.';
      render();
    }
  });
}

function ozSuppressLiveRefresh(ms = 1200) { ozRefs.liveRefreshBlockedUntil = Date.now() + Math.max(0, Number(ms) || 0); }

// --- OZ Data Loading ---
async function ozLoadUsers() {
  const API_BASE = getApiBase();
  const user = shared.currentUser;
  if (!user) return;
  const isSuper = user.role === 'super_admin'; const isAdmin = user.role === 'admin';
  if (!isSuper && !isAdmin) return;
  ozState.usersLoading = true; ozState.usersError = ''; render();
  try {
    const roleFilter = isSuper ? (ozState.userTab === 'admins' ? 'admin' : 'employee') : 'employee';
    const roleParam = isSuper ? `?role=${roleFilter}` : '';
    const data = await fetchJson(`${API_BASE}/users${roleParam}`);
    ozState.users = Array.isArray(data?.users) ? data.users : [];
  } catch (err) { if (ozHandleAuthError(err)) return; ozState.usersError = 'Не удалось загрузить пользователей'; }
  finally { ozState.usersLoading = false; ozState.usersLoaded = true; render(); tryApplyPendingDeepRoute(); }
}
async function ozLoadUserDirectory() {
  const API_BASE = getApiBase();
  ozState.userDirectoryLoading = true; ozState.userDirectoryError = '';
  try {
    const data = await fetchJson(`${API_BASE}/users/directory?_=${Date.now()}`);
    ozState.userDirectory = Array.isArray(data?.users) ? data.users : [];
    const availableIds = new Set(getAvailableDirectoryUsers(ozState).map((entry) => String(entry?.externalUserId ?? entry?.id ?? '')));
    if (String(ozState.createExternalUserId || '').trim() && !availableIds.has(String(ozState.createExternalUserId))) {
      ozState.createExternalUserId = '';
    }
  }
  catch (err) { if (ozHandleAuthError(err)) return; ozState.userDirectoryError = err?.message || 'Не удалось загрузить'; }
  finally { ozState.userDirectoryLoading = false; render(); }
}
async function ozLoadNewOrders({ silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!ozState.storeId) return;
  let shouldRender = !silent;
  const prevNewError = ozState.newError;
  if (!silent) { ozState.newLoading = true; ozState.newError = ''; render(); }
  try {
    const data = await ozAdminFetch(`${API_BASE}/new-orders`);
    const nextOrders = Array.isArray(data?.orders) ? data.orders : [];
    const nextActiveWarehouses = Array.isArray(data?.warehouses) ? data.warehouses : ozBuildWarehouseOptionsFromOrders(nextOrders);
    shouldRender = assignIfChanged(ozState, 'newOrders', nextOrders) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'activeWarehouses', nextActiveWarehouses) || shouldRender;
    const validWarehouseIds = new Set(nextActiveWarehouses.map((item) => ozNormalizeWarehouseId(item?.warehouseId)).filter(Boolean));
    const nextCreateWarehouseId = (() => {
      const currentWarehouseId = ozNormalizeWarehouseId(ozState.createWarehouseId);
      if (currentWarehouseId && validWarehouseIds.has(currentWarehouseId)) return String(currentWarehouseId);
      if (validWarehouseIds.size === 1) return String(Array.from(validWarehouseIds)[0]);
      return '';
    })();
    shouldRender = assignIfChanged(ozState, 'createWarehouseId', nextCreateWarehouseId) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'newError', '') || shouldRender;
    if (!silent || shouldRender || !ozState.newUpdatedAt) ozState.newUpdatedAt = new Date();
  }
  catch (err) { if (ozHandleAuthError(err)) return; if (!silent || !ozState.newOrders.length) ozState.newError = err?.message || 'Ошибка'; }
  finally { if (!silent) ozState.newLoading = false; if (ozState.newError !== prevNewError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadAssemblies({ silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!ozState.storeId) return;
  let shouldRender = !silent;
  const prevAssembliesError = ozState.assembliesError;
  if (!silent) { ozState.assembliesLoading = true; ozState.assembliesError = ''; render(); }
  try {
    const data = await ozAdminFetch(`${API_BASE}/assemblies`);
    const nextAssemblies = Array.isArray(data?.assemblies) ? data.assemblies : [];
    shouldRender = assignIfChanged(ozState, 'assemblies', nextAssemblies) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assembliesError', '') || shouldRender;
    if (ozState.selectedAssembly) {
      const nextSelectedAssembly = nextAssemblies.find(a => a.id === ozState.selectedAssembly.id) || ozState.selectedAssembly;
      shouldRender = assignIfChanged(ozState, 'selectedAssembly', nextSelectedAssembly) || shouldRender;
    }
  } catch (err) { if (ozHandleAuthError(err)) return; if (!silent || !ozState.assemblies.length) ozState.assembliesError = err?.message || 'Ошибка'; }
  finally { ozState.assembliesLoaded = true; if (!silent) ozState.assembliesLoading = false; if (ozState.assembliesError !== prevAssembliesError) shouldRender = true; if (shouldRender) render(); tryApplyPendingDeepRoute(); }
}
async function ozLoadFbsStockCheck({ force = false, silent = false, progressOnly = false } = {}) {
  const API_BASE = getApiBase();
  if (!silent && !progressOnly) { ozState.fbsStockLoading = true; ozState.fbsStockError = ''; render(); }
  try {
    const params = new URLSearchParams();
    if (force) params.set('refresh', '1'); else if (progressOnly) params.set('progress', '1');
    const qs = params.toString();
    const data = await ozAdminFetch(`${API_BASE}/fbs-stock-check${qs ? `?${qs}` : ''}`);
    ozState.fbsStockItems = Array.isArray(data?.items) ? data.items : [];
    ozState.fbsStockScopeStores = (Array.isArray(data?.scopeStores) ? data.scopeStores : []).map(s => ({ id: String(s?.id || '').trim(), name: String(s?.name || s?.id || '').trim() })).filter(s => s.id);
    ozState.fbsStockWarehouseName = String(data?.warehouseName || 'Ижевск FBS');
    ozState.fbsStockTotals = { all: Number(data?.totals?.all || ozState.fbsStockItems.length || 0), ok: Number(data?.totals?.ok || 0), shortage: Number(data?.totals?.shortage || 0), errors: Number(data?.totals?.errors || 0) };
    ozState.fbsStockUpdatedAt = data?.updatedAt ? new Date(data.updatedAt) : null;
    const isRunning = Boolean(data?.running);
    const progress = normalizeFbsProgress({ ...(data?.progress || {}), running: isRunning }, isRunning);
    ozState.fbsStockProgress = progress; ozState.fbsStockRefreshing = isRunning || progress.running;
    if (data?.error && !isRunning && !hasUsableFbsStockResponse(data)) ozState.fbsStockError = String(data.error);
    else ozState.fbsStockError = '';
    ozSetupFbsStockPoll();
  } catch (err) {
    if (ozHandleAuthError(err)) return;
    if ((!silent || !progressOnly) && !hasUsableFbsStockState(ozState)) ozState.fbsStockError = err?.message || 'Ошибка';
    ozState.fbsStockRefreshing = false;
  }
  finally { if (!silent && !progressOnly) ozState.fbsStockLoading = false; render(); }
}
function ozSetupFbsStockPoll() {
  if (ozTimers.fbsStockPoll) { clearInterval(ozTimers.fbsStockPoll); ozTimers.fbsStockPoll = null; }
  if (ozState.fbsStockRefreshing) ozTimers.fbsStockPoll = setInterval(() => ozLoadFbsStockCheck({ silent: true, progressOnly: true }), 1500);
}
async function ozLoadStockProblems({ silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!silent) { ozState.stockProblemsLoading = true; ozState.stockProblemsError = ''; render(); }
  try { const data = await ozAdminFetch(`${API_BASE}/stock-problems`); ozState.stockProblems = { negativeShelves: Array.isArray(data?.negativeShelves) ? data.negativeShelves : [], negativeEmployees: Array.isArray(data?.negativeEmployees) ? data.negativeEmployees : [], leftoverEmployees: Array.isArray(data?.leftoverEmployees) ? data.leftoverEmployees : [] }; ozState.stockProblemsUpdatedAt = data?.generatedAt ? new Date(data.generatedAt) : null; }
  catch (err) { if (ozHandleAuthError(err)) return; if (!silent) ozState.stockProblemsError = err?.message || 'Ошибка'; }
  finally { if (!silent) ozState.stockProblemsLoading = false; render(); }
}
async function ozLoadAssemblyOrders(assemblyId, { silent = false, skipSync = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return [];
  let shouldRender = !silent;
  const prevAssemblyOrdersError = ozState.assemblyOrdersError;
  if (!silent) { ozState.assemblyOrdersLoading = true; ozState.assemblyOrdersError = ''; render(); }
  try {
    const params = new URLSearchParams();
    if (skipSync) params.set('skipSync', '1');
    const data = await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(assemblyId)}/orders${params.toString() ? `?${params.toString()}` : ''}`);
    shouldRender = assignIfChanged(ozState, 'assemblyOrders', Array.isArray(data?.orders) ? data.orders : []) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assemblyOrdersError', '') || shouldRender;
    // items tab shows per-item availability — refresh it once orders arrive
    if (ozState.assemblyTab === 'items' && ozState.assemblyOrders.length && (!ozState.assemblyStock || ozState.assemblyStock.loading !== true)) {
      ozLoadAssemblyStock();
    }
    return ozState.assemblyOrders;
  }
  catch (err) { if (ozHandleAuthError(err)) return []; ozState.assemblyOrdersError = err?.message || 'Ошибка'; return []; }
  finally { if (!silent) ozState.assemblyOrdersLoading = false; if (ozState.assemblyOrdersError !== prevAssemblyOrdersError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadAssemblySettings(assemblyId, { silent = false, preserveEditorState = false, skipSync = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return;
  let shouldRender = !silent;
  const prevAssemblySettingsError = ozState.assemblySettingsError;
  if (!silent) { ozState.assemblySettingsError = ''; render(); }
  try {
    const params = new URLSearchParams();
    if (skipSync) params.set('skipSync', '1');
    const data = await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(assemblyId)}/settings${params.toString() ? `?${params.toString()}` : ''}`);
    shouldRender = assignIfChanged(ozState, 'assemblySettings', data?.settings || null) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assemblyTotals', data?.totals || { total: 0, collected: 0, remaining: 0, readyToShip: 0 }) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assemblyEmployees', Array.isArray(data?.employees) ? data.employees : []) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assemblyProgress', Array.isArray(data?.progress) ? data.progress : []) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'assemblySettingsError', '') || shouldRender;
    if (!preserveEditorState || !ozState.assemblyAccessDirty) {
      const nextAccessUsers = (Array.isArray(data?.accessUserIds) ? data.accessUserIds : []).map(Number);
      shouldRender = assignIfChanged(ozState, 'accessUsers', nextAccessUsers) || shouldRender;
      shouldRender = assignIfChanged(ozState, 'accessMode', data?.settings?.accessMode === 'selected_split' ? 'selected_split' : 'hidden') || shouldRender;
      shouldRender = assignIfChanged(ozState, 'assemblyAssignmentPartsDraft', assignmentDraftFromServer(data?.settings?.assignmentParts || [], nextAccessUsers)) || shouldRender;
      if (ozState.assemblyAccessDirty) {
        ozState.assemblyAccessDirty = false;
        shouldRender = true;
      }
    }
  } catch (err) { if (ozHandleAuthError(err)) return; if (!silent) ozState.assemblySettingsError = err?.message || 'Ошибка'; }
  finally { if (ozState.assemblySettingsError !== prevAssemblySettingsError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadAssemblyLabelDiagnostics(assemblyId, { silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return null;
  if (!silent) { ozState.assemblyLabelDiagnosticsLoading = true; ozState.assemblyLabelDiagnosticsError = ''; render(); }
  try { const data = await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(assemblyId)}/labels/diagnostics`); ozState.assemblyLabelDiagnostics = data?.diagnostics || null; return data?.diagnostics || null; }
  catch (err) { if (ozHandleAuthError(err)) return null; if (!silent) ozState.assemblyLabelDiagnosticsError = err?.message || 'Ошибка'; return null; }
  finally { if (!silent) ozState.assemblyLabelDiagnosticsLoading = false; render(); }
}
async function ozLoadScanIssues({ silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!ozState.storeId) return [];
  let shouldRender = !silent;
  const prevScanIssuesError = ozState.scanIssuesError;
  if (!silent) { ozState.scanIssuesLoading = true; ozState.scanIssuesError = ''; render(); }
  try {
    const data = await ozAdminFetch(`${API_BASE}/settings/scan-issues`);
    shouldRender = assignIfChanged(ozState, 'scanIssues', Array.isArray(data?.issues) ? data.issues : []) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'scanIssuesError', '') || shouldRender;
    return ozState.scanIssues;
  }
  catch (err) { if (ozHandleAuthError(err)) return []; if (!silent) ozState.scanIssuesError = err?.message || 'Ошибка'; return []; }
  finally { if (!silent) ozState.scanIssuesLoading = false; if (ozState.scanIssuesError !== prevScanIssuesError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadEmployeeStats(user, { rangeKey, customFrom, customTo } = {}) {
  return loadUnifiedEmployeeStats(ozState, user, { rangeKey, customFrom, customTo });
  const API_BASE = getApiBase();
  if (!user?.id) return;
  const rk = rangeKey || ozState.employeeStatsRangeKey;
  const range = resolveStatsRange(rk, customFrom || ozState.employeeStatsCustomFrom, customTo || ozState.employeeStatsCustomTo);
  ozState.employeeStatsLoading = true; ozState.employeeStatsError = ''; render();
  try {
    const params = new URLSearchParams(); if (range.from) params.set('from', range.from); if (range.to) params.set('to', range.to);
    const data = await fetchJson(`${API_BASE}/users/${user.id}/stats${params.toString() ? '?' + params.toString() : ''}`);
    ozState.employeeStatsData = data || null;
  } catch (err) { if (ozHandleAuthError(err)) return; ozState.employeeStatsError = err?.message || 'Ошибка'; }
  finally { ozState.employeeStatsLoading = false; render(); }
}
async function ozLoadEmployeeAssemblies({ silent = false } = {}) {
  const API_BASE = getApiBase();
  let shouldRender = !silent;
  const prevEmployeeAssembliesError = ozState.employeeAssembliesError;
  if (!silent) { ozState.employeeAssembliesLoading = true; ozState.employeeAssembliesError = ''; render(); }
  try {
    const data = await fetchJson(`${API_BASE}/employee/assemblies`);
    const nextAssemblies = Array.isArray(data?.assemblies) ? data.assemblies : [];
    shouldRender = assignIfChanged(ozState, 'employeeAssemblies', nextAssemblies) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'employeeAssembliesError', '') || shouldRender;
    if (ozState.employeeSelectedAssembly) {
      const nextSelectedAssembly = nextAssemblies.find(a => a.id === ozState.employeeSelectedAssembly.id) || ozState.employeeSelectedAssembly;
      shouldRender = assignIfChanged(ozState, 'employeeSelectedAssembly', nextSelectedAssembly) || shouldRender;
    }
  }
  catch (err) { if (ozHandleAuthError(err)) return; ozState.employeeAssembliesError = err?.message || 'Ошибка'; }
  finally { if (!silent) ozState.employeeAssembliesLoading = false; if (ozState.employeeAssembliesError !== prevEmployeeAssembliesError) shouldRender = true; if (shouldRender) render(); }
}
const OZ_COMPLETED_ORDER_TOMBSTONE_MS = 10 * 60 * 1000;

function ozEmployeeCompletedOrderKey(assemblyId, postingNumber) {
  return `${String(assemblyId || '')}::${String(postingNumber || '')}`;
}

function ozEmployeeRememberCompletedOrder(assemblyId, postingNumber) {
  if (!assemblyId || !postingNumber) return;
  const now = Date.now();
  const next = {};
  for (const [key, completedAt] of Object.entries(ozState.employeeCompletedOrderTombstones || {})) {
    if (now - Number(completedAt || 0) < OZ_COMPLETED_ORDER_TOMBSTONE_MS) next[key] = completedAt;
  }
  next[ozEmployeeCompletedOrderKey(assemblyId, postingNumber)] = now;
  ozState.employeeCompletedOrderTombstones = next;
}

function ozEmployeeFilterRecentlyCompletedOrders(assemblyId, orders) {
  const now = Date.now();
  const tombstones = ozState.employeeCompletedOrderTombstones || {};
  return (Array.isArray(orders) ? orders : []).filter((order) => {
    const completedAt = Number(tombstones[ozEmployeeCompletedOrderKey(assemblyId, order?.postingNumber)] || 0);
    return !completedAt || now - completedAt >= OZ_COMPLETED_ORDER_TOMBSTONE_MS;
  });
}

async function ozLoadEmployeeOrders(assemblyId, { silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return;
  const requestSeq = Number(ozState.employeeOrdersRequestSeq || 0) + 1;
  ozState.employeeOrdersRequestSeq = requestSeq;
  let shouldRender = !silent;
  const prevEmployeeOrdersError = ozState.employeeOrdersError;
  if (!silent) { ozState.employeeOrdersLoading = true; ozState.employeeOrdersError = ''; render(); }
  try {
    const data = await fetchJson(`${API_BASE}/employee/assemblies/${encodeURIComponent(assemblyId)}/orders`);
    if (requestSeq !== ozState.employeeOrdersRequestSeq) return ozState.employeeOrders;
    if (ozState.employeeSelectedAssembly && String(ozState.employeeSelectedAssembly.id) !== String(assemblyId)) {
      return ozState.employeeOrders;
    }
    const nextOrders = ozEmployeeFilterRecentlyCompletedOrders(assemblyId, data?.orders);
    shouldRender = assignIfChanged(ozState, 'employeeOrders', nextOrders) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'employeeOrdersError', '') || shouldRender;
    if (ozState.employeeSelectedOrder) {
      const nextSelectedOrder = nextOrders.find(o => o.postingNumber === ozState.employeeSelectedOrder.postingNumber) || null;
      shouldRender = assignIfChanged(ozState, 'employeeSelectedOrder', nextSelectedOrder) || shouldRender;
    }
    return ozState.employeeOrders;
  } catch (err) { if (ozHandleAuthError(err)) return []; ozState.employeeOrdersError = err?.message || 'Ошибка'; return []; }
  finally {
    if (requestSeq !== ozState.employeeOrdersRequestSeq) return;
    if (!silent) ozState.employeeOrdersLoading = false;
    if (ozState.employeeOrdersError !== prevEmployeeOrdersError) shouldRender = true;
    if (shouldRender) render();
  }
}
async function ozLoadEmployeeAssemblySession(assemblyId, { silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return null;
  let shouldRender = !silent;
  const prevEmployeeAssemblySessionError = ozState.employeeAssemblySessionError;
  if (!silent) { ozState.employeeAssemblySessionLoading = true; ozState.employeeAssemblySessionError = ''; ozState.employeeStartError = ''; render(); }
  try {
    const data = await fetchJson(`${API_BASE}/employee/assemblies/${encodeURIComponent(assemblyId)}/session`);
    shouldRender = ozEmployeeApplySessionData(assemblyId, data || null) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'employeeAssemblySessionError', '') || shouldRender;
    return data || null;
  }
  catch (err) { if (ozHandleAuthError(err)) return null; if (!silent) ozState.employeeAssemblySessionError = err?.message || 'Ошибка'; return null; }
  finally { if (!silent) ozState.employeeAssemblySessionLoading = false; if (ozState.employeeAssemblySessionError !== prevEmployeeAssemblySessionError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadEmployeePickItems(assemblyId, { silent = false } = {}) {
  const API_BASE = getApiBase();
  if (!assemblyId) return [];
  let shouldRender = !silent;
  const prevEmployeePickItemsError = ozState.employeePickItemsError;
  if (!silent) { ozState.employeePickItemsLoading = true; ozState.employeePickItemsError = ''; render(); }
  try {
    const data = await fetchJson(`${API_BASE}/employee/assemblies/${encodeURIComponent(assemblyId)}/pick-items`);
    shouldRender = assignIfChanged(ozState, 'employeePickItems', sortEmployeePickItems(Array.isArray(data?.items) ? data.items : [])) || shouldRender;
    if (data?.session) {
      shouldRender = ozEmployeeApplySessionData(assemblyId, {
        ...(ozState.employeeAssemblySession || {}),
        session: data.session,
      }) || shouldRender;
    }
    shouldRender = assignIfChanged(ozState, 'employeePickItemsError', '') || shouldRender;
    setTimeout(() => ozAutoCollectBypassedPickItems(), 0);
    return ozState.employeePickItems;
  }
  catch (err) { if (ozHandleAuthError(err)) return []; if (!silent) ozState.employeePickItemsError = err?.message || 'Ошибка'; return []; }
  finally { if (!silent) ozState.employeePickItemsLoading = false; if (ozState.employeePickItemsError !== prevEmployeePickItemsError) shouldRender = true; if (shouldRender) render(); }
}
async function ozLoadCollectorAssemblies({ silent = false } = {}) {
  const API_BASE = getApiBase();
  let shouldRender = !silent;
  const prevCollectorError = ozState.collectorError;
  if (!silent) { ozState.collectorLoading = true; ozState.collectorError = ''; render(); }
  try {
    const data = await fetchJson(`${API_BASE}/employee/collector/assemblies`);
    shouldRender = assignIfChanged(ozState, 'collectorAssemblies', Array.isArray(data?.assemblies) ? data.assemblies : []) || shouldRender;
    shouldRender = assignIfChanged(ozState, 'collectorError', '') || shouldRender;
  }
  catch (err) { if (err?.status === 401) return; ozState.collectorError = err?.message || 'Ошибка'; }
  finally { if (!silent) ozState.collectorLoading = false; if (ozState.collectorError !== prevCollectorError) shouldRender = true; if (shouldRender) render(); }
}

// --- OZ Polling ---
function ozSetupAdminPolling() {
  ozCleanupTimers();
  ozTimers.newOrders = setInterval(() => ozLoadNewOrders({ silent: true }), 20000);
  ozTimers.assemblies = setInterval(() => {
    ozLoadAssemblies({ silent: true });
    ozLoadScanIssues({ silent: true });
    if (ozState.selectedAssembly) {
      ozLoadAssemblySettings(ozState.selectedAssembly.id, { silent: true, preserveEditorState: ozState.assemblyTab === 'settings' && (ozState.assemblyAccessDirty || ozState.settingsBusy), skipSync: ozState.assemblyTab === 'settings' });
      if (ozState.assemblyTab !== 'settings') ozLoadAssemblyOrders(ozState.selectedAssembly.id, { silent: true });
    }
  }, 15000);
}
function ozSetupEmployeePolling() {
  ozCleanupTimers();
  ozTimers.employee = setInterval(() => {
    if (!ozState.employeeSelectedAssembly) { ozLoadEmployeeAssemblies({ silent: true }); return; }
    if (Date.now() < ozRefs.liveRefreshBlockedUntil) return;
    ozLoadEmployeeAssemblySession(ozState.employeeSelectedAssembly.id, { silent: true }).then(sd => {
      const stage = sd?.workflow?.currentStage || '';
      if (stage === 'picking') { ozLoadEmployeePickItems(ozState.employeeSelectedAssembly.id, { silent: true }); return; }
      if (ozState.employeeSelectedOrder) return;
      ozLoadEmployeeOrders(ozState.employeeSelectedAssembly.id, { silent: true });
    });
  }, 12000);
}
function ozSetupCollectorPolling() {
  ozCleanupTimers();
  ozTimers.collector = setInterval(() => ozLoadCollectorAssemblies({ silent: true }), 12000);
}
function ozCleanupTimers() {
  Object.keys(ozTimers).forEach(key => { if (ozTimers[key]) { clearInterval(ozTimers[key]); clearTimeout(ozTimers[key]); ozTimers[key] = null; } });
}

// --- OZ Render (delegates to main render which checks marketplace) ---
// OZ rendering is embedded in the main render function below.
// We define ozRender() to produce the full OZ interface HTML.

// ================================================================
// SHARED: Employee Stats Modal (used by both OZ and WB)
// ================================================================

function renderEmployeeStatsModal(stateObj) {
  const emp = stateObj.employeeStatsUser;
  if (!emp) return '';
  const data = stateObj.employeeStatsData;
  const stats = data?.stats || {};
  const today = stats.today || {}, period = stats.period || {}, allTime = stats.allTime || {};
  const summary = stats.summary || {};
  const daily = Array.isArray(stats.daily) ? stats.daily : [];
  const sessions = Array.isArray(stats.sessions) ? stats.sessions : [];
  const periodOrders = Number(period.orders || 0), periodPicked = Number(period.pickedItems || 0);
  const todayOrders = Number(today.orders || 0), todayPicked = Number(today.pickedItems || 0);
  const allOrders = Number(allTime.orders || 0), allPicked = Number(allTime.pickedItems || 0);
  const periodPackedItems = Number(period.packedItems || period.packed || 0);
  const periodErrors = Number(period.errors || period.scanIssues || 0);
  const periodSessions = Number(period.assemblies || period.sessions || 0);
  const pickingStats = stats.picking || period.picking || {};
  const packingStats = stats.packing || period.packing || {};

  // Average times
  const todayAvg = Number(today.avgSecondsPerOrder || today.avgSeconds || 0);
  const periodAvg = Number(period.avgSecondsPerOrder || period.avgSeconds || 0);
  const allAvg = Number(allTime.avgSecondsPerOrder || allTime.avgSeconds || 0);

  // Range selector
  const rangeKey = stateObj.employeeStatsRangeKey;
  const rangeButtons = ['today', '7d', '30d', 'month', 'custom'].map(k => {
    const labels = { today: '\u0421\u0435\u0433\u043E\u0434\u043D\u044F', '7d': '7 \u0434\u043D\u0435\u0439', '30d': '30 \u0434\u043D\u0435\u0439', month: '\u041C\u0435\u0441\u044F\u0446', custom: '\u0421\u0432\u043E\u0439 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D' };
    return `<button class="chip ${rangeKey === k ? 'active' : ''}" data-stats-range="${k}">${labels[k]}</button>`;
  }).join('');

  const customInputs = rangeKey === 'custom' ? `<div class="stats-range-inline" style="display:inline-flex;gap:6px;margin-left:8px;align-items:center"><input class="input" type="date" id="stats-from" value="${esc(stateObj.employeeStatsCustomFrom)}" style="width:140px" /><input class="input" type="date" id="stats-to" value="${esc(stateObj.employeeStatsCustomTo)}" style="width:140px" /><button class="btn btn-primary btn-sm" id="btn-stats-apply">\u041F\u0420\u0418\u041C\u0415\u041D\u0418\u0422\u042C</button></div>` : '';

  // Hero section
  const heroHtml = `<div class="stats-hero" style="text-align:center;padding:16px 0;border-bottom:1px solid #333">
    <div style="font-size:20px;font-weight:700;color:#0f0">${periodOrders} \u0437\u0430\u043A\u0430\u0437\u043E\u0432 \u0438 ${periodPicked} \u0442\u043E\u0432\u0430\u0440\u043E\u0432</div>
    <div class="hint" style="margin-top:4px">${formatDurationLong(period.totalSeconds)} \u2022 ${periodSessions} \u0441\u0435\u0441\u0441\u0438\u0439</div>
    <div style="display:flex;justify-content:center;gap:24px;margin-top:12px">
      <div><div class="hint">\u0421\u0440\u0435\u0434\u043D\u0435\u0435 \u0441\u0435\u0433\u043E\u0434\u043D\u044F</div><div style="font-size:14px;font-weight:600">${todayAvg > 0 ? formatDuration(todayAvg) : '\u2014'}</div></div>
      <div><div class="hint">\u0421\u0440\u0435\u0434\u043D\u0435\u0435 \u0437\u0430 \u043F\u0435\u0440\u0438\u043E\u0434</div><div style="font-size:14px;font-weight:600">${periodAvg > 0 ? formatDuration(periodAvg) : '\u2014'}</div></div>
      <div><div class="hint">\u0421\u0440\u0435\u0434\u043D\u0435\u0435 \u0432\u0441\u0435\u0433\u043E</div><div style="font-size:14px;font-weight:600">${allAvg > 0 ? formatDuration(allAvg) : '\u2014'}</div></div>
    </div>
  </div>`;

  // Summary grid: today / period / all-time
  const summaryHtml = `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:12px 0;border-bottom:1px solid #333">
    <div style="background:#1a1a2e;padding:12px;border-radius:6px;border-left:3px solid #00bcd4">
      <div style="font-size:11px;color:#888;text-transform:uppercase">\u0421\u0435\u0433\u043E\u0434\u043D\u044F</div>
      <div style="font-size:18px;font-weight:700;margin:4px 0">${todayOrders} \u0437\u0430\u043A\u0430\u0437\u043E\u0432</div>
      <div style="font-size:12px;color:#aaa">\u0422\u043E\u0432\u0430\u0440: ${todayPicked} \u0448\u0442</div>
      <div style="font-size:12px;color:#aaa">\u0412\u0440\u0435\u043C\u044F: ${formatDuration(today.totalSeconds || 0)}</div>
    </div>
    <div style="background:#1a2e1a;padding:12px;border-radius:6px;border-left:3px solid #4caf50">
      <div style="font-size:11px;color:#888;text-transform:uppercase">\u041F\u0435\u0440\u0438\u043E\u0434</div>
      <div style="font-size:18px;font-weight:700;margin:4px 0">${periodOrders} \u0437\u0430\u043A\u0430\u0437\u043E\u0432</div>
      <div style="font-size:12px;color:#aaa">\u0422\u043E\u0432\u0430\u0440: ${periodPicked} \u0448\u0442</div>
      <div style="font-size:12px;color:#aaa">\u0412\u0440\u0435\u043C\u044F: ${formatDuration(period.totalSeconds || 0)}</div>
    </div>
    <div style="background:#2e2e1a;padding:12px;border-radius:6px;border-left:3px solid #ff9800">
      <div style="font-size:11px;color:#888;text-transform:uppercase">\u0412\u0441\u0435 \u0432\u0440\u0435\u043C\u044F</div>
      <div style="font-size:18px;font-weight:700;margin:4px 0">${allOrders} \u0437\u0430\u043A\u0430\u0437\u043E\u0432</div>
      <div style="font-size:12px;color:#aaa">\u0422\u043E\u0432\u0430\u0440: ${allPicked} \u0448\u0442</div>
      <div style="font-size:12px;color:#aaa">\u0412\u0440\u0435\u043C\u044F: ${formatDuration(allTime.totalSeconds || 0)}</div>
    </div>
  </div>`;

  // Totals row: picked / packed / errors
  const totalsHtml = `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:12px 0;border-bottom:1px solid #333">
    <div style="text-align:center"><div class="hint">\u0421\u043E\u0431\u0440\u0430\u043D\u043E \u0442\u043E\u0432\u0430\u0440\u043E\u0432</div><div style="font-size:22px;font-weight:700;color:#4caf50">${Number(summary.totalPickedItems || periodPicked)}</div></div>
    <div style="text-align:center"><div class="hint">\u0423\u043F\u0430\u043A\u043E\u0432\u0430\u043D\u043E</div><div style="font-size:22px;font-weight:700;color:#2196f3">${Number(summary.totalPackedItems || periodPackedItems)}</div></div>
    <div style="text-align:center"><div class="hint">\u041E\u0448\u0438\u0431\u043A\u0438</div><div style="font-size:22px;font-weight:700;color:${periodErrors > 0 ? '#f44336' : '#888'}">${periodErrors}</div></div>
  </div>`;

  // Average time section
  const avgTimeHtml = `<div style="padding:12px 0;border-bottom:1px solid #333">
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">\u0421\u0440\u0435\u0434\u043D\u0435\u0435 \u0432\u0440\u0435\u043C\u044F</div>
    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">
      <div><span class="hint">\u041D\u0430 \u0437\u0430\u043A\u0430\u0437:</span> <strong>${periodOrders > 0 ? formatDuration(Number(period.totalSeconds || 0) / periodOrders) : '\u2014'}</strong></div>
      <div><span class="hint">\u041D\u0430 \u0442\u043E\u0432\u0430\u0440:</span> <strong>${periodPicked > 0 ? formatDuration(Number(period.totalSeconds || 0) / periodPicked) : '\u2014'}</strong></div>
      <div><span class="hint">\u0417\u0430\u043A\u0430\u0437\u043E\u0432/\u0447\u0430\u0441:</span> <strong>${formatUnitsPerHour(periodOrders, period.totalSeconds, '\u0437\u0430\u043A')}</strong></div>
      <div><span class="hint">\u0422\u043E\u0432\u0430\u0440\u043E\u0432/\u0447\u0430\u0441:</span> <strong>${formatUnitsPerHour(periodPicked, period.totalSeconds, '\u0448\u0442')}</strong></div>
    </div>
  </div>`;

  // Picking stage card
  const pickOrders = Number(pickingStats.orders || 0);
  const pickItems = Number(pickingStats.items || pickingStats.pickedItems || 0);
  const pickSeconds = Number(pickingStats.totalSeconds || 0);
  const pickingHtml = pickOrders > 0 || pickItems > 0 ? `<div style="background:#1a1a2e;padding:12px;border-radius:6px;margin-top:12px;border-left:3px solid #9c27b0">
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">\u0421\u0431\u043E\u0440\u043A\u0430 \u0442\u043E\u0432\u0430\u0440\u0430 (picking)</div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;font-size:12px">
      <div><span class="hint">\u0422\u043E\u0432\u0430\u0440\u043E\u0432:</span> <strong>${pickItems}</strong></div>
      <div><span class="hint">\u0412\u0440\u0435\u043C\u044F:</span> <strong>${formatDuration(pickSeconds)}</strong></div>
      <div><span class="hint">\u0421\u0440\u0435\u0434\u043D\u0435\u0435:</span> <strong>${pickItems > 0 ? formatDuration(pickSeconds / pickItems) + '/\u0448\u0442' : '\u2014'}</strong></div>
    </div>
  </div>` : '';

  // Packing stage card
  const packOrders = Number(packingStats.orders || 0);
  const packItems = Number(packingStats.items || packingStats.packedItems || 0);
  const packSeconds = Number(packingStats.totalSeconds || 0);
  const packingHtml = packOrders > 0 || packItems > 0 ? `<div style="background:#1a2e1a;padding:12px;border-radius:6px;margin-top:12px;border-left:3px solid #2196f3">
    <div style="font-size:13px;font-weight:600;margin-bottom:8px">\u0423\u043F\u0430\u043A\u043E\u0432\u043A\u0430 (packing)</div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;font-size:12px">
      <div><span class="hint">\u0417\u0430\u043A\u0430\u0437\u043E\u0432:</span> <strong>${packOrders}</strong></div>
      <div><span class="hint">\u0412\u0440\u0435\u043C\u044F:</span> <strong>${formatDuration(packSeconds)}</strong></div>
      <div><span class="hint">\u0421\u0440\u0435\u0434\u043D\u0435\u0435:</span> <strong>${packOrders > 0 ? formatDuration(packSeconds / packOrders) + '/\u0437\u0430\u043A' : '\u2014'}</strong></div>
    </div>
  </div>` : '';

  // Daily activity chart
  let dailyHtml = '';
  if (daily.length > 0) {
    const maxCount = Math.max(1, ...daily.map(d => Math.max(Number(d.orders || 0), Number(d.pickedItems || d.items || 0))));
    dailyHtml = `<div style="padding:12px 0;border-bottom:1px solid #333">
      <div style="font-size:13px;font-weight:600;margin-bottom:8px">\u0410\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u044C \u043F\u043E \u0434\u043D\u044F\u043C</div>
      <div style="display:flex;gap:2px;align-items:end;height:80px">
        ${daily.map(d => {
          const orders = Number(d.orders || 0);
          const items = Number(d.pickedItems || d.items || 0);
          const hOrders = Math.max(2, (orders / maxCount) * 70);
          const hItems = Math.max(2, (items / maxCount) * 70);
          const dateLabel = d.date ? formatShortDate(d.date + 'T00:00:00') : '';
          return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:1px" title="${dateLabel}: ${orders} \u0437\u0430\u043A, ${items} \u0448\u0442">
            <div style="display:flex;gap:1px;align-items:end;width:100%;justify-content:center">
              <div style="width:45%;height:${hOrders}px;background:#4caf50;border-radius:2px 2px 0 0;min-width:3px"></div>
              <div style="width:45%;height:${hItems}px;background:#2196f3;border-radius:2px 2px 0 0;min-width:3px"></div>
            </div>
            <div style="font-size:9px;color:#666;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;width:100%;text-align:center">${dateLabel}</div>
          </div>`;
        }).join('')}
      </div>
      <div style="display:flex;gap:12px;margin-top:4px;font-size:10px;color:#888"><span>\u25A0 <span style="color:#4caf50">\u0417\u0430\u043A\u0430\u0437\u044B</span></span><span>\u25A0 <span style="color:#2196f3">\u0422\u043E\u0432\u0430\u0440\u044B</span></span></div>
    </div>`;
  }

  // Session history
  let sessionsHtml = '';
  if (sessions.length > 0) {
    sessionsHtml = `<div style="padding:12px 0">
      <div style="font-size:13px;font-weight:600;margin-bottom:8px">\u0418\u0441\u0442\u043E\u0440\u0438\u044F \u0441\u0435\u0441\u0441\u0438\u0439 (${sessions.length})</div>
      <div style="max-height:300px;overflow-y:auto">
        ${sessions.map(s => {
          const sOrders = Number(s.orders || s.orderCount || 0);
          const sItems = Number(s.pickedItems || s.items || s.itemCount || 0);
          const sDuration = Number(s.totalSeconds || s.durationSeconds || 0);
          const sDate = s.date || s.startedAt || s.createdAt || '';
          const sName = s.assemblyName || s.supplyName || s.name || '';
          return `<div style="background:#111;border:1px solid #333;border-radius:6px;padding:10px;margin-bottom:6px">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div><strong>${esc(sName || '\u0421\u0435\u0441\u0441\u0438\u044F')}</strong>${sDate ? ` <span class="hint">${formatShortDate(sDate)}</span>` : ''}</div>
              <div style="font-size:12px;color:#888">${formatDuration(sDuration)}</div>
            </div>
            <div style="display:flex;gap:16px;margin-top:6px;font-size:12px;color:#aaa">
              <span>\u0417\u0430\u043A\u0430\u0437\u044B: ${sOrders}</span>
              <span>\u0422\u043E\u0432\u0430\u0440\u044B: ${sItems}</span>
              ${sOrders > 0 && sDuration > 0 ? `<span>\u0421\u0440\u0435\u0434\u043D\u0435\u0435: ${formatDuration(sDuration / sOrders)}/\u0437\u0430\u043A</span>` : ''}
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }

  const bodyContent = stateObj.employeeStatsLoading
    ? '<div class="hint" style="text-align:center;padding:40px">\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430...</div>'
    : stateObj.employeeStatsError
      ? `<div class="alert alert-error">${esc(stateObj.employeeStatsError)}</div>`
      : `${heroHtml}${summaryHtml}${totalsHtml}${avgTimeHtml}${pickingHtml}${packingHtml}${dailyHtml}${sessionsHtml}`;

  return `<div class="modal-overlay" id="modal-stats" style="position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:1000;display:flex;align-items:center;justify-content:center">
    <div class="modal-panel wide" style="background:#0a0a0a;border:1px solid #333;border-radius:8px;max-width:720px;width:95%;max-height:90vh;display:flex;flex-direction:column" onclick="event.stopPropagation()">
      <div class="modal-header" style="display:flex;justify-content:space-between;align-items:center;padding:16px;border-bottom:1px solid #333">
        <div>
          <div class="modal-title" style="font-size:16px;font-weight:700">${esc(emp.surname || emp.fullName || '')} ${esc(emp.name || '')}</div>
          <div class="modal-subtitle" style="font-size:12px;color:#888">\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430 \u2022 ${esc(data?.timezone || 'Europe/Moscow')}</div>
        </div>
        <button class="btn-icon" id="btn-close-stats" style="font-size:20px;background:none;border:none;color:#888;cursor:pointer">&times;</button>
      </div>
      <div class="stats-toolbar" style="padding:8px 16px;border-bottom:1px solid #333;display:flex;flex-wrap:wrap;gap:6px;align-items:center">
        ${rangeButtons}${customInputs}
      </div>
      <div class="modal-body" style="padding:16px;overflow-y:auto;flex:1">
        ${bodyContent}
      </div>
    </div>
  </div>`;
}

function buildEmployeeStatsRange(rangeKey, customFrom, customTo) {
  const today = getMoscowDateString();
  let fromDate = customFrom;
  let toDate = customTo;
  if (rangeKey === 'today') {
    fromDate = today;
    toDate = today;
  } else if (rangeKey === '7d') {
    fromDate = shiftDateString(today, -6);
    toDate = today;
  } else if (rangeKey === '30d') {
    fromDate = shiftDateString(today, -29);
    toDate = today;
  } else if (rangeKey === 'month') {
    const parts = today.split('-');
    fromDate = `${parts[0]}-${parts[1]}-01`;
    toDate = today;
  }
  if (!fromDate || !toDate) return { fromMs: null, toMs: null };
  const from = new Date(`${fromDate}T00:00:00${MOSCOW_OFFSET}`);
  const to = new Date(`${shiftDateString(toDate, 1)}T00:00:00${MOSCOW_OFFSET}`);
  return {
    fromMs: Number.isNaN(from.getTime()) ? null : from.getTime(),
    toMs: Number.isNaN(to.getTime()) ? null : to.getTime(),
  };
}

function employeeStatsHasPickingActivity(session) {
  return (
    Number(session?.pickingCollectedQty || 0) > 0 ||
    Number(session?.pickingTotalSeconds || 0) > 0 ||
    Boolean(session?.pickingStartedAt)
  );
}

function employeeStatsHasPackingActivity(session) {
  return (
    Number(session?.collectedOrderCount || 0) > 0 ||
    Number(session?.packingTotalSeconds || 0) > 0 ||
    Boolean(session?.startedAt)
  );
}

function employeeStatsSessionFitsRange(session, range) {
  if (!range?.fromMs || !range?.toMs) return true;
  const candidates = [session?.startedAt, session?.pickingStartedAt, session?.assignedAt]
    .map(value => new Date(value || '').getTime())
    .filter(value => Number.isFinite(value));
  if (!candidates.length) return false;
  return candidates.some(value => value >= range.fromMs && value < range.toMs);
}

function employeeStatsStatusLabel(session) {
  if (session?.status === 'finished') return 'Завершена';
  if (session?.status === 'started') return 'В работе';
  if (session?.status === 'cancelled') return 'Остановлена';
  if (session?.status === 'assigned') return 'Назначена';
  return session?.status || '—';
}

function employeeStatsMarketplaceMeta(stateObj) {
  const isWb = stateObj === wbState;
  return {
    isWb,
    entitySingular: isWb ? 'Поставка' : 'Сборка',
    entityPlural: isWb ? 'поставок' : 'сборок',
    entityIdKey: isWb ? 'supplyId' : 'assemblyId',
    entityNameKey: isWb ? 'supplyName' : 'assemblyName',
    periodCountKey: isWb ? 'supplies' : 'assemblies',
  };
}

function employeeStatsRoleLabel(user) {
  return user?.position === 'collector' ? 'Сборщик' : 'Упаковщик';
}

function employeeStatsSiteLabel(marketplace) {
  return marketplace === 'wb' ? 'WB' : 'OZON';
}

function employeeStatsSiteMeta(marketplace) {
  const isWb = marketplace === 'wb';
  return {
    marketplace,
    marketplaceLabel: employeeStatsSiteLabel(marketplace),
    entitySingular: isWb ? 'Поставка' : 'Сборка',
    entityPlural: isWb ? 'поставок' : 'сборок',
    entityIdKey: isWb ? 'supplyId' : 'assemblyId',
    entityNameKey: isWb ? 'supplyName' : 'assemblyName',
    periodCountKey: isWb ? 'supplies' : 'assemblies',
  };
}

function normalizeEmployeeStatsBlock(block = {}) {
  return {
    assemblies: Number(block?.assemblies || 0),
    supplies: Number(block?.supplies || 0),
    sessions: Number(block?.sessions || 0),
    orders: Number(block?.orders || 0),
    pickedItems: Number(block?.pickedItems || 0),
    totalSeconds: Number(block?.totalSeconds || 0),
    packingSeconds: Number(block?.packingSeconds || 0),
    pickingSeconds: Number(block?.pickingSeconds || 0),
    avgSecondsPerOrder: Number(block?.avgSecondsPerOrder || 0),
    avgPickSecondsPerItem: Number(block?.avgPickSecondsPerItem || 0),
  };
}

function normalizeEmployeeStatsSession(session, marketplace) {
  const meta = employeeStatsSiteMeta(marketplace);
  const entityId = session?.[meta.entityIdKey];
  return {
    ...session,
    marketplace,
    marketplaceLabel: meta.marketplaceLabel,
    entityId,
    entityName: session?.[meta.entityNameKey] || `${meta.entitySingular} ${entityId || '—'}`,
    entitySingular: meta.entitySingular,
    entityPlural: meta.entityPlural,
    sessionSortAt:
      session?.finishedAt ||
      session?.startedAt ||
      session?.pickingFinishedAt ||
      session?.pickingStartedAt ||
      session?.assignedAt ||
      '',
  };
}

function emptyUnifiedEmployeeStatsSource(marketplace, user, range) {
  return {
    marketplace,
    marketplaceLabel: employeeStatsSiteLabel(marketplace),
    timezone: 'Europe/Moscow',
    range: range || { from: null, to: null },
    user: user || null,
    stats: {
      today: normalizeEmployeeStatsBlock(),
      period: normalizeEmployeeStatsBlock(),
      allTime: normalizeEmployeeStatsBlock(),
      sessions: [],
      daily: [],
    },
  };
}

function normalizeEmployeeStatsSource(data, marketplace, user, range) {
  const fallback = emptyUnifiedEmployeeStatsSource(marketplace, user, range);
  const stats = data?.stats || {};
  return {
    marketplace,
    marketplaceLabel: employeeStatsSiteLabel(marketplace),
    timezone: data?.timezone || fallback.timezone,
    range: data?.range || fallback.range,
    user: data?.user || user || null,
    stats: {
      today: normalizeEmployeeStatsBlock(stats?.today),
      period: normalizeEmployeeStatsBlock(stats?.period),
      allTime: normalizeEmployeeStatsBlock(stats?.allTime),
      sessions: (Array.isArray(stats?.sessions) ? stats.sessions : []).map(session => normalizeEmployeeStatsSession(session, marketplace)),
      daily: Array.isArray(stats?.daily) ? stats.daily : [],
    },
  };
}

function mergeEmployeeStatsBlocks(...blocks) {
  const merged = {
    assemblies: 0,
    supplies: 0,
    sessions: 0,
    orders: 0,
    pickedItems: 0,
    totalSeconds: 0,
    packingSeconds: 0,
    pickingSeconds: 0,
    avgSecondsPerOrder: 0,
    avgPickSecondsPerItem: 0,
  };
  blocks.filter(Boolean).forEach((block) => {
    const normalized = normalizeEmployeeStatsBlock(block);
    merged.assemblies += normalized.assemblies;
    merged.supplies += normalized.supplies;
    merged.sessions += normalized.sessions;
    merged.orders += normalized.orders;
    merged.pickedItems += normalized.pickedItems;
    merged.totalSeconds += normalized.totalSeconds;
    merged.packingSeconds += normalized.packingSeconds;
    merged.pickingSeconds += normalized.pickingSeconds;
  });
  merged.avgSecondsPerOrder = merged.orders > 0 && merged.packingSeconds > 0 ? Math.round(merged.packingSeconds / merged.orders) : 0;
  merged.avgPickSecondsPerItem = merged.pickedItems > 0 && merged.pickingSeconds > 0 ? Math.round(merged.pickingSeconds / merged.pickedItems) : 0;
  return merged;
}

function buildUnifiedEmployeeStatsData(user, range, sources, partialErrors = []) {
  const oz = normalizeEmployeeStatsSource(sources?.oz, 'oz', user, range);
  const wb = normalizeEmployeeStatsSource(sources?.wb, 'wb', user, range);
  const combinedSessions = [...oz.stats.sessions, ...wb.stats.sessions]
    .sort((a, b) => new Date(b?.sessionSortAt || 0).getTime() - new Date(a?.sessionSortAt || 0).getTime());

  return {
    user: user || null,
    timezone: oz.timezone || wb.timezone || 'Europe/Moscow',
    range: range || { from: null, to: null },
    partialErrors,
    sources: { oz, wb },
    combined: {
      period: mergeEmployeeStatsBlocks(oz.stats.period, wb.stats.period),
      today: mergeEmployeeStatsBlocks(oz.stats.today, wb.stats.today),
      allTime: mergeEmployeeStatsBlocks(oz.stats.allTime, wb.stats.allTime),
    },
    sessions: combinedSessions,
  };
}

async function loadUnifiedEmployeeStats(stateObj, user, { rangeKey, customFrom, customTo } = {}) {
  if (!user?.id) return;
  const rk = rangeKey || stateObj.employeeStatsRangeKey;
  const resolvedRange = resolveStatsRange(rk, customFrom || stateObj.employeeStatsCustomFrom, customTo || stateObj.employeeStatsCustomTo);
  const range = { from: resolvedRange.from || null, to: resolvedRange.to || null };
  const requestId = Number(stateObj.employeeStatsRequestId || 0) + 1;
  stateObj.employeeStatsRequestId = requestId;
  stateObj.employeeStatsLoading = true;
  stateObj.employeeStatsError = '';
  render();

  const params = new URLSearchParams();
  if (range.from) params.set('from', range.from);
  if (range.to) params.set('to', range.to);
  const query = params.toString() ? `?${params.toString()}` : '';

  try {
    const [ozResult, wbResult] = await Promise.allSettled([
      fetchJson(`${AUTH_API}/oz/users/${user.id}/stats${query}`),
      fetchJson(`${AUTH_API}/wb/users/${user.id}/stats${query}`),
    ]);

    if (Number(stateObj.employeeStatsRequestId || 0) !== requestId) return;

    const partialErrors = [];
    const sources = {};
    const resolvedResults = { oz: ozResult, wb: wbResult };
    for (const marketplace of ['oz', 'wb']) {
      const result = resolvedResults[marketplace];
      if (result.status === 'fulfilled') {
        sources[marketplace] = result.value || null;
        continue;
      }
      const message = result.reason?.message || 'Ошибка загрузки';
      partialErrors.push(`${employeeStatsSiteLabel(marketplace)}: ${message}`);
      sources[marketplace] = null;
    }

    if (!sources.oz && !sources.wb) {
      throw new Error(partialErrors.join(' | ') || 'Не удалось загрузить статистику');
    }

    stateObj.employeeStatsData = buildUnifiedEmployeeStatsData(user, range, sources, partialErrors);
  } catch (err) {
    if (Number(stateObj.employeeStatsRequestId || 0) !== requestId) return;
    stateObj.employeeStatsError = err?.message || 'Ошибка';
  } finally {
    if (Number(stateObj.employeeStatsRequestId || 0) !== requestId) return;
    stateObj.employeeStatsLoading = false;
    render();
  }
}

