function renderEmployeeStatsDailyRow(day) {
  const totalSeconds = Number(day?.totalSeconds || 0);
  const pickingSeconds = Number(day?.pickingSeconds || 0);
  const packingSeconds = Number(day?.packingSeconds || 0);
  const shareBase = Math.max(1, totalSeconds);
  const pickWidth = Math.max(0, Math.min(100, (pickingSeconds / shareBase) * 100));
  const packWidth = Math.max(0, Math.min(100, (packingSeconds / shareBase) * 100));
  return `<div class="employee-stats-v1-day-row">
    <div class="employee-stats-v1-day-meta">
      <div class="employee-stats-v1-day-date">${esc(formatShortDate(day?.day))}</div>
      <div class="employee-stats-v1-day-orders">${Number(day?.orders || 0)} заказов</div>
    </div>
    <div class="employee-stats-v1-day-bar">
      <span class="segment-pick" style="width:${pickWidth}%"></span>
      <span class="segment-pack" style="width:${packWidth}%"></span>
    </div>
    <div class="employee-stats-v1-day-stats">
      <span>Товар: ${esc(formatDuration(pickingSeconds))}</span>
      <span>Заказы: ${esc(formatDuration(packingSeconds))}</span>
      <strong>${esc(formatDuration(totalSeconds))}</strong>
    </div>
  </div>`;
}

