function renderEmployeeStatsModalModern(stateObj) {
  const employee = stateObj.employeeStatsUser;
  if (!employee) return '';

  const statsData = stateObj.employeeStatsData;
  const stats = statsData?.stats || {};
  const today = stats.today || {};
  const period = stats.period || {};
  const allTime = stats.allTime || {};
  const sessions = Array.isArray(stats.sessions) ? stats.sessions : [];
  const daily = Array.isArray(stats.daily) ? stats.daily : [];
  const meta = employeeStatsMarketplaceMeta(stateObj);
  const roleLabel = employeeStatsRoleLabel(employee);
  const rangeKey = stateObj.employeeStatsRangeKey;
  const todayDate = getMoscowDateString();
  const fallbackCustomFrom = meta.isWb ? shiftDateString(todayDate, -6) : '';
  const fallbackCustomTo = meta.isWb ? todayDate : '';
  const customFromValue = stateObj.employeeStatsCustomFrom || fallbackCustomFrom;
  const customToValue = stateObj.employeeStatsCustomTo || fallbackCustomTo;
  const selectedRange = buildEmployeeStatsRange(rangeKey, customFromValue, customToValue);
  const rangeSessions = sessions.filter(session => employeeStatsSessionFitsRange(session, selectedRange));
  const visibleSessions = rangeSessions.slice(0, 24);
  const pickingSessionCount = rangeSessions.filter(employeeStatsHasPickingActivity).length;
  const packingSessionCount = rangeSessions.filter(employeeStatsHasPackingActivity).length;
  const activeDaily = daily.filter(day => Number(day?.totalSeconds || 0) > 0 || Number(day?.orders || 0) > 0);
  const visibleDaily = [...(activeDaily.length ? activeDaily : daily)].slice(-14).reverse();

  const todayOrders = Number(today.orders || 0);
  const todayPickedItems = Number(today.pickedItems || 0);
  const periodOrders = Number(period.orders || 0);
  const periodPickedItems = Number(period.pickedItems || 0);
  const allTimeOrders = Number(allTime.orders || 0);
  const allTimePickedItems = Number(allTime.pickedItems || 0);
  const periodEntityCount = Number(period[meta.periodCountKey] || 0);

  const rangeButtons = [
    { key: 'today', label: 'Сегодня' },
    { key: '7d', label: '7 дней' },
    { key: '30d', label: '30 дней' },
    { key: 'month', label: 'Месяц' },
    { key: 'custom', label: 'Период' },
  ].map(item => `<button class="chip ${rangeKey === item.key ? 'active' : ''}" data-stats-range="${item.key}">${item.label}</button>`).join('');

  const customInputs = rangeKey === 'custom'
    ? `<div class="employee-range-inline">
      <input class="input" type="date" id="stats-from" value="${esc(customFromValue)}" />
      <input class="input" type="date" id="stats-to" value="${esc(customToValue)}" />
      <button class="btn btn-primary btn-sm" id="btn-stats-apply">ПРИМЕНИТЬ</button>
    </div>`
    : '';

  const bodyContent = stateObj.employeeStatsLoading
    ? '<div class="hint" style="padding:24px;text-align:center">Загрузка статистики...</div>'
    : stateObj.employeeStatsError
      ? `<div class="alert alert-error">${esc(stateObj.employeeStatsError)}</div>`
      : `<section class="employee-stats-v1-hero">
          <div class="employee-stats-v1-hero-main">
            <div class="employee-stats-v1-eyebrow">Обзор работы за выбранный период</div>
            <div class="employee-stats-v1-headline">${periodOrders} заказов и ${periodPickedItems} товаров</div>
            <div class="employee-stats-v1-hero-note">${esc(formatDuration(period.totalSeconds || 0))} суммарного времени • ${periodEntityCount} ${meta.entityPlural} • ${Number(period.sessions || 0)} сессий</div>
          </div>
          <div class="employee-stats-v1-hero-aside">
            <div class="employee-stats-v1-hero-badge">Средняя упаковка: <strong>${esc(formatDuration(period.avgSecondsPerOrder || 0))} / заказ</strong></div>
            <div class="employee-stats-v1-hero-badge">Средняя сборка товара: <strong>${esc(formatDuration(period.avgPickSecondsPerItem || 0))} / товар</strong></div>
          </div>
        </section>
        <section class="employee-stats-v1-summary-grid">
          ${renderEmployeeStatsSummaryCard({ title: 'Сегодня', primary: `${todayOrders} заказов`, secondary: `Товар: ${todayPickedItems} шт`, tertiary: `Время: ${formatDuration(today.totalSeconds || 0)}`, tone: 'today' })}
          ${renderEmployeeStatsSummaryCard({ title: 'Период', primary: `${periodOrders} заказов`, secondary: `Товар: ${periodPickedItems} шт`, tertiary: `Время: ${formatDuration(period.totalSeconds || 0)}`, tone: 'period' })}
          ${renderEmployeeStatsSummaryCard({ title: 'Все время', primary: `${allTimeOrders} заказов`, secondary: `Товар: ${allTimePickedItems} шт`, tertiary: `Время: ${formatDuration(allTime.totalSeconds || 0)}`, tone: 'alltime' })}
        </section>
        <section class="employee-stats-v1-average-overview">
          <div class="employee-stats-v1-section-head">
            <div>
              <div class="section-title">Среднее время</div>
              <div class="hint">Среднее время на 1 товар и на 1 заказ в общем по выбранному периоду.</div>
            </div>
          </div>
          <div class="employee-stats-v1-average-overview-grid">
            ${renderEmployeeStatsAverageCard({ title: 'Сегодня', itemAverage: formatSecondsPerUnit(today.pickingSeconds, todayPickedItems, 'товар'), orderAverage: formatSecondsPerUnit(today.packingSeconds, todayOrders, 'заказ'), footer: `Время: ${formatDuration(today.totalSeconds || 0)}`, tone: 'today' })}
            ${renderEmployeeStatsAverageCard({ title: 'Период', itemAverage: formatSecondsPerUnit(period.pickingSeconds, periodPickedItems, 'товар'), orderAverage: formatSecondsPerUnit(period.packingSeconds, periodOrders, 'заказ'), footer: `Время: ${formatDuration(period.totalSeconds || 0)}`, tone: 'period' })}
            ${renderEmployeeStatsAverageCard({ title: 'Все время', itemAverage: formatSecondsPerUnit(allTime.pickingSeconds, allTimePickedItems, 'товар'), orderAverage: formatSecondsPerUnit(allTime.packingSeconds, allTimeOrders, 'заказ'), footer: `Время: ${formatDuration(allTime.totalSeconds || 0)}`, tone: 'alltime' })}
          </div>
        </section>
        <section class="employee-stats-v1-workflow">
          ${renderEmployeeStatsStageCard({
            title: 'Сборка товара',
            accent: 'pick',
            periodValue: `${periodPickedItems} шт`,
            periodHint: `${formatDuration(period.pickingSeconds || 0)} за период`,
            todayValue: `${todayPickedItems} шт`,
            allTimeValue: `${allTimePickedItems} шт`,
            sessionCount: String(pickingSessionCount),
            metrics: [
              { label: 'Средняя скорость', value: formatUnitsPerHour(periodPickedItems, period.pickingSeconds, 'шт'), hint: 'Сколько товаров в час в среднем' },
              { label: 'На 1 товар', value: formatSecondsPerUnit(period.pickingSeconds, periodPickedItems, 'товар'), hint: 'Среднее время на один товар' },
              { label: 'Среднее за сессию', value: formatUnitsPerSession(periodPickedItems, pickingSessionCount, 'шт'), hint: 'Среднее количество товаров за одну сессию' },
              { label: 'Все время', value: formatUnitsPerHour(allTimePickedItems, allTime.pickingSeconds, 'шт'), hint: `${formatDuration(allTime.avgPickSecondsPerItem || 0)} / товар` },
            ],
          })}
          ${renderEmployeeStatsStageCard({
            title: 'Упаковка заказов',
            accent: 'pack',
            periodValue: `${periodOrders} заказов`,
            periodHint: `${formatDuration(period.packingSeconds || 0)} за период`,
            todayValue: `${todayOrders} заказов`,
            allTimeValue: `${allTimeOrders} заказов`,
            sessionCount: String(packingSessionCount),
            metrics: [
              { label: 'Средняя скорость', value: formatUnitsPerHour(periodOrders, period.packingSeconds, 'зак'), hint: 'Сколько заказов в час в среднем' },
              { label: 'На 1 заказ', value: formatSecondsPerUnit(period.packingSeconds, periodOrders, 'заказ'), hint: 'Среднее время на один заказ' },
              { label: 'Среднее за сессию', value: formatUnitsPerSession(periodOrders, packingSessionCount, 'заказа'), hint: 'Среднее количество заказов за одну сессию' },
              { label: 'Все время', value: formatUnitsPerHour(allTimeOrders, allTime.packingSeconds, 'зак'), hint: `${formatDuration(allTime.avgSecondsPerOrder || 0)} / заказ` },
            ],
          })}
        </section>
        <section class="employee-stats-v1-section">
          <div class="employee-stats-v1-section-head">
            <div>
              <div class="section-title">Дневная активность</div>
              <div class="hint">По каждому дню видно распределение времени между сборкой товара и упаковкой заказов.</div>
            </div>
          </div>
          <div class="employee-stats-v1-day-list">${visibleDaily.length ? visibleDaily.map(renderEmployeeStatsDailyRow).join('') : '<div class="hint" style="padding:12px">Нет активности за выбранный период</div>'}</div>
        </section>
        <section class="employee-stats-v1-section">
          <div class="employee-stats-v1-section-head">
            <div>
              <div class="section-title">Последние сессии</div>
              <div class="hint">Карточки показывают, как шла сборка товара и упаковка заказов по каждой выдаче.</div>
            </div>
          </div>
          <div class="employee-stats-v1-session-list">${visibleSessions.length ? visibleSessions.map(session => renderEmployeeStatsSessionCard(session, meta)).join('') : '<div class="hint" style="padding:12px">Сессий пока нет</div>'}</div>
        </section>`;

  return `<div class="modal-overlay" id="modal-stats">
    <div class="modal-panel wide employee-stats-modal" onclick="event.stopPropagation()">
      <div class="modal-header">
        <div>
          <div class="modal-title">${esc(employee.surname || employee.fullName || '')} ${esc(employee.name || '')}</div>
          <div class="modal-subtitle">${esc(roleLabel)} • Новый обзор статистики • Часовой пояс ${esc(statsData?.timezone || 'Europe/Moscow')}</div>
        </div>
        <button class="btn-icon" id="btn-close-stats">&times;</button>
      </div>
      <div class="employee-stats-toolbar">
        <div class="chip-group">${rangeButtons}</div>
        ${customInputs}
      </div>
      <div class="modal-body employee-stats-body employee-stats-v1-body">${bodyContent}</div>
    </div>
  </div>`;
}

function renderEmployeeStatsModalClassic(stateObj) {
  return renderEmployeeStatsModalUnifiedClassic(stateObj);
  const employee = stateObj.employeeStatsUser;
  if (!employee) return '';

  const statsData = stateObj.employeeStatsData;
  const stats = statsData?.stats || {};
  const today = stats.today || {};
  const period = stats.period || {};
  const allTime = stats.allTime || {};
  const sessions = Array.isArray(stats.sessions) ? stats.sessions : [];
  const daily = Array.isArray(stats.daily) ? stats.daily : [];
  const meta = employeeStatsMarketplaceMeta(stateObj);
  const roleLabel = employeeStatsRoleLabel(employee);
  const rangeKey = stateObj.employeeStatsRangeKey;
  const todayDate = getMoscowDateString();
  const fallbackCustomFrom = meta.isWb ? shiftDateString(todayDate, -6) : '';
  const fallbackCustomTo = meta.isWb ? todayDate : '';
  const customFromValue = stateObj.employeeStatsCustomFrom || fallbackCustomFrom;
  const customToValue = stateObj.employeeStatsCustomTo || fallbackCustomTo;
  const selectedRange = buildEmployeeStatsRange(rangeKey, customFromValue, customToValue);
  const rangeSessions = sessions.filter(session => employeeStatsSessionFitsRange(session, selectedRange));
  const visibleSessions = rangeSessions.slice(0, 24);
  const pickingSessionCount = rangeSessions.filter(employeeStatsHasPickingActivity).length;
  const packingSessionCount = rangeSessions.filter(employeeStatsHasPackingActivity).length;
  const activeDaily = daily.filter(day => Number(day?.totalSeconds || 0) > 0 || Number(day?.orders || 0) > 0);
  const visibleDaily = [...(activeDaily.length ? activeDaily : daily)].slice(-14).reverse();

  const todayOrders = Number(today.orders || 0);
  const todayPickedItems = Number(today.pickedItems || 0);
  const periodOrders = Number(period.orders || 0);
  const periodPickedItems = Number(period.pickedItems || 0);
  const allTimeOrders = Number(allTime.orders || 0);
  const allTimePickedItems = Number(allTime.pickedItems || 0);
  const periodEntityCount = Number(period[meta.periodCountKey] || 0);

  const rangeButtons = [
    { key: 'today', label: 'Сегодня' },
    { key: '7d', label: '7 дней' },
    { key: '30d', label: '30 дней' },
    { key: 'month', label: 'Месяц' },
    { key: 'custom', label: 'Период' },
  ].map(item => `<button class="chip ${rangeKey === item.key ? 'active' : ''}" data-stats-range="${item.key}">${item.label}</button>`).join('');

  const customInputs = rangeKey === 'custom'
    ? `<div class="stats-range-inline">
        <input class="input" type="date" id="stats-from" value="${esc(customFromValue)}" />
        <input class="input" type="date" id="stats-to" value="${esc(customToValue)}" />
        <button class="btn btn-primary btn-sm" id="btn-stats-apply">ПРИМЕНИТЬ</button>
      </div>`
    : '';

  const renderSummaryCard = ({ title, primary, secondary, tertiary, tone }) => `<div class="stats-summary-card tone-${tone}">
    <div class="stats-summary-title">${esc(title)}</div>
    <div class="stats-summary-primary">${esc(primary)}</div>
    <div class="stats-summary-lines">
      ${secondary ? `<div>${esc(secondary)}</div>` : ''}
      ${tertiary ? `<div>${esc(tertiary)}</div>` : ''}
    </div>
  </div>`;

  const renderAverageCard = ({ title, itemAverage, orderAverage, footer, tone }) => `<div class="stats-average-card tone-${tone}">
    <div class="stats-average-title">${esc(title)}</div>
    <div class="stats-average-row">
      <span>1 товар</span>
      <strong>${esc(itemAverage)}</strong>
    </div>
    <div class="stats-average-row">
      <span>1 заказ</span>
      <strong>${esc(orderAverage)}</strong>
    </div>
    ${footer ? `<div class="stats-average-footer">${esc(footer)}</div>` : ''}
  </div>`;

  const renderStageMetric = ({ label, value, hint }) => `<div class="stats-stage-metric">
    <div class="stats-stage-metric-label">${esc(label)}</div>
    <div class="stats-stage-metric-value">${esc(value)}</div>
    ${hint ? `<div class="stats-stage-metric-hint">${esc(hint)}</div>` : ''}
  </div>`;

  const renderStageCard = ({ title, accent, periodValue, periodHint, todayValue, allTimeValue, sessionCount, metrics }) => `<section class="stats-stage ${accent}">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap">
      <div>
        <div class="stats-stage-kicker">${esc(title)}</div>
        <div class="stats-stage-main">${esc(periodValue)}</div>
        <div class="hint">${esc(periodHint)}</div>
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end">
        <span class="stats-mini-pill">Сегодня: ${esc(todayValue)}</span>
        <span class="stats-mini-pill">Все время: ${esc(allTimeValue)}</span>
        <span class="stats-mini-pill">Сессий: ${esc(String(sessionCount))}</span>
      </div>
    </div>
    <div class="stats-stage-grid">
      ${metrics.map(renderStageMetric).join('')}
    </div>
  </section>`;

  const renderDayRow = day => {
    const totalSeconds = Number(day?.totalSeconds || 0);
    const pickingSeconds = Number(day?.pickingSeconds || 0);
    const packingSeconds = Number(day?.packingSeconds || 0);
    const shareBase = Math.max(1, totalSeconds);
    const pickWidth = Math.max(0, Math.min(100, (pickingSeconds / shareBase) * 100));
    const packWidth = Math.max(0, Math.min(100, (packingSeconds / shareBase) * 100));
    return `<div class="stats-day-row">
      <div class="stats-day-date">${esc(formatShortDate(day?.day))}</div>
      <div class="stats-day-orders">${Number(day?.orders || 0)} заказов</div>
      <div class="stats-day-bar">
        <span class="segment-pick" style="width:${pickWidth}%"></span>
        <span class="segment-pack" style="width:${packWidth}%"></span>
      </div>
      <div class="stats-day-stats">
        <span>Товар: ${esc(formatDuration(pickingSeconds))}</span>
        <span>Заказы: ${esc(formatDuration(packingSeconds))}</span>
        <strong>${esc(formatDuration(totalSeconds))}</strong>
      </div>
    </div>`;
  };

  const renderSessionCard = session => {
    const entityId = session?.[meta.entityIdKey];
    const entityName = session?.[meta.entityNameKey] || `${meta.entitySingular} ${entityId || '—'}`;
    const pickAverage = formatSecondsPerUnit(session?.pickingTotalSeconds, session?.pickingCollectedQty, 'товар');
    const packAverage = formatSecondsPerUnit(session?.packingTotalSeconds, session?.collectedOrderCount, 'заказ');
    const totalStageNote = employeeStatsHasPickingActivity(session) && employeeStatsHasPackingActivity(session)
      ? 'Товар + заказы'
      : employeeStatsHasPickingActivity(session)
        ? 'Только товар'
        : 'Только заказы';

    return `<article class="stats-session-card">
      <div class="stats-session-head">
        <div>
          <div class="stats-session-title">${esc(entityName)}</div>
          <div class="stats-session-subtitle">
            <span class="mono">${esc(entityId || '—')}</span>
            <span>${esc(session?.storeName || 'Без магазина')}</span>
          </div>
        </div>
        <span class="stats-session-status status-${esc(String(session?.status || '').toLowerCase())}">${esc(employeeStatsStatusLabel(session))}</span>
      </div>
      <div class="stats-session-meta">
        <div><span>Назначил</span><strong>${esc(session?.assignedByName || '—')}</strong></div>
        <div><span>Выдано</span><strong>${esc(formatDateTime(session?.assignedAt))}</strong></div>
        <div><span>Старт товара</span><strong>${esc(formatDateTime(session?.pickingStartedAt))}</strong></div>
        <div><span>Старт заказов</span><strong>${esc(formatDateTime(session?.startedAt))}</strong></div>
        <div><span>Финиш</span><strong>${esc(formatDateTime(session?.finishedAt || session?.pickingFinishedAt))}</strong></div>
      </div>
      <div class="stats-session-grid">
        <div class="stats-session-stage stage-pick">
          <div class="stats-session-stage-title">Сборка товара</div>
          <div class="stats-session-stage-main">${Number(session?.pickingCollectedQty || 0)} шт</div>
          <div class="stats-session-stage-note">${esc(formatDuration(session?.pickingTotalSeconds || 0))} суммарно</div>
          <div class="stats-session-stage-meta">
            <span>Среднее на 1 товар</span>
            <strong>${esc(pickAverage)}</strong>
          </div>
        </div>
        <div class="stats-session-stage stage-pack">
          <div class="stats-session-stage-title">Упаковка заказов</div>
          <div class="stats-session-stage-main">${Number(session?.collectedOrderCount || 0)} / ${Number(session?.assignedOrderCount || 0)}</div>
          <div class="stats-session-stage-note">${esc(formatDuration(session?.packingTotalSeconds || 0))} суммарно</div>
          <div class="stats-session-stage-meta">
            <span>Среднее на 1 заказ</span>
            <strong>${esc(packAverage)}</strong>
          </div>
        </div>
        <div class="stats-session-stage stage-total">
          <div class="stats-session-stage-title">Итого</div>
          <div class="stats-session-stage-main">${esc(formatDuration(session?.totalSeconds || 0))}</div>
          <div class="stats-session-stage-note">${esc(totalStageNote)}</div>
          <div style="display:grid;gap:4px;margin-top:6px;border-top:1px solid var(--border);padding-top:6px">
            <div class="stats-session-stage-meta" style="margin-top:0;border-top:none;padding-top:0">
              <span>1 товар</span>
              <strong>${esc(pickAverage)}</strong>
            </div>
            <div class="stats-session-stage-meta" style="margin-top:0;border-top:none;padding-top:0">
              <span>1 заказ</span>
              <strong>${esc(packAverage)}</strong>
            </div>
          </div>
        </div>
      </div>
    </article>`;
  };

  const heroHtml = `<div class="stats-hero">
    <div class="stats-hero-headline">${periodOrders} заказов и ${periodPickedItems} товаров</div>
    <div class="hint">${esc(formatDuration(period.totalSeconds || 0))} суммарного времени • ${periodEntityCount} ${meta.entityPlural} • ${Number(period.sessions || 0)} сессий</div>
    <div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-top:10px">
      <span class="stats-mini-pill">Средняя упаковка: ${esc(formatDuration(period.avgSecondsPerOrder || 0))} / заказ</span>
      <span class="stats-mini-pill">Средняя сборка товара: ${esc(formatDuration(period.avgPickSecondsPerItem || 0))} / товар</span>
    </div>
  </div>`;

  const summaryHtml = `<div class="stats-summary-grid">
    ${renderSummaryCard({ title: 'Сегодня', primary: `${todayOrders} заказов`, secondary: `Товар: ${todayPickedItems} шт`, tertiary: `Время: ${formatDuration(today.totalSeconds || 0)}`, tone: 'today' })}
    ${renderSummaryCard({ title: 'Период', primary: `${periodOrders} заказов`, secondary: `Товар: ${periodPickedItems} шт`, tertiary: `Время: ${formatDuration(period.totalSeconds || 0)}`, tone: 'period' })}
    ${renderSummaryCard({ title: 'Все время', primary: `${allTimeOrders} заказов`, secondary: `Товар: ${allTimePickedItems} шт`, tertiary: `Время: ${formatDuration(allTime.totalSeconds || 0)}`, tone: 'alltime' })}
  </div>`;

  const averagesHtml = `<div class="stats-stage">
    <div class="section-title">Среднее время</div>
    <div class="hint" style="margin-top:4px">Среднее время на 1 товар и на 1 заказ по выбранному периоду.</div>
    <div class="stats-average-grid">
      ${renderAverageCard({ title: 'Сегодня', itemAverage: formatSecondsPerUnit(today.pickingSeconds, todayPickedItems, 'товар'), orderAverage: formatSecondsPerUnit(today.packingSeconds, todayOrders, 'заказ'), footer: `Время: ${formatDuration(today.totalSeconds || 0)}`, tone: 'today' })}
      ${renderAverageCard({ title: 'Период', itemAverage: formatSecondsPerUnit(period.pickingSeconds, periodPickedItems, 'товар'), orderAverage: formatSecondsPerUnit(period.packingSeconds, periodOrders, 'заказ'), footer: `Время: ${formatDuration(period.totalSeconds || 0)}`, tone: 'period' })}
      ${renderAverageCard({ title: 'Все время', itemAverage: formatSecondsPerUnit(allTime.pickingSeconds, allTimePickedItems, 'товар'), orderAverage: formatSecondsPerUnit(allTime.packingSeconds, allTimeOrders, 'заказ'), footer: `Время: ${formatDuration(allTime.totalSeconds || 0)}`, tone: 'alltime' })}
    </div>
  </div>`;

  const workflowHtml = `${renderStageCard({
    title: 'Сборка товара',
    accent: 'pick',
    periodValue: `${periodPickedItems} шт`,
    periodHint: `${formatDuration(period.pickingSeconds || 0)} за период`,
    todayValue: `${todayPickedItems} шт`,
    allTimeValue: `${allTimePickedItems} шт`,
    sessionCount: pickingSessionCount,
    metrics: [
      { label: 'Средняя скорость', value: formatUnitsPerHour(periodPickedItems, period.pickingSeconds, 'шт'), hint: 'Сколько товаров в час в среднем' },
      { label: 'На 1 товар', value: formatSecondsPerUnit(period.pickingSeconds, periodPickedItems, 'товар'), hint: 'Среднее время на один товар' },
      { label: 'Среднее за сессию', value: formatUnitsPerSession(periodPickedItems, pickingSessionCount, 'шт'), hint: 'Среднее количество товаров за одну сессию' },
      { label: 'Все время', value: formatUnitsPerHour(allTimePickedItems, allTime.pickingSeconds, 'шт'), hint: `${formatDuration(allTime.avgPickSecondsPerItem || 0)} / товар` },
    ],
  })}${renderStageCard({
    title: 'Упаковка заказов',
    accent: 'pack',
    periodValue: `${periodOrders} заказов`,
    periodHint: `${formatDuration(period.packingSeconds || 0)} за период`,
    todayValue: `${todayOrders} заказов`,
    allTimeValue: `${allTimeOrders} заказов`,
    sessionCount: packingSessionCount,
    metrics: [
      { label: 'Средняя скорость', value: formatUnitsPerHour(periodOrders, period.packingSeconds, 'зак'), hint: 'Сколько заказов в час в среднем' },
      { label: 'На 1 заказ', value: formatSecondsPerUnit(period.packingSeconds, periodOrders, 'заказ'), hint: 'Среднее время на один заказ' },
      { label: 'Среднее за сессию', value: formatUnitsPerSession(periodOrders, packingSessionCount, 'заказа'), hint: 'Среднее количество заказов за одну сессию' },
      { label: 'Все время', value: formatUnitsPerHour(allTimeOrders, allTime.packingSeconds, 'зак'), hint: `${formatDuration(allTime.avgSecondsPerOrder || 0)} / заказ` },
    ],
  })}`;

  const dailyHtml = `<div class="stats-stage">
    <div class="section-title">Дневная активность</div>
    <div class="hint" style="margin-top:4px">По каждому дню видно распределение времени между сборкой товара и упаковкой заказов.</div>
    <div style="margin-top:10px">
      ${visibleDaily.length ? visibleDaily.map(renderDayRow).join('') : '<div class="hint" style="padding:12px 0">Нет активности за выбранный период</div>'}
    </div>
  </div>`;

  const sessionsHtml = `<div class="stats-stage">
    <div class="section-title">Последние сессии</div>
    <div class="hint" style="margin-top:4px">Карточки показывают, как шла сборка товара и упаковка заказов по каждой выдаче.</div>
    <div style="margin-top:10px;max-height:420px;overflow:auto">
      ${visibleSessions.length ? visibleSessions.map(renderSessionCard).join('') : '<div class="hint" style="padding:12px 0">Сессий пока нет</div>'}
    </div>
  </div>`;

  const bodyContent = stateObj.employeeStatsLoading
    ? '<div class="hint" style="text-align:center;padding:40px">Загрузка статистики...</div>'
    : stateObj.employeeStatsError
      ? `<div class="alert alert-error">${esc(stateObj.employeeStatsError)}</div>`
      : `${heroHtml}${summaryHtml}${averagesHtml}${workflowHtml}${dailyHtml}${sessionsHtml}`;

  return `<div class="modal-overlay" id="modal-stats" style="position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:1000;display:flex;align-items:center;justify-content:center">
    <div class="modal-panel wide" style="background:#0a0a0a;border:1px solid #333;border-radius:8px;max-width:1160px;width:95%;max-height:90vh;display:flex;flex-direction:column" onclick="event.stopPropagation()">
      <div class="modal-header" style="display:flex;justify-content:space-between;align-items:center;padding:16px;border-bottom:1px solid #333">
        <div>
          <div class="modal-title" style="font-size:16px;font-weight:700">${esc(employee.surname || employee.fullName || '')} ${esc(employee.name || '')}</div>
          <div class="modal-subtitle" style="font-size:12px;color:#888">${esc(roleLabel)} • Статистика • Часовой пояс ${esc(statsData?.timezone || 'Europe/Moscow')}</div>
        </div>
        <button class="btn-icon" id="btn-close-stats" style="font-size:20px;background:none;border:none;color:#888;cursor:pointer">&times;</button>
      </div>
      <div class="stats-toolbar">
        ${rangeButtons}
        ${customInputs}
      </div>
      <div class="modal-body" style="padding:16px;overflow-y:auto;flex:1">
        ${bodyContent}
      </div>
    </div>
  </div>`;
}

function renderEmployeeStatsModalUnifiedClassic(stateObj) {
  const employee = stateObj.employeeStatsUser;
  if (!employee) return '';

  const statsData = stateObj.employeeStatsData || {};
  const roleLabel = employeeStatsRoleLabel(employee);
  const rangeKey = stateObj.employeeStatsRangeKey;
  const todayDate = getMoscowDateString();
  const fallbackCustomFrom = stateObj === wbState ? shiftDateString(todayDate, -6) : '';
  const fallbackCustomTo = stateObj === wbState ? todayDate : '';
  const customFromValue = stateObj.employeeStatsCustomFrom || fallbackCustomFrom;
  const customToValue = stateObj.employeeStatsCustomTo || fallbackCustomTo;
  const selectedRange = buildEmployeeStatsRange(rangeKey, customFromValue, customToValue);
  const combinedPeriod = statsData?.combined?.period || mergeEmployeeStatsBlocks();
  const sourceOz = statsData?.sources?.oz || emptyUnifiedEmployeeStatsSource('oz', employee, statsData?.range);
  const sourceWb = statsData?.sources?.wb || emptyUnifiedEmployeeStatsSource('wb', employee, statsData?.range);
  const sessions = Array.isArray(statsData?.sessions) ? statsData.sessions : [];
  const visibleSessions = sessions
    .filter(session => employeeStatsSessionFitsRange(session, selectedRange))
    .sort((a, b) => new Date(b?.sessionSortAt || 0).getTime() - new Date(a?.sessionSortAt || 0).getTime());
  const partialErrors = Array.isArray(statsData?.partialErrors) ? statsData.partialErrors : [];

  const rangeButtons = [
    { key: 'today', label: 'Сегодня' },
    { key: '7d', label: '7 дней' },
    { key: '30d', label: '30 дней' },
    { key: 'month', label: 'Месяц' },
    { key: 'custom', label: 'Период' },
  ].map(item => `<button class="chip ${rangeKey === item.key ? 'active' : ''}" data-stats-range="${item.key}">${item.label}</button>`).join('');

  const customInputs = rangeKey === 'custom'
    ? `<div class="stats-range-inline">
        <input class="input" type="date" id="stats-from" value="${esc(customFromValue)}" />
        <input class="input" type="date" id="stats-to" value="${esc(customToValue)}" />
        <button class="btn btn-primary btn-sm" id="btn-stats-apply">ПРИМЕНИТЬ</button>
      </div>`
    : '';

  const renderMarketMetric = ({ label, value, hint }) => `<div class="stats-market-metric">
    <div class="stats-market-metric-label">${esc(label)}</div>
    <div class="stats-market-metric-value">${esc(value)}</div>
    ${hint ? `<div class="stats-stage-metric-hint">${esc(hint)}</div>` : ''}
  </div>`;

  const renderMarketCard = (marketplace, source) => {
    const meta = employeeStatsSiteMeta(marketplace);
    const period = source?.stats?.period || normalizeEmployeeStatsBlock();
    const entityCount = Number(period?.[meta.periodCountKey] || 0);
    return `<div class="stats-market-card ${marketplace}">
      <div class="stats-market-head">
        <span class="stats-market-badge ${marketplace}">${esc(source?.marketplaceLabel || employeeStatsSiteLabel(marketplace))}</span>
        <div class="stats-market-big">${Number(period.orders || 0)} заказов</div>
      </div>
      <div class="stats-market-meta">
        Товаров: ${Number(period.pickedItems || 0)} шт • ${meta.entityPlural}: ${entityCount} • Сессий: ${Number(period.sessions || 0)} • Время: ${esc(formatDuration(period.totalSeconds || 0))}
      </div>
      <div class="stats-market-metrics">
        ${renderMarketMetric({
          label: 'Скорость товара',
          value: formatUnitsPerHour(period.pickedItems, period.pickingSeconds, 'шт'),
          hint: `${formatSecondsPerUnit(period.pickingSeconds, period.pickedItems, 'товар')}`,
        })}
        ${renderMarketMetric({
          label: 'Скорость заказов',
          value: formatUnitsPerHour(period.orders, period.packingSeconds, 'зак'),
          hint: `${formatSecondsPerUnit(period.packingSeconds, period.orders, 'заказ')}`,
        })}
      </div>
    </div>`;
  };

  const renderSessionCard = (session) => {
    const pickAverage = formatSecondsPerUnit(session?.pickingTotalSeconds, session?.pickingCollectedQty, 'товар');
    const packAverage = formatSecondsPerUnit(session?.packingTotalSeconds, session?.collectedOrderCount, 'заказ');
    const totalStageNote = employeeStatsHasPickingActivity(session) && employeeStatsHasPackingActivity(session)
      ? 'Товар + заказы'
      : employeeStatsHasPickingActivity(session)
        ? 'Только товар'
        : 'Только заказы';

    return `<article class="stats-session-card">
      <div class="stats-session-head">
        <div>
          <div class="stats-session-title">${esc(session?.entityName || 'Сессия')}</div>
          <div class="stats-session-subtitle">
            <span class="stats-market-badge ${esc(session?.marketplace || 'oz')}">${esc(session?.marketplaceLabel || 'OZON')}</span>
            <span class="mono">${esc(session?.entityId || '—')}</span>
            <span>${esc(session?.storeName || 'Без магазина')}</span>
          </div>
        </div>
        <span class="stats-session-status status-${esc(String(session?.status || '').toLowerCase())}">${esc(employeeStatsStatusLabel(session))}</span>
      </div>
      <div class="stats-session-meta">
        <div><span>Назначил</span><strong>${esc(session?.assignedByName || '—')}</strong></div>
        <div><span>Выдано</span><strong>${esc(formatDateTime(session?.assignedAt))}</strong></div>
        <div><span>Старт товара</span><strong>${esc(formatDateTime(session?.pickingStartedAt))}</strong></div>
        <div><span>Старт заказов</span><strong>${esc(formatDateTime(session?.startedAt))}</strong></div>
        <div><span>Финиш</span><strong>${esc(formatDateTime(session?.finishedAt || session?.pickingFinishedAt))}</strong></div>
      </div>
      <div class="stats-session-grid">
        <div class="stats-session-stage stage-pick">
          <div class="stats-session-stage-title">Сборка товара</div>
          <div class="stats-session-stage-main">${Number(session?.pickingCollectedQty || 0)} шт</div>
          <div class="stats-session-stage-note">${esc(formatDuration(session?.pickingTotalSeconds || 0))} суммарно</div>
          <div class="stats-session-stage-meta">
            <span>Среднее на 1 товар</span>
            <strong>${esc(pickAverage)}</strong>
          </div>
        </div>
        <div class="stats-session-stage stage-pack">
          <div class="stats-session-stage-title">Упаковка заказов</div>
          <div class="stats-session-stage-main">${Number(session?.collectedOrderCount || 0)} / ${Number(session?.assignedOrderCount || 0)}</div>
          <div class="stats-session-stage-note">${esc(formatDuration(session?.packingTotalSeconds || 0))} суммарно</div>
          <div class="stats-session-stage-meta">
            <span>Среднее на 1 заказ</span>
            <strong>${esc(packAverage)}</strong>
          </div>
        </div>
        <div class="stats-session-stage stage-total">
          <div class="stats-session-stage-title">Итого</div>
          <div class="stats-session-stage-main">${esc(formatDuration(session?.totalSeconds || 0))}</div>
          <div class="stats-session-stage-note">${esc(totalStageNote)}</div>
          <div style="display:grid;gap:4px;margin-top:6px;border-top:1px solid var(--border);padding-top:6px">
            <div class="stats-session-stage-meta" style="margin-top:0;border-top:none;padding-top:0">
              <span>1 товар</span>
              <strong>${esc(pickAverage)}</strong>
            </div>
            <div class="stats-session-stage-meta" style="margin-top:0;border-top:none;padding-top:0">
              <span>1 заказ</span>
              <strong>${esc(packAverage)}</strong>
            </div>
          </div>
        </div>
      </div>
    </article>`;
  };

  const combinedHtml = `<div class="stats-stage total">
    <div class="stats-stage-kicker">ИТОГ OZON + WB ЗА ВЫБРАННЫЙ ПЕРИОД</div>
    <div class="stats-stage-main">${Number(combinedPeriod.orders || 0)} заказов</div>
    <div class="hint">Товаров: ${Number(combinedPeriod.pickedItems || 0)} шт • Сессий: ${Number(combinedPeriod.sessions || 0)} • Время: ${esc(formatDuration(combinedPeriod.totalSeconds || 0))}</div>
    <div class="stats-stage-grid">
      <div class="stats-stage-metric">
        <div class="stats-stage-metric-label">Скорость товара</div>
        <div class="stats-stage-metric-value">${esc(formatUnitsPerHour(combinedPeriod.pickedItems, combinedPeriod.pickingSeconds, 'шт'))}</div>
        <div class="stats-stage-metric-hint">${esc(formatSecondsPerUnit(combinedPeriod.pickingSeconds, combinedPeriod.pickedItems, 'товар'))}</div>
      </div>
      <div class="stats-stage-metric">
        <div class="stats-stage-metric-label">Скорость заказов</div>
        <div class="stats-stage-metric-value">${esc(formatUnitsPerHour(combinedPeriod.orders, combinedPeriod.packingSeconds, 'зак'))}</div>
        <div class="stats-stage-metric-hint">${esc(formatSecondsPerUnit(combinedPeriod.packingSeconds, combinedPeriod.orders, 'заказ'))}</div>
      </div>
      <div class="stats-stage-metric">
        <div class="stats-stage-metric-label">OZON</div>
        <div class="stats-stage-metric-value">${Number(sourceOz?.stats?.period?.orders || 0)} заказов</div>
        <div class="stats-stage-metric-hint">Товаров: ${Number(sourceOz?.stats?.period?.pickedItems || 0)} шт</div>
      </div>
      <div class="stats-stage-metric">
        <div class="stats-stage-metric-label">WB</div>
        <div class="stats-stage-metric-value">${Number(sourceWb?.stats?.period?.orders || 0)} заказов</div>
        <div class="stats-stage-metric-hint">Товаров: ${Number(sourceWb?.stats?.period?.pickedItems || 0)} шт</div>
      </div>
    </div>
  </div>`;

  const compareHtml = `<div class="stats-stage">
    <div class="section-title">Раскладка по маркетплейсам</div>
    <div class="hint" style="margin-top:4px">Слева Ozon, справа WB. Внутри каждого блока только данные за выбранный период.</div>
    <div class="stats-market-grid">
      ${renderMarketCard('oz', sourceOz)}
      ${renderMarketCard('wb', sourceWb)}
    </div>
  </div>`;

  const sessionsHtml = `<div class="stats-stage">
    <div class="section-title">Сессии за выбранный период</div>
    <div class="hint" style="margin-top:4px">Показаны все сессии сотрудника за выбранный диапазон сразу по Ozon и WB.</div>
    <div style="margin-top:10px;max-height:460px;overflow:auto">
      ${visibleSessions.length ? visibleSessions.map(renderSessionCard).join('') : '<div class="hint" style="padding:12px 0">Сессий за выбранный период нет</div>'}
    </div>
  </div>`;

  const partialErrorsHtml = partialErrors.length
    ? `<div class="alert">${esc(partialErrors.join(' | '))}</div>`
    : '';

  const bodyContent = stateObj.employeeStatsLoading
    ? '<div class="hint" style="text-align:center;padding:40px">Загрузка статистики...</div>'
    : stateObj.employeeStatsError
      ? `<div class="alert alert-error">${esc(stateObj.employeeStatsError)}</div>`
      : `${partialErrorsHtml}${combinedHtml}${compareHtml}${sessionsHtml}`;

  return `<div class="modal-overlay" id="modal-stats" style="position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:1000;display:flex;align-items:center;justify-content:center">
    <div class="modal-panel wide" style="background:#0a0a0a;border:1px solid #333;border-radius:8px;max-width:1200px;width:95%;max-height:90vh;display:flex;flex-direction:column" onclick="event.stopPropagation()">
      <div class="modal-header" style="display:flex;justify-content:space-between;align-items:center;padding:16px;border-bottom:1px solid #333">
        <div>
          <div class="modal-title" style="font-size:16px;font-weight:700">${esc(employee.surname || employee.fullName || '')} ${esc(employee.name || '')}</div>
          <div class="modal-subtitle" style="font-size:12px;color:#888">${esc(roleLabel)} • OZON + WB • Часовой пояс ${esc(statsData?.timezone || 'Europe/Moscow')}</div>
        </div>
        <button class="btn-icon" id="btn-close-stats" style="font-size:20px;background:none;border:none;color:#888;cursor:pointer">&times;</button>
      </div>
      <div class="stats-toolbar">
        ${rangeButtons}
        ${customInputs}
      </div>
      <div class="modal-body" style="padding:16px;overflow-y:auto;flex:1">
        ${bodyContent}
      </div>
    </div>
  </div>`;
}

function ozRender() {
  // This is the "inner render" — it assumes OZ is the active marketplace
  // The main render() wraps this with topbar etc.
  const app = document.getElementById('app');
  if (!app) return;
  const user = shared.currentUser;
  if (!user) return;
  const isSuper = user.role === 'super_admin';
  const isAdmin = user.role === 'admin';
  const isEmployee = user.role === 'employee';
  const isCollector = isEmployee && user.position === 'collector';

  let content = '';
  const topbar = ozRenderTopbar();

  if (isSuper) {
    content = topbar + '<div class="main-content">' + ozRenderSuperAdmin() + '</div>' + ozRenderStatusbar();
    app.innerHTML = content;
    ozBindSuperAdmin();
    return;
  }
  if (isAdmin) {
    content = topbar + ozRenderAdminTabs() + '<div class="main-content">' + ozRenderAdminContent() + '</div>' + ozRenderStatusbar() + ozRenderAdminModals();
    app.innerHTML = content;
    ozBindAdmin();
    return;
  }
  if (isCollector) {
    content = topbar + '<div class="main-content">' + ozRenderCollector() + '</div>' + ozRenderStatusbar();
    app.innerHTML = content;
    ozBindCollector();
    return;
  }
  if (isEmployee) {
    content = topbar + '<div class="main-content">' + ozRenderEmployeeCurrent() + '</div>' + ozRenderStatusbar() + ozRenderEmployeeModalsCurrent();
    app.innerHTML = content;
    ozBindEmployeeCurrent();
    return;
  }
}

// Due to file size constraints, we provide stub render/bind functions for OZ
// that directly replicate the original OZ code, adapted to use ozState and getApiBase().
// The full implementation follows the same patterns as the original OZ app.js.

function earningsMarketplaceLabel(value) {
  return value === 'wb' ? 'WB' : value === 'oz' ? 'OZON' : 'ОБЩИЙ';
}

function earningsCodeLabel(value) {
  return value === 'wb_barcode' ? 'Баркод WB' : value === 'ozon_barcode' ? 'ШК Ozon' : 'Код';
}

function earningsRangeLabel(rangeKey) {
  if (rangeKey === 'today') return 'Сегодня';
  if (rangeKey === '7d') return '7 дней';
  if (rangeKey === '30d') return '30 дней';
  if (rangeKey === 'month') return 'Этот месяц';
  return 'Свой диапазон';
}

function earningsEmployeeRoleLabel(position) {
  return position === 'collector' ? 'Сборщик' : 'Упаковщик';
}

function earningsEventLabel(eventType) {
  if (eventType === 'order_collect') return 'Сборка заказа';
  if (eventType === 'manual_adjustment') return 'Корректировка';
  return 'Сборка товара';
}

function buildEarningsStoreOptionValue(store) {
  const marketplace = String(store?.marketplace || '').trim();
  const storeId = String(store?.storeId || '').trim();
  if (!storeId) return '';
  return marketplace ? `${marketplace}::${storeId}` : storeId;
}

function parseEarningsStoreOptionValue(value) {
  const raw = String(value || '').trim();
  if (!raw) return { marketplace: '', storeId: '' };
  const sepIndex = raw.indexOf('::');
  if (sepIndex === -1) return { marketplace: '', storeId: raw };
  return {
    marketplace: raw.slice(0, sepIndex) || '',
    storeId: raw.slice(sepIndex + 2) || '',
  };
}

function renderEarningsStatCard({ title, value, note = '', meta = [], tone = '', active = false, attrs = '' } = {}) {
  return `<button class="earnings-stat-card${tone ? ` tone-${tone}` : ''}${active ? ' is-active' : ''}" type="button"${attrs}>
    <div class="earnings-stat-title">${esc(title || '—')}</div>
    <div class="earnings-stat-value">${esc(value || '—')}</div>
    ${note ? `<div class="earnings-stat-note">${esc(note)}</div>` : ''}
    ${meta.length ? `<div class="earnings-stat-meta">${meta.map((item) => `<span>${esc(item)}</span>`).join('')}</div>` : ''}
  </button>`;
}

function normalizeEarningsDisplayValue(value) {
  const text = String(value ?? '').trim();
  if (!text || !/GRA\b/i.test(text)) return text;
  const normalizedNumber = text
    .replace(/\s*GRA\b/gi, '')
    .replace(/\u00A0/g, '')
    .replace(/\s/g, '')
    .replace(',', '.');
  const graValue = Number(normalizedNumber);
  if (!Number.isFinite(graValue)) return text.replace(/\bGRA\b/gi, '₽');
  return formatRubFromGra(graValue, 2);
}

function renderEarningsSummaryCard(title, value, note, accent = '') {
  const displayValue = normalizeEarningsDisplayValue(value);
  return `<div class="earnings-summary-card${accent ? ` tone-${accent}` : ''}">
    <div class="earnings-summary-title">${esc(title)}</div>
    <div class="earnings-summary-value">${esc(displayValue)}</div>
    <div class="earnings-summary-note">${esc(note)}</div>
  </div>`;
}

