function renderEarningsTabV5() {
  const data = earningsState.dashboard;
  const detail = earningsState.detail;
  const summary = data?.summary || {};
  const employees = Array.isArray(data?.employees) ? data.employees : [];
  const marketplaceStats = Array.isArray(data?.marketplaces) ? data.marketplaces : [];
  const selectedUserId = Number(earningsState.userId || 0);
  const isDetailCurrent = Number(earningsState.detailUserId || 0) === Number(selectedUserId || 0);
  const currentDetail = isDetailCurrent ? detail : null;
  const selectedEmployee =
    currentDetail?.employee ||
    employees.find((employee) => Number(employee?.userId || 0) === Number(selectedUserId || 0)) ||
    null;
  const detailSummary = currentDetail?.summary || {};
  const detailEntities = Array.isArray(currentDetail?.entities) ? currentDetail.entities : [];
  const detailMarketplaceStats = Array.isArray(currentDetail?.marketplaces) ? currentDetail.marketplaces : [];
  const wbStat = marketplaceStats.find((stat) => stat?.marketplace === 'wb') || null;
  const ozStat = marketplaceStats.find((stat) => stat?.marketplace === 'oz') || null;
  const wbEmployeeStat = detailMarketplaceStats.find((stat) => stat?.marketplace === 'wb') || null;
  const ozEmployeeStat = detailMarketplaceStats.find((stat) => stat?.marketplace === 'oz') || null;
  const wbEntities = detailEntities.filter((row) => row?.marketplace === 'wb');
  const ozEntities = detailEntities.filter((row) => row?.marketplace === 'oz');
  const otherEntities = detailEntities.filter((row) => row?.marketplace !== 'wb' && row?.marketplace !== 'oz');
  const hasData = Boolean(data);
  const lastEarnedText = detailSummary?.lastEarnedAt ? formatDateTime(detailSummary.lastEarnedAt) : '—';

  const detailContent = (earningsState.detailLoading || (selectedUserId > 0 && !isDetailCurrent))
    ? '<div class="hint" style="padding:24px;text-align:center">Загрузка сотрудника...</div>'
    : earningsState.detailError
      ? `<div class="alert alert-error">${esc(earningsState.detailError)}</div>`
      : selectedEmployee
        ? `<div class="earnings-detail-stack">
            <div class="earnings-detail-head">
              <div>
                <div class="section-title">${esc(selectedEmployee.fullName || '—')}</div>
                <div class="section-subtitle">${esc(earningsEmployeeRoleLabel(selectedEmployee.position))} • детали по сборке товара и сборке заказа</div>
              </div>
              <div class="earnings-detail-balance">${formatNumber(detailSummary.balance ?? selectedEmployee.balance ?? 0, 2)} GRA</div>
            </div>
            <div class="earnings-summary-grid">
              ${renderEarningsSummaryCard('Баланс', `${formatNumber(detailSummary.balance ?? selectedEmployee.balance ?? 0, 2)} GRA`, 'Текущий баланс сотрудника')}
              ${renderEarningsSummaryCard('Сборка товара', `${formatNumber(detailSummary.itemAmount || 0, 2)} GRA`, `${formatNumber(detailSummary.itemEvents || 0, 0)} начислений • ${formatNumber(detailSummary.itemUnits || 0, 0)} сканов`)}
              ${renderEarningsSummaryCard('Сборка заказа', `${formatNumber(detailSummary.orderAmount || 0, 2)} GRA`, `${formatNumber(detailSummary.orderEvents || 0, 0)} начислений • ${formatNumber(detailSummary.orderUnits || 0, 0)} заказов`)}
              ${renderEarningsSummaryCard('Корректировки', `${formatNumber(detailSummary.manualAmount || 0, 2)} GRA`, `Последнее: ${lastEarnedText}`)}
            </div>
            <div class="earnings-detail-market-grid">
              ${renderEarningsMarketplaceCardV5('WB', wbEmployeeStat, 'wb')}
              ${renderEarningsMarketplaceCardV5('OZON', ozEmployeeStat, 'oz')}
            </div>
            <div class="earnings-detail-sections">
              <section class="earnings-detail-section">
                <div class="section-header">
                  <div>
                    <div class="section-title">WB</div>
                    <div class="section-subtitle">Поставки, по которым сотрудник получил начисления в WB.</div>
                  </div>
                </div>
                <div class="earnings-entity-list">
                  ${wbEntities.length ? wbEntities.map((row) => renderEarningsEntityRowV5(row)).join('') : renderEarningsEmptyState('Нет начислений в WB', 'По WB у сотрудника пока нет начислений.')}
                </div>
              </section>
              <section class="earnings-detail-section">
                <div class="section-header">
                  <div>
                    <div class="section-title">OZON</div>
                    <div class="section-subtitle">Сборки, по которым сотрудник получил начисления в Ozon.</div>
                  </div>
                </div>
                <div class="earnings-entity-list">
                  ${ozEntities.length ? ozEntities.map((row) => renderEarningsEntityRowV5(row)).join('') : renderEarningsEmptyState('Нет начислений в Ozon', 'По Ozon у сотрудника пока нет начислений.')}
                </div>
              </section>
              ${otherEntities.length ? `<section class="earnings-detail-section">
                <div class="section-header">
                  <div>
                    <div class="section-title">Прочее</div>
                    <div class="section-subtitle">Редкие или нестандартные источники начислений.</div>
                  </div>
                </div>
                <div class="earnings-entity-list">${otherEntities.map((row) => renderEarningsEntityRowV5(row)).join('')}</div>
              </section>` : ''}
            </div>
          </div>`
        : renderEarningsEmptyState('Нет выбранного сотрудника', 'Список сотрудников пуст или детализация еще не загружена.');

  return `<div class="earnings-shell">
    <div class="section-header earnings-page-head">
      <div>
        <div class="section-title">Заработок</div>
        <div class="section-subtitle">Раздельное начисление за сборку товара и за сборку заказа по OZON и WB.</div>
      </div>
      <div class="earnings-head-actions">
        <div class="earnings-head-chip">
          <span>Период</span>
          <strong>Все время</strong>
        </div>
        <button class="btn btn-sm" id="btn-earnings-refresh" ${earningsState.loading ? 'disabled' : ''}>${earningsState.loading ? 'Обновляем...' : 'Обновить'}</button>
      </div>
    </div>
    ${earningsState.error ? `<div class="alert alert-error">${esc(earningsState.error)}</div>` : ''}
    ${earningsState.loading && !hasData ? '<div class="hint" style="padding:24px;text-align:center">Загрузка заработка...</div>' : ''}
    ${hasData ? `
      <div class="earnings-summary-grid">
        ${renderEarningsSummaryCard('Всего начислено', `${formatNumber(summary.totalAmount || 0, 2)} GRA`, 'Общий объем начислений по сайту')}
        ${renderEarningsSummaryCard('Живой баланс', `${formatNumber(summary.totalBalance || 0, 2)} GRA`, `${formatNumber(summary.balanceHolders || 0, 0)} сотрудников с балансом`)}
        ${renderEarningsSummaryCard('Сборка товара', `${formatNumber(summary.pickAmount || 0, 2)} GRA`, `${formatNumber(summary.pickEvents || 0, 0)} начислений • ${formatNumber(summary.pickUnits || 0, 0)} сканов`)}
        ${renderEarningsSummaryCard('Сборка заказа', `${formatNumber(summary.orderAmount || 0, 2)} GRA`, `${formatNumber(summary.orderEvents || 0, 0)} начислений • ${formatNumber(summary.orderUnits || 0, 0)} заказов`)}
      </div>
      <div class="earnings-market-grid-simple">
        ${renderEarningsMarketplaceCardV5('WB', wbStat, 'wb')}
        ${renderEarningsMarketplaceCardV5('OZON', ozStat, 'oz')}
      </div>
      <div class="earnings-simple-grid">
        <section class="card earnings-list-card">
          <div class="section-header">
            <div>
              <div class="section-title">Сотрудники</div>
              <div class="section-subtitle">Список сотрудников с положительным балансом. Нажмите на сотрудника, чтобы увидеть детализацию по его сборкам и поставкам.</div>
            </div>
          </div>
          <div class="earnings-employee-list-simple">
            ${employees.length ? employees.map((employee) => renderEarningsEmployeeRowV5(employee, selectedUserId)).join('') : renderEarningsEmptyState('Нет сотрудников', 'Сотрудники с положительным балансом пока не найдены.')}
          </div>
        </section>
        <section class="card earnings-detail-card">
          ${detailContent}
        </section>
      </div>
      <section class="card earnings-settings-simple">
        <div class="section-header">
          <div>
            <div class="section-title">Настройка ставок</div>
            <div class="section-subtitle">Отдельные ставки для сборки товара и для сборки заказа. Новые значения действуют только для новых начислений.</div>
          </div>
        </div>
        <div class="earnings-settings-inline">
          <input class="input" id="earnings-pick-rate" value="${esc(earningsState.pickRateDraft || data?.settings?.pickItemRatePerUnit || data?.settings?.ratePerUnit || '')}" placeholder="Ставка за товар" />
          <input class="input" id="earnings-order-rate" value="${esc(earningsState.orderRateDraft || data?.settings?.orderCollectRatePerUnit || '0')}" placeholder="Ставка за заказ" />
          <button class="btn btn-primary btn-sm" id="btn-earnings-save-rate" ${earningsState.saveBusy ? 'disabled' : ''}>${earningsState.saveBusy ? 'Сохраняем...' : 'Сохранить ставки'}</button>
        </div>
      </section>
    ` : ''}
  </div>`;
}

