function renderEarningsMarketplaceCardV6(title, stat, tone = '') {
  const lastText = stat?.lastEventAt ? formatDateTime(stat.lastEventAt) : 'Пока нет начислений';
  const meta = [
    `Начислений: ${formatNumber(stat?.eventCount || 0, 0)}`,
    `Единиц: ${formatNumber(stat?.units || 0, 0)}`,
  ];
  if (Number.isFinite(Number(stat?.activeEmployees))) {
    meta.push(`Сотрудников: ${formatNumber(stat?.activeEmployees || 0, 0)}`);
  }
  return `<article class="earnings-v6-market-card${tone ? ` tone-${tone}` : ''}">
    <div class="earnings-v6-market-head">
      <div>
        <div class="earnings-v6-eyebrow">${esc(title || '—')}</div>
        <div class="earnings-v6-market-amount">${formatRubFromGra(stat?.amount || 0, 2)}</div>
      </div>
      <div class="earnings-v6-market-mark">${tone === 'wb' ? 'WB' : tone === 'oz' ? 'OZON' : esc(title || '—')}</div>
    </div>
    <div class="earnings-v6-market-meta">${meta.map((item) => `<span>${esc(item)}</span>`).join('')}</div>
    <div class="earnings-v6-market-note">${esc(lastText)}</div>
  </article>`;
}

