function renderStockContextList(contexts, entityLabel) {
  const items = Array.isArray(contexts) ? contexts : [];
  if (!items.length) return `<div class="stock-context-empty">Нет привязки к ${esc(entityLabel.toLowerCase())}</div>`;
  return `<div class="stock-context-list">${items.map((ctx) => `<div class="stock-context-item">
    <div class="stock-context-main">
      <span class="stock-context-chip">${esc(ctx?.entityDisplay || 'Без привязки')}</span>
      <strong>×${formatNumber(ctx?.quantity || 0)}</strong>
    </div>
    <div class="stock-context-meta">${[
      ctx?.shelfName ? `полка ${esc(ctx.shelfName)}` : '',
      ctx?.scannedBarcode ? `<span class="cell-mono">${esc(ctx.scannedBarcode)}</span>` : '',
      ctx?.createdAt ? esc(formatDateTime(ctx.createdAt)) : '',
    ].filter(Boolean).join(' • ') || 'Без деталей'}</div>
  </div>`).join('')}</div>`;
}

