// --- OZ Assembly Detail Modal ---
function ozRenderAssemblyDetailModal() {
  const a = ozState.selectedAssembly;
  if (!a) return '';
  const isCompleted = Number(ozState.assemblyTotals.total || 0) > 0 && Number(ozState.assemblyTotals.remaining || 0) === 0;
  let bodyHtml = '';
  if (ozState.assemblyTab === 'settings') bodyHtml = ozRenderAssemblySettingsTab();
  else if (ozState.assemblyTab === 'items') bodyHtml = ozRenderAssemblyItemsTab();
  else if (ozState.assemblyTab === 'shipment') bodyHtml = ozRenderAssemblyShipmentTab();
  else if (ozState.assemblyTab === 'labels') bodyHtml = ozRenderAssemblyLabelsTab();
  else bodyHtml = ozRenderAssemblyOrdersTab();
  return `<div class="modal-overlay" id="modal-assembly">
    <div class="modal-panel wide">
      <div class="modal-header">
        <div><div class="modal-title">${esc(a.name || 'Сборка ' + a.id)}${isCompleted ? ' <span class="text-success">СОБРАНА</span>' : ''}</div><div class="modal-subtitle">${esc(a.storeName || '')} \u2022 ${esc(a.id)}</div></div>
        <div class="modal-header-actions">
          ${ozState.assemblyTab === 'items' ? `<button class="btn btn-sm" id="btn-export-assembly-items">ЭКСПОРТ EXCEL</button>` : ''}
          <button class="btn btn-sm" id="btn-sync-assembly" ${ozState.assemblySyncBusy || ozState.settingsBusy ? 'disabled' : ''}>${ozState.assemblySyncBusy ? 'СИНХРОНИЗАЦИЯ...' : 'СИНХРОНИЗАЦИЯ'}</button>
          <button class="btn-icon" id="btn-close-assembly">&times;</button>
        </div>
      </div>
      <div class="modal-tabs">
        <button class="modal-tab ${ozState.assemblyTab === 'settings' ? 'active' : ''}" data-assembly-tab="settings">Настройка</button>
        <button class="modal-tab ${ozState.assemblyTab === 'shipment' ? 'active' : ''}" data-assembly-tab="shipment">Отгрузка</button>
        <button class="modal-tab ${ozState.assemblyTab === 'orders' ? 'active' : ''}" data-assembly-tab="orders">Заказы</button>
        <button class="modal-tab ${ozState.assemblyTab === 'items' ? 'active' : ''}" data-assembly-tab="items">Товары</button>
        <button class="modal-tab ${ozState.assemblyTab === 'labels' ? 'active' : ''}" data-assembly-tab="labels">Этикетки</button>
      </div>
      <div class="modal-body">${bodyHtml}</div>
    </div>
  </div>`;
}

