  bindSafeOverlayClose('#modal-create', () => { ozState.createOpen = false; ozState.createMode = 'count'; ozState.createLocationCode = DEFAULT_CREATE_LOCATION_CODE; ozState.createExcludeArticle = ''; ozState.createArticleMode = 'exclude'; ozState.createOnlyIndividuals = true; ozState.createAllowStockShortage = false; render(); });
