// OZ action handlers
async function ozHandleSyncAwaitingDeliver() {
  const API_BASE = getApiBase();
  ozState.syncBusy = true; ozState.syncError = ''; ozState.syncInfo = ''; render();
  try {
    const data = await ozAdminFetch(`${API_BASE}/assemblies/sync-awaiting-deliver`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ loadLabels: true }) });
    ozState.syncInfo = `В Ozon: ${data?.totalFromOzon || 0}, добавлено: ${data?.inserted || 0}, обновлено: ${data?.updated || 0}`;
    await ozLoadAssemblies({ silent: true });
    await ozLoadNewOrders({ silent: true });
  } catch (err) { if (ozHandleAuthError(err)) return; ozState.syncError = err?.message || 'Ошибка'; }
  finally { ozState.syncBusy = false; render(); }
}

async function ozHandleSyncAssembly() {
  if (!ozState.selectedAssembly || ozState.assemblySyncBusy) return;
  const confirmed = window.confirm('Сверить эту сборку с заказами Ozon в статусе «Ожидают отгрузки» и убрать лишние заказы у сотрудников?');
  if (!confirmed) return;
  const assembly = ozState.selectedAssembly;
  const API_BASE = getApiBase();
  ozState.assemblySyncBusy = true;
  ozState.settingsBusy = true;
  ozState.assemblySettingsNotice = '';
  ozState.assemblySettingsError = '';
  render();
  try {
    const data = await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(assembly.id)}/sync-awaiting-deliver`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({}),
    });
    const removed = Number(data?.removedOrdersCount || 0);
    const released = Number(data?.removedAssignedOrdersCount || 0);
    const failed = Number(data?.failedChecks || 0);
    ozState.assemblySettingsNotice = removed > 0
      ? `Синхронизация завершена. Убрано заказов: ${removed}. Снято у сотрудников: ${released}.${failed > 0 ? ` Не удалось проверить: ${failed}.` : ''}`
      : `Сборка актуальна. Активных заказов: ${Number(data?.totalOrders || 0)}.${failed > 0 ? ` Не удалось проверить: ${failed}.` : ''}`;
    await Promise.all([
      ozLoadAssemblySettings(assembly.id, { silent: true, preserveEditorState: false, skipSync: true }),
      ozLoadAssemblyOrders(assembly.id, { silent: true, skipSync: true }),
      ozLoadAssemblyLabelDiagnostics(assembly.id, { silent: true }),
      ozLoadAssemblies({ silent: true }),
    ]);
  } catch (err) {
    if (ozHandleAuthError(err)) return;
    ozState.assemblySettingsError = err?.message || 'Не удалось синхронизировать сборку';
  } finally {
    ozState.assemblySyncBusy = false;
    ozState.settingsBusy = false;
    render();
  }
}

async function ozHandleResolveScanIssue(issueId) {
  if (!issueId || ozState.scanIssueActionBusyId) return;
  const API_BASE = getApiBase();
  ozState.scanIssueActionBusyId = issueId; render();
  try { await ozAdminFetch(`${API_BASE}/settings/scan-issues/${issueId}/resolve`, { method: 'POST' }); ozState.scanIssues = ozState.scanIssues.filter(i => i.id !== issueId); }
  catch (err) { if (ozHandleAuthError(err)) return; ozState.scanIssuesError = err?.message || 'Ошибка'; }
  finally { ozState.scanIssueActionBusyId = null; render(); }
}

async function ozHandleFixScanIssue(issueId) {
  if (!issueId || ozState.scanIssueActionBusyId) return;
  const issue = ozState.scanIssues.find((item) => Number(item.id) === Number(issueId));
  const remainingQuantity = Math.max(0, Number(issue?.remainingQuantity || 0));
  if (issue?.issueStage === 'pick_scan' && remainingQuantity > 1 && !window.confirm(`Фикс завершит сразу ${remainingQuantity} шт. этого товара на этапе подбора. Продолжить?`)) return;
  const API_BASE = getApiBase();
  ozState.scanIssueActionBusyId = issueId; render();
  try { await ozAdminFetch(`${API_BASE}/settings/scan-issues/${issueId}/fix`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ confirmedQuantity: remainingQuantity }) }); ozState.scanIssues = ozState.scanIssues.filter(i => i.id !== issueId); }
  catch (err) { if (ozHandleAuthError(err)) return; ozState.scanIssuesError = err?.message || 'Ошибка'; }
  finally { ozState.scanIssueActionBusyId = null; render(); }
}

// --- OZ Helper functions ---
const OZ_LABEL_STATUS_LABELS = { idle: 'Ожидают загрузки', pending: 'Ожидают загрузки', loading: 'Загрузка', partial: 'Частично загружены', ready: 'Загружены', done: 'Загружены', error: 'Ошибка' };

function ozLabelsStatusLabel(status) {
  if (!status) return '\u2014';
  return OZ_LABEL_STATUS_LABELS[String(status).trim().toLowerCase()] || status;
}
function ozLabelErrorText(message) {
  const text = String(message || '').trim();
  if (!text) return '';
  const lower = text.toLowerCase();
  if (lower === 'fetch failed') return 'Ошибка сети при загрузке этикеток. Нажмите «Обновить этикетки» и повторите.';
  if (lower.includes('network') || lower.includes('fetch failed')) return 'Сетевая ошибка при загрузке этикеток. Нажмите «Обновить этикетки».';
  return text;
}
function formatOzonMarketplaceBarcode(sku) {
  const n = String(sku ?? '').trim();
  if (!n) return '';
  if (/^OZN/i.test(n)) return n;
  return /^\d+$/.test(n) ? `OZN${n}` : n;
}

function assignmentDraftUserLabel(employees, userId) {
  const normalizedUserId = Number(userId || 0);
  const employee = (Array.isArray(employees) ? employees : []).find((item) => Number(item?.id || 0) === normalizedUserId);
  if (!employee) return normalizedUserId ? `ID ${normalizedUserId}` : 'Не выбран';
  return `${employee.surname || ''} ${employee.name || ''}`.trim() || employee.fullName || `ID ${normalizedUserId}`;
}

function normalizeAssignmentDraftRow(row = {}) {
  const packerUserId = Number(row?.packerUserId || row?.packer_user_id || 0) || null;
  const pickerUserId = Number(row?.pickerUserId || row?.picker_user_id || 0) || null;
  const tableNo = [1, 2, 3].includes(Number(row?.tableNo || row?.table_no || 0)) ? Number(row?.tableNo || row?.table_no) : 1;
  return {
    packerUserId,
    pickerUserId: pickerUserId && pickerUserId !== packerUserId ? pickerUserId : null,
    tableNo,
  };
}

function buildDefaultAssignmentDraft(accessUsers = []) {
  return (Array.isArray(accessUsers) ? accessUsers : [])
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0)
    .map((userId) => ({
      packerUserId: userId,
      pickerUserId: null,
      tableNo: 1,
    }));
}

function compactAssignmentDraft(rows = [], accessUsers = []) {
  const allowedUsers = Array.from(new Set((Array.isArray(accessUsers) ? accessUsers : []).map((value) => Number(value)).filter((value) => Number.isFinite(value) && value > 0)));
  const used = new Set();
  const result = [];
  for (const rawRow of Array.isArray(rows) ? rows : []) {
    const row = normalizeAssignmentDraftRow(rawRow);
    if (!row.packerUserId || !allowedUsers.includes(row.packerUserId) || used.has(row.packerUserId)) continue;
    used.add(row.packerUserId);
    let pickerUserId = row.pickerUserId;
    if (!pickerUserId || !allowedUsers.includes(pickerUserId) || pickerUserId === row.packerUserId || used.has(pickerUserId)) {
      pickerUserId = null;
    }
    if (pickerUserId) used.add(pickerUserId);
    result.push({
      packerUserId: row.packerUserId,
      pickerUserId,
      tableNo: pickerUserId ? row.tableNo || 1 : 1,
    });
  }
  allowedUsers.forEach((userId) => {
    if (used.has(userId)) return;
    result.push({
      packerUserId: userId,
      pickerUserId: null,
      tableNo: 1,
    });
  });
  return result;
}

function assignmentDraftFromServer(parts = [], accessUsers = []) {
  const serverParts = Array.isArray(parts) && parts.length
    ? parts.map((part) => ({
        packerUserId: Number(part?.packerUserId || part?.packer_user_id || 0) || null,
        pickerUserId: Number(part?.pickerUserId || part?.picker_user_id || 0) || null,
        tableNo: Number(part?.tableNo || part?.table_no || 0) || 1,
      }))
    : buildDefaultAssignmentDraft(accessUsers);
  return compactAssignmentDraft(serverParts, accessUsers);
}

function serializeAssignmentDraft(parts = [], accessUsers = []) {
  return compactAssignmentDraft(parts, accessUsers).map((row, index) => ({
    partNo: index + 1,
    packerUserId: Number(row.packerUserId),
    pickerUserId: row.pickerUserId ? Number(row.pickerUserId) : null,
    tableNo: row.pickerUserId ? Number(row.tableNo || 1) : null,
  }));
}

function renderAssignmentDraftEditor(kind, employees, accessUsers, draftRows, busy) {
  const selectedUsers = Array.from(new Set((Array.isArray(accessUsers) ? accessUsers : []).map((value) => Number(value)).filter((value) => Number.isFinite(value) && value > 0)));
  const rows = compactAssignmentDraft(draftRows, selectedUsers);
  if (!selectedUsers.length) {
    return '<div class="hint">Сначала выберите сотрудников выше.</div>';
  }
  const optionsHtml = selectedUsers.map((userId) => `<option value="${esc(userId)}">${esc(assignmentDraftUserLabel(employees, userId))}</option>`).join('');
  return `<div class="progress-list">
    ${rows.map((row, index) => {
      const isSplit = Number(row.pickerUserId || 0) > 0 && Number(row.pickerUserId) !== Number(row.packerUserId);
      const summary = isSplit
        ? `Товар собирает ${assignmentDraftUserLabel(employees, row.pickerUserId)}, упаковывает ${assignmentDraftUserLabel(employees, row.packerUserId)}, стол ${row.tableNo || 1}`
        : `${assignmentDraftUserLabel(employees, row.packerUserId)} собирает и товар, и заказы`;
      return `<div class="settings-card" style="padding:12px">
        <div class="section-title">Часть ${index + 1}</div>
        <div class="form-grid">
          <label class="field">
            <span>Упаковщик</span>
            <select class="input" data-assignment-kind="${esc(kind)}" data-assignment-row="${index}" data-assignment-field="packer" ${busy ? 'disabled' : ''}>
              ${optionsHtml.replace(`value="${esc(row.packerUserId)}"`, `value="${esc(row.packerUserId)}" selected`)}
            </select>
          </label>
          <label class="field">
            <span>Сборщик товара</span>
            <select class="input" data-assignment-kind="${esc(kind)}" data-assignment-row="${index}" data-assignment-field="picker" ${busy ? 'disabled' : ''}>
              <option value="">Тот же сотрудник</option>
              ${optionsHtml.replace(`value="${esc(row.pickerUserId)}"`, `value="${esc(row.pickerUserId)}" selected`)}
            </select>
          </label>
          <label class="field">
            <span>Стол</span>
            <select class="input" data-assignment-kind="${esc(kind)}" data-assignment-row="${index}" data-assignment-field="table" ${busy || !isSplit ? 'disabled' : ''}>
              <option value="1" ${Number(row.tableNo || 1) === 1 ? 'selected' : ''}>Стол 1</option>
              <option value="2" ${Number(row.tableNo || 1) === 2 ? 'selected' : ''}>Стол 2</option>
              <option value="3" ${Number(row.tableNo || 1) === 3 ? 'selected' : ''}>Стол 3</option>
            </select>
          </label>
        </div>
        <div class="hint">${esc(summary)}</div>
      </div>`;
    }).join('')}
  </div>`;
}
function getAssignmentDraftState(kind) {
  if (kind === 'oz') {
    return {
      accessUsers: Array.isArray(ozState.accessUsers) ? ozState.accessUsers : [],
      draftRows: Array.isArray(ozState.assemblyAssignmentPartsDraft) ? ozState.assemblyAssignmentPartsDraft : [],
    };
  }
  return {
    accessUsers: Array.isArray(wbState.supplyAccessUsers) ? wbState.supplyAccessUsers : [],
    draftRows: Array.isArray(wbState.supplyAssignmentPartsDraft) ? wbState.supplyAssignmentPartsDraft : [],
  };
}

function setAssignmentDraftState(kind, draftRows, accessUsers = null) {
  const nextAccessUsers = Array.isArray(accessUsers)
    ? accessUsers.map((value) => Number(value)).filter((value) => Number.isFinite(value) && value > 0)
    : getAssignmentDraftState(kind).accessUsers;
  const nextDraftRows = compactAssignmentDraft(draftRows, nextAccessUsers);
  if (kind === 'oz') {
    ozState.accessUsers = nextAccessUsers;
    ozState.assemblyAssignmentPartsDraft = nextDraftRows;
    ozState.assemblyAccessDirty = true;
    return;
  }
  wbState.supplyAccessUsers = nextAccessUsers;
  wbState.supplyAssignmentPartsDraft = nextDraftRows;
  wbState.supplyAccessDirty = true;
}

function updateAssignmentDraftField(kind, rowIndex, field, rawValue) {
  const { accessUsers, draftRows } = getAssignmentDraftState(kind);
  const nextRows = compactAssignmentDraft(draftRows, accessUsers).map((row) => ({ ...row }));
  if (!nextRows[rowIndex]) return;
  if (field === 'packer') {
    nextRows[rowIndex].packerUserId = Number(rawValue || 0) || null;
  } else if (field === 'picker') {
    nextRows[rowIndex].pickerUserId = Number(rawValue || 0) || null;
  } else if (field === 'table') {
    nextRows[rowIndex].tableNo = [1, 2, 3].includes(Number(rawValue || 0)) ? Number(rawValue) : 1;
  }
  setAssignmentDraftState(kind, nextRows, accessUsers);
}

function getAssignmentDraftPayload(kind) {
  const { accessUsers, draftRows } = getAssignmentDraftState(kind);
  return serializeAssignmentDraft(draftRows, accessUsers);
}

function assignmentDraftHasSplitRoles(parts = []) {
  return (Array.isArray(parts) ? parts : []).some((part) => Number(part?.pickerUserId || 0) > 0 && Number(part?.pickerUserId || 0) !== Number(part?.packerUserId || 0));
}

function ozAggregateAssemblyItems(orders) {
  const map = new Map();
  for (const order of Array.isArray(orders) ? orders : []) {
    for (const item of Array.isArray(order?.items) ? order.items : []) {
      const article = String(item.article || '').trim() || '\u2014';
      const name = String(item.name || '').trim() || '\u2014';
      const sku = Number.isFinite(Number(item.sku)) ? Number(item.sku) : null;
      const key = `${article}::${name}::${sku ?? ''}`;
      if (!map.has(key)) map.set(key, { article, name, sku, marketplaceBarcode: formatOzonMarketplaceBarcode(sku), count: 0 });
      map.get(key).count += Math.max(0, Number(item.quantity || 0));
    }
  }
  return Array.from(map.values()).sort((a, b) => b.count - a.count);
}
function wbAggregateSupplyItems(orders) {
  const map = new Map();
  for (const order of Array.isArray(orders) ? orders : []) {
    const name = order?.productName || order?.article || '\u2014';
    const barcode = order?.barcode || '\u2014';
    const article = order?.article || '\u2014';
    const nmId = order?.nmId || '\u2014';
    const key = `${name}||${barcode}||${article}||${nmId}`;
    const rawQty = Number(order?.quantity ?? 1);
    const qty = Number.isFinite(rawQty) && rawQty > 0 ? rawQty : 1;
    const entry = map.get(key) || { name, barcode, article, nmId, count: 0 };
    entry.count += qty;
    map.set(key, entry);
  }
  return Array.from(map.values()).sort((a, b) => b.count - a.count);
}
function ozSortOrders(orders, sortDir) {
  const out = [...orders].sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));
  if (sortDir === 'newest') out.reverse();
  return out;
}
function ozPickOrdersByCount(orders, sortDir, count) {
  return ozSortOrders(orders, sortDir).slice(0, count);
}

function ozNormalizeWarehouseId(value) {
  const num = Number(value);
  return Number.isFinite(num) && num > 0 ? num : null;
}

function ozBuildWarehouseOptionsFromOrders(orders) {
  const map = new Map();
  for (const order of Array.isArray(orders) ? orders : []) {
    const warehouseId = ozNormalizeWarehouseId(order?.warehouseId);
    if (!warehouseId) continue;
    const warehouseName = String(order?.warehouseName || '').trim() || `Склад ${warehouseId}`;
    const deliveryMethodName = String(order?.deliveryMethodName || '').trim();
    if (!map.has(warehouseId)) {
      map.set(warehouseId, {
        warehouseId,
        warehouseName,
        label: warehouseName,
        deliveryMethodNames: [],
      });
    }
    const entry = map.get(warehouseId);
    if (deliveryMethodName && !entry.deliveryMethodNames.includes(deliveryMethodName)) {
      entry.deliveryMethodNames.push(deliveryMethodName);
    }
    const extraNames = entry.deliveryMethodNames.filter((value) => !value.toLowerCase().includes(warehouseName.toLowerCase()));
    entry.label = extraNames.length ? `${warehouseName} · ${extraNames.join(', ')}` : warehouseName;
  }
  return Array.from(map.values()).sort((a, b) => String(a.label || '').localeCompare(String(b.label || ''), 'ru'));
}

function ozGetActiveWarehouseOptions() {
  const active = Array.isArray(ozState.activeWarehouses) ? ozState.activeWarehouses : [];
  return active.length ? active : ozBuildWarehouseOptionsFromOrders(ozState.newOrders);
}

function ozResolveCreateWarehouseId() {
  const options = ozGetActiveWarehouseOptions();
  const current = ozNormalizeWarehouseId(ozState.createWarehouseId);
  if (current && options.some((item) => Number(item?.warehouseId || 0) === current)) return current;
  if (options.length === 1) return ozNormalizeWarehouseId(options[0]?.warehouseId);
  return null;
}

function ozGetSelectedForCreate() {
  return ozGetCreateSelection().selected;
}

function ozOpenCreateAssemblyModal() {
  ozState.createMode = 'count';
  ozState.createSort = 'oldest';
  ozState.createExcludeArticle = '';
  ozState.createLocationCode = DEFAULT_CREATE_LOCATION_CODE;
  ozState.createArticleMode = 'exclude';
  ozState.createOnlyIndividuals = true;
  ozState.createAllowStockShortage = false;
  ozState.createOpen = true;
  const selectedWarehouseId = ozResolveCreateWarehouseId();
  ozState.createWarehouseId = selectedWarehouseId ? String(selectedWarehouseId) : '';
  ozEnsureCityWarehouseMap(DEFAULT_CREATE_LOCATION_CODE);
  render();
}

function ozNormalizeCreateArticle(value) {
  return String(value || '').trim().toUpperCase().replace(/\s+/g, '');
}

function ozParseCreateArticles(value) {
  return Array.from(
    new Set(
      String(value || '')
        .split(/[,\n;]+/)
        .map((item) => ozNormalizeCreateArticle(item))
        .filter(Boolean)
    )
  );
}

function ozOrderItems(order) {
  return Array.isArray(order?.products) ? order.products : Array.isArray(order?.items) ? order.items : [];
}

function ozOrderArticleList(order) {
  return Array.from(
    new Set(
      ozOrderItems(order)
        .map((item) => ozNormalizeCreateArticle(item?.offerId || item?.article || ''))
        .filter(Boolean)
    )
  );
}

function ozOrderContainsExcludedArticles(order, excludedArticleSet) {
  if (!(excludedArticleSet instanceof Set) || !excludedArticleSet.size) return false;
  return ozOrderArticleList(order).some((article) => excludedArticleSet.has(article));
}

function ozOrderOnlyContainsSelectedArticles(order, selectedArticleSet) {
  if (!(selectedArticleSet instanceof Set) || !selectedArticleSet.size) return false;
  const articles = ozOrderArticleList(order);
  if (!articles.length) return false;
  return articles.every((article) => selectedArticleSet.has(article));
}

function ozCountSelectedArticleUnits(orders, articleSet) {
  if (!(articleSet instanceof Set) || !articleSet.size) return 0;
  return (Array.isArray(orders) ? orders : []).reduce((total, order) => (
    total + ozOrderItems(order).reduce((orderTotal, item) => {
      const article = ozNormalizeCreateArticle(item?.offerId || item?.article || '');
      return orderTotal + (articleSet.has(article) ? Math.max(1, Number(item?.quantity || 1)) : 0);
    }, 0)
  ), 0);
}

function ozIsIndividualOrder(order) {
  return !(order?.isLegal === true || order?.customerType === 'business' || order?.isB2B === true);
}

function ozGetCustomerTypeLabel(order) {
  return ozIsIndividualOrder(order) ? 'Физлицо' : 'Не физлицо';
}

function ozSplitNewOrders(orders) {
  const source = Array.isArray(orders) ? orders : [];
  const individualOrders = [];
  const nonIndividualOrders = [];
  source.forEach((order) => {
    if (ozIsIndividualOrder(order)) individualOrders.push(order);
    else nonIndividualOrders.push(order);
  });
  return { individualOrders, nonIndividualOrders };
}

function ozGetCreateSelection() {
  const selectedWarehouseId = ozResolveCreateWarehouseId();
  const requestedCount = Math.max(1, Number(ozState.createCount) || 1);
  const sourceOrders = selectedWarehouseId
    ? (Array.isArray(ozState.newOrders) ? ozState.newOrders : []).filter(
        (order) => ozNormalizeWarehouseId(order?.warehouseId) === selectedWarehouseId
      )
    : [];
  const clientEligibleOrders = ozState.createOnlyIndividuals
    ? sourceOrders.filter((order) => ozIsIndividualOrder(order))
    : sourceOrders;
  const excludedArticles = ozParseCreateArticles(ozState.createExcludeArticle);
  const excludedArticleSet = new Set(excludedArticles);
  const includeMode = ozState.createArticleMode === 'include';
  // include: оставляем ТОЛЬКО заказы с выбранными артикулами; exclude: убираем их.
  const filteredOrders = includeMode
    ? (excludedArticleSet.size
        ? clientEligibleOrders.filter((order) => ozOrderOnlyContainsSelectedArticles(order, excludedArticleSet))
        : [])
    : (excludedArticleSet.size
        ? clientEligibleOrders.filter((order) => !ozOrderContainsExcludedArticles(order, excludedArticleSet))
        : clientEligibleOrders);
  const selected = ozPickOrdersByCount(filteredOrders, ozState.createSort, requestedCount);
  return {
    selectedWarehouseId,
    requestedCount,
    selected,
    warehouseTotal: sourceOrders.length,
    clientFilteredCount: Math.max(0, sourceOrders.length - clientEligibleOrders.length),
    clientEligibleCount: clientEligibleOrders.length,
    excludedArticles,
    articleMode: includeMode ? 'include' : 'exclude',
    excludedCount: Math.max(0, clientEligibleOrders.length - filteredOrders.length),
    availableAfterExclude: filteredOrders.length,
    selectedArticleUnitCount: includeMode ? ozCountSelectedArticleUnits(selected, excludedArticleSet) : 0,
    availableArticleUnitCount: includeMode ? ozCountSelectedArticleUnits(filteredOrders, excludedArticleSet) : 0,
  };
}

ozRenderNewOrders = function ozRenderNewOrdersV2() {
  const allOrders = sortOrdersOldestFirst(ozState.newOrders);
  const { individualOrders, nonIndividualOrders } = ozSplitNewOrders(allOrders);
  const activeWarehouses = ozGetActiveWarehouseOptions();
  const renderOrderRow = (order, tone = 'normal') => {
    const items = ozOrderItems(order);
    const productsHtml = items.length === 0
      ? '—'
      : items.map((item) => `<div class="order-product-row"><span class="order-product-name">${esc(item.name || '—')}</span>${Number(item.quantity || 1) > 1 ? ` <span class="cell-muted">×${item.quantity}</span>` : ''}</div>`).join('');
    const articles = ozOrderArticleList(order);
    const warehouseName = String(order?.warehouseName || '').trim() || '—';
    const deliveryMethodName = String(order?.deliveryMethodName || '').trim();
    const rowClasses = [tone === 'danger' ? 'wb-order-row-danger' : '', orderAgeClass(order?.createdAt)].filter(Boolean).join(' ');
    return `<tr class="${rowClasses}">
      <td><div class="cell-primary cell-mono">${esc(order.postingNumber || '—')}</div></td>
      <td><div class="cell-primary">${esc(warehouseName)}</div>${deliveryMethodName ? `<div class="cell-muted">${esc(deliveryMethodName)}</div>` : ''}</td>
      <td>${productsHtml}</td>
      <td class="cell-mono">${articles.length ? articles.map((article) => esc(article)).join('<br>') : '—'}</td>
      <td><span class="pill ${tone === 'danger' ? 'wb-order-pill-danger' : ''}">${esc(ozGetCustomerTypeLabel(order))}</span></td>
      <td class="r"><span class="pill pill-created-time">${esc(timeAgo(order.createdAt))}</span></td>
    </tr>`;
  };
  return `<div class="card">
    <div class="actions-bar"><div class="actions-bar-left">
      <button class="btn btn-sm" id="btn-refresh-new" ${ozState.newLoading ? 'disabled' : ''}>ОБНОВИТЬ СПИСОК</button>
      <span class="hint">${ozState.newUpdatedAt ? `Обновлено: ${ozState.newUpdatedAt.toLocaleTimeString('ru-RU')}` : ''}</span>
    </div><div class="actions-bar-right">
      <span class="pill">Физлица: ${individualOrders.length}</span>
      <span class="pill ${nonIndividualOrders.length > 0 ? 'wb-order-pill-danger' : ''}">Не физлица: ${nonIndividualOrders.length}</span>
      ${activeWarehouses.length ? activeWarehouses.map((item) => `<span class="pill">${esc(item?.label || item?.warehouseName || `Склад ${item?.warehouseId || ''}`)}</span>`).join('') : '<span class="hint">Активные склады не найдены</span>'}
    </div></div>
    ${nonIndividualOrders.length > 0 ? `<div class="alert alert-error wb-new-orders-warning">Не от физлиц: ${nonIndividualOrders.length}. Эти заказы вынесены сверху отдельно и не попадут в сборку, если включён фильтр "Только физлица".</div>
    <table class="tbl new-orders-table wb-new-orders-danger-table"><thead><tr><th>Заказ</th><th>Склад</th><th>Товары</th><th>Артикул</th><th>Тип</th><th class="r">Создан</th></tr></thead>
    <tbody>${nonIndividualOrders.map((order) => renderOrderRow(order, 'danger')).join('')}</tbody></table>` : ''}
    <table class="tbl new-orders-table"><thead><tr><th>Заказ</th><th>Склад</th><th>Товары</th><th>Артикул</th><th>Тип</th><th class="r">Создан</th></tr></thead>
    <tbody>${ozState.newLoading ? '<tr><td colspan="6" class="tbl-empty">Загрузка...</td></tr>' : individualOrders.length === 0 ? '<tr><td colspan="6" class="tbl-empty">Нет заказов от физлиц</td></tr>' : individualOrders.map((order) => renderOrderRow(order)).join('')}</tbody></table>
    ${ozState.newError ? `<div class="alert alert-error" style="margin:8px 14px">${esc(ozState.newError)}</div>` : ''}
  </div>`;
};

