function wbPickOrders(orders, sortDir, count) {
  const sorted = [...orders].sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
  if (sortDir === 'newest') sorted.reverse();
  if (!sorted.length) return { selected: [], available: 0, warehouseId: null, cargoType: null };
  const normalizedCount = Math.max(1, Number(count) || 1);
  const groups = [];
  const groupMap = new Map();
  sorted.forEach((order) => {
    const key = `${order?.warehouseId ?? ''}::${order?.cargoType ?? ''}`;
    let group = groupMap.get(key);
    if (!group) {
      group = {
        key,
        warehouseId: order?.warehouseId ?? null,
        cargoType: order?.cargoType ?? null,
        items: [],
        firstIndex: groups.length,
      };
      groupMap.set(key, group);
      groups.push(group);
    }
    group.items.push(order);
  });
  const groupWithEnoughOrders = groups.find((group) => group.items.length >= normalizedCount);
  const selectedGroup = groupWithEnoughOrders || groups.slice().sort((a, b) => {
    if (b.items.length !== a.items.length) return b.items.length - a.items.length;
    return a.firstIndex - b.firstIndex;
  })[0];
  const filtered = Array.isArray(selectedGroup?.items) ? selectedGroup.items : [];
  return {
    selected: filtered.slice(0, normalizedCount),
    available: filtered.length,
    warehouseId: selectedGroup?.warehouseId ?? null,
    cargoType: selectedGroup?.cargoType ?? null,
  };
}

function wbNormalizeCreateArticle(value) {
  return String(value || '').trim().toUpperCase().replace(/\s+/g, '');
}

function wbNormalizeCreateArticleFamily(value) {
  const article = wbNormalizeCreateArticle(value);
  return article ? article.replace(/_\d+$/i, '') : '';
}

function wbParseCreateArticles(value) {
  return Array.from(
    new Set(
      String(value || '')
        .split(/[,\n;]+/)
        .map((item) => wbNormalizeCreateArticle(item))
      .filter(Boolean)
    )
  );
}

function wbBuildExcludedArticleMatcher(values) {
  const exact = new Set();
  const families = new Set();
  (Array.isArray(values) ? values : [values]).forEach((value) => {
    const exactKey = wbNormalizeCreateArticle(value);
    if (!exactKey) return;
    exact.add(exactKey);
    const familyKey = wbNormalizeCreateArticleFamily(exactKey);
    if (familyKey) families.add(familyKey);
  });
  return { exact, families };
}

function wbOrderMatchesExcludedArticle(order, matcher) {
  if (!matcher || !(matcher.exact instanceof Set) || !(matcher.families instanceof Set)) return false;
  const exactKey = wbNormalizeCreateArticle(order?.article);
  if (!exactKey) return false;
  if (matcher.exact.has(exactKey)) return true;
  const familyKey = wbNormalizeCreateArticleFamily(exactKey);
  return Boolean(familyKey && matcher.families.has(familyKey));
}

function wbCountSelectedArticleUnits(orders, matcher) {
  return (Array.isArray(orders) ? orders : []).reduce((total, order) => (
    total + (wbOrderMatchesExcludedArticle(order, matcher) ? Math.max(1, Number(order?.quantity || 1)) : 0)
  ), 0);
}

function wbIsIndividualOrder(order) {
  return !(order?.isB2B === true || order?.customerType === 'business');
}

function wbGetCustomerTypeLabel(order) {
  return wbIsIndividualOrder(order) ? '\u0424\u0438\u0437\u043b\u0438\u0446\u043e' : '\u041d\u0435 \u0444\u0438\u0437\u043b\u0438\u0446\u043e';
}

function wbSplitNewOrders(orders) {
  const source = Array.isArray(orders) ? orders : [];
  const individualOrders = [];
  const nonIndividualOrders = [];
  source.forEach((order) => {
    if (wbIsIndividualOrder(order)) individualOrders.push(order);
    else nonIndividualOrders.push(order);
  });
  return { individualOrders, nonIndividualOrders };
}

function wbNormalizeWarehouseId(value) {
  const num = Number(value);
  return Number.isFinite(num) && num > 0 ? num : null;
}
// Подтягивает привязку «город → WB-склад» (site_location_warehouse_settings, marketplace=wb)
// при выборе города в модалке создания поставки. Зеркало ozEnsureCityWarehouseMap.
async function wbEnsureCityWarehouseMap(locationCode) {
  const code = String(locationCode || '');
  const storeId = String(wbState.storeId || '');
  if (!code) { wbState.createCityWh = null; return; }
  if (wbState.createCityWh && wbState.createCityWh.location === code && wbState.createCityWh.storeId === storeId && !wbState.createCityWh.loading) return;
  wbState.createCityWh = { location: code, storeId, loading: true, warehouses: [], error: '' };
  // без render() здесь — лишний ре-рендер съедал первый клик по кнопке создания
  try {
    let data;
    try {
      data = await wbAdminFetch(`${getApiBase()}/location-warehouse-map?location=${encodeURIComponent(code)}`);
    } catch {
      data = await wbAdminFetch(`${getApiBase()}/location-warehouse-map?location=${encodeURIComponent(code)}`);
    }
    if (String(wbState.createLocationCode || '') !== code || String(wbState.storeId || '') !== storeId) return;
    wbState.createCityWh = { location: code, storeId, loading: false, warehouses: Array.isArray(data?.warehouses) ? data.warehouses : [], error: '' };
  } catch (err) {
    wbState.createCityWh = { location: code, storeId, loading: false, warehouses: [], error: err?.message || 'Не удалось получить настройки города' };
  }
  render();
}
// Набор WB-складов, привязанных к текущему городу создания. mapped=false → у города
// нет конкретной привязки WB-склада (напр. Ижевск = marketplace 'all') → НЕ фильтруем.
function wbGetCityWarehouseIdSet() {
  const code = String(wbState.createLocationCode || '');
  const storeId = String(wbState.storeId || '');
  const cityWh = wbState.createCityWh && wbState.createCityWh.location === code && wbState.createCityWh.storeId === storeId ? wbState.createCityWh : null;
  if (!code || !cityWh || cityWh.loading) return { set: null, mapped: false, loading: !!(cityWh && cityWh.loading) };
  const ids = (cityWh.warehouses || []).map((w) => wbNormalizeWarehouseId(w.marketplaceWarehouseId)).filter(Boolean);
  if (!ids.length) return { set: null, mapped: false, loading: false };
  return { set: new Set(ids), mapped: true, loading: false };
}
function wbFilterOrdersByCityWarehouse(orders) {
  const { set, mapped } = wbGetCityWarehouseIdSet();
  if (!mapped || !set) return orders; // город без привязки WB-склада → показываем всё (как раньше)
  return orders.filter((order) => set.has(wbNormalizeWarehouseId(order?.warehouseId)));
}
function wbGetCreateSelection() {
  const requestedCount = Math.max(1, Number(wbState.createCount) || 1);
  const excludedArticles = wbParseCreateArticles(wbState.createExcludeArticle);
  const excludedMatcher = wbBuildExcludedArticleMatcher(excludedArticles);
  const allNewOrders = Array.isArray(wbState.newOrders) ? wbState.newOrders : [];
  // КЛЮЧЕВОЙ ФИКС: заказы, не относящиеся к WB-складу выбранного города, отбрасываем
  // ДО подсчёта («будет выбрано»), чтобы не показывать заказы других складов/городов.
  const cityWh = wbGetCityWarehouseIdSet();
  const sourceOrders = wbFilterOrdersByCityWarehouse(allNewOrders);
  const clientEligibleOrders = wbState.createOnlyIndividuals ? sourceOrders.filter((order) => wbIsIndividualOrder(order)) : sourceOrders;
  const includeMode = wbState.createArticleMode === 'include';
  const hasSel = excludedMatcher.exact.size > 0 || excludedMatcher.families.size > 0;
  // include: оставляем ТОЛЬКО заказы с выбранными артикулами; exclude: убираем их.
  const filteredOrders = includeMode
    ? (hasSel
        ? clientEligibleOrders.filter((order) => wbOrderMatchesExcludedArticle(order, excludedMatcher))
        : [])
    : (hasSel
        ? clientEligibleOrders.filter((order) => !wbOrderMatchesExcludedArticle(order, excludedMatcher))
        : clientEligibleOrders);
  const selection = wbPickOrders(filteredOrders, wbState.createSort, requestedCount);
  return {
    ...selection,
    requestedCount,
    excludedArticles,
    articleMode: includeMode ? 'include' : 'exclude',
    excludedCount: Math.max(0, clientEligibleOrders.length - filteredOrders.length),
    totalOrders: sourceOrders.length,
    clientFilteredCount: Math.max(0, sourceOrders.length - clientEligibleOrders.length),
    clientEligibleCount: clientEligibleOrders.length,
    availableAfterExclude: filteredOrders.length,
    selectedArticleUnitCount: includeMode ? wbCountSelectedArticleUnits(selection.selected, excludedMatcher) : 0,
    availableArticleUnitCount: includeMode ? wbCountSelectedArticleUnits(filteredOrders, excludedMatcher) : 0,
    warehouseMapped: cityWh.mapped,
    warehouseMapLoading: cityWh.loading,
    otherWarehouseCount: cityWh.mapped ? Math.max(0, allNewOrders.length - sourceOrders.length) : 0,
    allNewOrdersCount: allNewOrders.length,
  };
}

