async function ozHandleAccessModeChange(mode) {
  if (!ozState.selectedAssembly || mode === ozState.accessMode) return;
  const API_BASE = getApiBase();
  ozState.settingsBusy = true; ozState.assemblySettingsNotice = ''; ozState.assemblySettingsError = ''; render();
  try {
    await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(ozState.selectedAssembly.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ accessMode: mode }) });
    await Promise.all([ozLoadAssemblySettings(ozState.selectedAssembly.id, { silent: true, preserveEditorState: false }), ozLoadAssemblyOrders(ozState.selectedAssembly.id, { silent: true }), ozLoadAssemblies({ silent: true })]);
  } catch (err) { if (ozHandleAuthError(err)) return; ozState.assemblySettingsError = err?.message || 'Ошибка'; }
  finally { ozState.settingsBusy = false; render(); }
}
