    await Promise.all([ozLoadAssemblySettings(ozState.selectedAssembly.id, { silent: true, preserveEditorState: false }), ozLoadAssemblyOrders(ozState.selectedAssembly.id, { silent: true }), ozLoadAssemblies({ silent: true })]);
