function ozGetAdminWorkflowStageLocal(mode, accessMode) {
  const nextAccessMode = accessMode === 'selected_split' ? 'selected_split' : 'hidden';
  return mode === 'picking' && nextAccessMode === 'selected_split' ? 'pick_pending' : 'orders_only';
}

function ozSnapshotAdminAssemblyState() {
  const assemblyId = ozState.selectedAssembly?.id || null;
  return {
    accessMode: ozState.accessMode,
    assemblySettings: ozState.assemblySettings ? { ...ozState.assemblySettings } : null,
    selectedAssembly: ozState.selectedAssembly ? { ...ozState.selectedAssembly } : null,
    assemblies: Array.isArray(ozState.assemblies)
      ? ozState.assemblies.map((item) => (String(item?.id) === String(assemblyId) ? { ...item } : item))
      : [],
  };
}

function ozRestoreAdminAssemblyState(snapshot) {
  if (!snapshot) return;
  ozState.accessMode = snapshot.accessMode;
  ozState.assemblySettings = snapshot.assemblySettings;
  ozState.selectedAssembly = snapshot.selectedAssembly;
  ozState.assemblies = Array.isArray(snapshot.assemblies) ? snapshot.assemblies : ozState.assemblies;
}

function ozApplyAdminAssemblySettingPatch(patch = {}) {
  const assemblyId = ozState.selectedAssembly?.id;
  if (!assemblyId) return;
  const nextAccessMode = Object.prototype.hasOwnProperty.call(patch, 'accessMode')
    ? (patch.accessMode === 'selected_split' ? 'selected_split' : 'hidden')
    : ozState.accessMode;
  if (ozState.assemblySettings) {
    ozState.assemblySettings = { ...ozState.assemblySettings, ...patch, accessMode: nextAccessMode };
  }
  ozState.accessMode = nextAccessMode;
  if (ozState.selectedAssembly && String(ozState.selectedAssembly.id) === String(assemblyId)) {
    ozState.selectedAssembly = { ...ozState.selectedAssembly, ...patch, accessMode: nextAccessMode };
  }
  if (Array.isArray(ozState.assemblies)) {
    ozState.assemblies = ozState.assemblies.map((item) => (
      String(item?.id) === String(assemblyId)
        ? { ...item, ...patch, accessMode: nextAccessMode }
        : item
    ));
  }
}

async function ozHandleEmployeeWorkflowModeToggle(checked) {
  if (!ozState.selectedAssembly) return;
  const nextMode = checked ? 'picking' : 'legacy';
  const API_BASE = getApiBase();
  const snapshot = ozSnapshotAdminAssemblyState();
  ozApplyAdminAssemblySettingPatch({
    employeeWorkflowMode: nextMode,
    employeeWorkflowStage: ozGetAdminWorkflowStageLocal(nextMode, ozState.accessMode),
  });
  ozState.settingsBusy = true;
  ozState.assemblySettingsError = '';
  render();
  try {
    await ozAdminFetch(`${API_BASE}/assemblies/${encodeURIComponent(ozState.selectedAssembly.id)}/settings`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ employeeWorkflowMode: nextMode }),
    });
    await Promise.all([
      ozLoadAssemblySettings(ozState.selectedAssembly.id, { silent: true, preserveEditorState: false, skipSync: true }),
      ozLoadAssemblies({ silent: true }),
    ]);
  } catch (err) {
    if (ozHandleAuthError(err)) return;
    ozRestoreAdminAssemblyState(snapshot);
    ozState.assemblySettingsError = err?.message || 'Ошибка';
  } finally {
    ozState.settingsBusy = false;
    render();
  }
}

