async function ozHandleExportAssemblyItems() {
  if (!ozState.selectedAssembly) return;
  const items = ozAggregateAssemblyItems(ozState.assemblyOrders);
  if (!items.length) { showToast('Нет товаров для экспорта.'); return; }
  const rows = items.map(i => ({ 'Артикул': i.article, 'Название': i.name, 'Штрихкод Ozon': i.marketplaceBarcode || '', 'Кол-во': i.count }));
  await exportExcel(rows, ['Артикул', 'Название', 'Штрихкод Ozon', 'Кол-во'], [20, 40, 20, 10], `assembly_${ozState.selectedAssembly.id}_items.xlsx`);
}
async function ozHandleExportAssemblyEmployeeItems(entry) {
  if (!ozState.selectedAssembly || !entry?.userId) return;
  let orders = ozState.assemblyOrders;
  if (!orders.length) orders = await ozLoadAssemblyOrders(ozState.selectedAssembly.id, { silent: true });
  const assigned = (Array.isArray(orders) ? orders : []).filter(o => Number(o?.assignedUserId || 0) === Number(entry.userId));
  const items = ozAggregateAssemblyItems(assigned);
  if (!items.length) { showToast('Нет назначенных товаров.'); return; }
  const rows = items.map(i => ({ 'Артикул': i.article, 'Название': i.name, 'Штрихкод Ozon': i.marketplaceBarcode || '', 'Кол-во': i.count }));
  const fileSurname = sanitizeFilePart(entry.surname || `employee_${entry.userId}`, `employee_${entry.userId}`);
  const total = items.reduce((s, i) => s + Number(i.count || 0), 0);
  await exportExcel(rows, ['Артикул', 'Название', 'Штрихкод Ozon', 'Кол-во'], [20, 40, 20, 10], `${fileSurname}_${total}.xlsx`);
}
async function ozHandleCreateAssembly() {
  if (ozState.createBusy) return;
  if (!ozState.storeId) { ozState.createError = '\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043c\u0430\u0433\u0430\u0437\u0438\u043d'; render(); return; }
  if (!ozState.storeId) { ozState.createError = 'Выберите магазин'; render(); return; }
  const locationCode = String(ozState.createLocationCode || '').trim();
  if (!locationCode) { ozState.createError = 'Выберите город сборки'; render(); return; }
  const selectedWarehouseId = ozResolveCreateWarehouseId();
  if (!selectedWarehouseId) { ozState.createError = 'Выберите активный склад Ozon'; render(); return; }
  ozState.createError = '';
  const selected = ozGetSelectedForCreate();
  if (!selected.length) { ozState.createError = '\u041d\u0435\u0442 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0445 \u0437\u0430\u043a\u0430\u0437\u043e\u0432'; render(); return; }
  if (!selected.length) { ozState.createError = 'Нет выбранных заказов'; render(); return; }
  ozState.createBusy = true; render();
  const API_BASE = getApiBase();
  try {
    const data = await ozAdminFetch(`${API_BASE}/assemblies/create`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ postingNumbers: selected.map(o => o.postingNumber), warehouseId: selectedWarehouseId, locationCode, desktopPrint: ozState.createDesktopPrint === true, allowStockShortage: ozState.createAllowStockShortage === true, selectionMode: ozState.createArticleMode === 'include' ? 'articles' : 'count', selectedArticles: ozState.createArticleMode === 'include' ? ozParseCreateArticles(ozState.createExcludeArticle) : [] }), timeoutMs: CREATE_FETCH_TIMEOUT_MS });
    ozState.createBusy = false; ozState.createOpen = false; ozState.createError = ''; ozState.createLocationCode = DEFAULT_CREATE_LOCATION_CODE; ozState.createExcludeArticle = ''; ozState.createArticleMode = 'exclude'; ozState.createOnlyIndividuals = true; ozState.createAllowStockShortage = false;
    await ozLoadNewOrders({ silent: true });
    await ozLoadAssemblies({ silent: true });
    if (data?.assemblyId) {
      const assembly = { id: data.assemblyId, name: data.assemblyName || 'Сборка Ozon' };
      ozState.selectedAssembly = assembly; ozState.assemblyTab = 'settings'; ozState.assemblySettingsNotice = ''; ozState.assemblyEmployeeQuery = ''; ozState.assemblyAccessDirty = false; ozState.shipmentError = ''; ozState.shipmentNotice = '';
      ozLoadAssemblySettings(assembly.id); ozLoadAssemblyOrders(assembly.id); ozLoadAssemblyLabelDiagnostics(assembly.id);
    }
  } catch (err) { if (ozHandleAuthError(err)) return; ozState.createError = err?.message || 'Не удалось создать сборку'; ozState.createBusy = false; }
  render();
}

// --- WB Supply Action Handlers ---
function wbGetAdminWorkflowStageLocal(mode, accessMode) {
  const nextAccessMode = accessMode === 'selected_split' ? 'selected_split' : 'hidden';
  return mode === 'picking' && nextAccessMode === 'selected_split' ? 'pick_pending' : 'orders_only';
}

function wbSnapshotAdminSupplyState() {
  const supplyId = wbState.selectedSupply?.id || null;
  return {
    supplyAccessMode: wbState.supplyAccessMode,
    supplySettings: wbState.supplySettings ? { ...wbState.supplySettings } : null,
    selectedSupply: wbState.selectedSupply ? { ...wbState.selectedSupply } : null,
    supplies: Array.isArray(wbState.supplies)
      ? wbState.supplies.map((item) => (String(item?.id) === String(supplyId) ? { ...item } : item))
      : [],
  };
}

function wbRestoreAdminSupplyState(snapshot) {
  if (!snapshot) return;
  wbState.supplyAccessMode = snapshot.supplyAccessMode;
  wbState.supplySettings = snapshot.supplySettings;
  wbState.selectedSupply = snapshot.selectedSupply;
  wbState.supplies = Array.isArray(snapshot.supplies) ? snapshot.supplies : wbState.supplies;
}

function wbApplyAdminSupplySettingPatch(patch = {}) {
  const supplyId = wbState.selectedSupply?.id;
  if (!supplyId) return;
  const nextAccessMode = Object.prototype.hasOwnProperty.call(patch, 'accessMode')
    ? (patch.accessMode === 'selected_split' ? 'selected_split' : 'hidden')
    : wbState.supplyAccessMode;
  if (wbState.supplySettings) {
    wbState.supplySettings = { ...wbState.supplySettings, ...patch, accessMode: nextAccessMode };
  }
  wbState.supplyAccessMode = nextAccessMode;
  if (wbState.selectedSupply && String(wbState.selectedSupply.id) === String(supplyId)) {
    wbState.selectedSupply = { ...wbState.selectedSupply, ...patch, accessMode: nextAccessMode };
  }
  if (Array.isArray(wbState.supplies)) {
    wbState.supplies = wbState.supplies.map((item) => (
      String(item?.id) === String(supplyId)
        ? { ...item, ...patch, accessMode: nextAccessMode }
        : item
    ));
  }
}

async function wbHandleAccessModeChange(mode) {
  if (!wbState.selectedSupply) return;
  const API_BASE = getApiBase();
  wbState.settingsBusy = true; wbState.supplySettingsNotice = ''; wbState.supplySettingsError = ''; render();
  try {
    await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ accessMode: mode }) });
    await wbLoadSupplySettings(wbState.selectedSupply, { silent: true }); wbState.supplySettingsNotice = 'Настройки сохранены.';
  } catch (err) { if (wbHandleAuthError(err)) return; wbState.supplySettingsError = err?.message || 'Ошибка'; }
  finally { wbState.settingsBusy = false; render(); }
}
async function wbHandleWorkflowModeChange(checked) {
  if (!wbState.selectedSupply) return;
  const API_BASE = getApiBase();
  const snapshot = wbSnapshotAdminSupplyState();
  const nextMode = checked ? 'picking' : 'legacy';
  wbApplyAdminSupplySettingPatch({
    employeeWorkflowMode: nextMode,
    employeeWorkflowStage: wbGetAdminWorkflowStageLocal(nextMode, wbState.supplyAccessMode),
  });
  wbState.settingsBusy = true; wbState.supplySettingsError = ''; render();
  try {
    await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ employeeWorkflowMode: nextMode }) });
    await wbLoadSupplySettings(wbState.selectedSupply, { silent: true });
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbRestoreAdminSupplyState(snapshot);
    wbState.supplySettingsError = err?.message || 'Ошибка';
  }
  finally { wbState.settingsBusy = false; render(); }
}
async function wbHandleStockMethodChange(enabled) {
  if (!wbState.selectedSupply) return;
  const API_BASE = getApiBase();
  const snapshot = wbSnapshotAdminSupplyState();
  wbApplyAdminSupplySettingPatch({ stockMethodEnabled: enabled });
  wbState.settingsBusy = true; wbState.supplySettingsError = ''; render();
  try {
    await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ stockMethodEnabled: enabled }) });
    await wbLoadSupplySettings(wbState.selectedSupply, { silent: true });
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbRestoreAdminSupplyState(snapshot);
    wbState.supplySettingsError = err?.message || 'Ошибка';
  }
  finally { wbState.settingsBusy = false; render(); }
}
