  if (wbState.supplySettings) {
    wbState.supplySettings.allowNoScan = enabled;
    if (enabled) wbState.supplySettings.partialSafeScan = false;
  }
  wbState.settingsBusy = true;
  wbState.supplySettingsError = '';
  render();
