    await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ allowNoScan: enabled }) });
    wbState.supplySettingsNotice = enabled
