async function wbHandleSetSupplyLocation(code) {
  if (!wbState.selectedSupply) return;
  const API_BASE = getApiBase();
  const prev = wbState.supplySettings?.locationCode || '';
  const next = String(code || '').trim();
  if (!next || next === prev) return;
  // город сменился — сбрасываем выбранных упаковщиков (могли быть из другого города)
  wbState.supplyAccessUsers = [];
  wbState.supplyAccessDirty = false;
  wbState.settingsBusy = true;
  render();
  try {
    await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/settings`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ locationCode: next }) });
    wbState.settingsBusy = false;
    // перезагружаем настройки — сервер вернёт упаковщиков, отфильтрованных по новому городу
    await wbLoadSupplySettings(wbState.selectedSupply);
    wbState.supplySettingsNotice = 'Город поставки сохранён — упаковщики отобраны по городу.';
  } catch (err) {
    wbState.settingsBusy = false;
    if (wbHandleAuthError(err)) return;
    wbState.supplySettingsError = err?.message || 'Не удалось сохранить город';
  } finally { render(); }
}
