async function wbHandleExcludeProduct(article) {
  if (!wbState.selectedSupply || !article) return;
  const confirmed = window.confirm(`Исключить товар ${article} из этой поставки?\nВсе его заказы будут убраны из сборки у сотрудников. В кабинете WB заказы останутся — если товар появится, пересинхронизируйте поставку.`);
  if (!confirmed) return;
  const API_BASE = getApiBase();
  wbState.settingsBusy = true; wbState.supplySettingsNotice = ''; wbState.supplySettingsError = ''; render();
  try {
    const data = await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/exclude-product`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ article }),
    });
    await wbLoadSupplyOrders(wbState.selectedSupply);
    await wbLoadSupplySettings(wbState.selectedSupply, { silent: true });
    wbState.supplySettingsNotice = `Товар ${article} исключён: убрано заказов ${data?.removedOrders || 0}.`;
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbState.supplySettingsError = err?.message || 'Не удалось исключить товар';
  } finally {
    wbState.settingsBusy = false; render();
  }
}

async function wbHandleSyncSupply() {
  if (!wbState.selectedSupply) return;
  const confirmed = window.confirm('Проверить поставку на WB и убрать лишние заказы у сотрудников?');
  if (!confirmed) return;
  const API_BASE = getApiBase();
  wbState.settingsBusy = true; wbState.supplySettingsNotice = ''; wbState.supplySettingsError = ''; render();
  try {
    const data = await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ supplyName: wbState.selectedSupply?.name || null }),
    });
    if (data?.sync && wbState.supplySettings) {
      wbState.supplySettings = { ...wbState.supplySettings, manualSync: data.sync };
    }
    await wbLoadSupplySettings(wbState.selectedSupply, { silent: true });
    wbState.supplySettingsNotice = data?.started === false
      ? 'Синхронизация уже выполняется.'
      : 'Синхронизация запущена в фоне. Можно обновить страницу или перейти в другой маркетплейс.';
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbState.supplySettingsError = err?.message || 'Ошибка';
  } finally {
    wbState.settingsBusy = false;
    render();
  }
}
async function wbHandleFullSyncSupply() {
  if (!wbState.selectedSupply) return;
  if (wbState.supplySettings?.canFullSync !== true) {
    wbState.supplySettingsError = wbState.supplySettings?.fullSyncBlockedReason || 'Полная синхронизация для этой поставки уже заблокирована.';
    render();
    return;
  }
  const confirmed = window.confirm('Полная синхронизация добавит в эту поставку все заказы, которые сейчас есть в поставке WB. Делайте это только пока поставка скрыта и сборка не начата.');
  if (!confirmed) return;
  const API_BASE = getApiBase();
  wbState.settingsBusy = true; wbState.supplySettingsNotice = ''; wbState.supplySettingsError = ''; render();
  try {
    const data = await wbAdminFetch(`${API_BASE}/supplies/${encodeURIComponent(wbState.selectedSupply.id)}/sync-full-apply`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ supplyName: wbState.selectedSupply?.name || null }),
    });
    await Promise.all([
      wbLoadSupplySettings(wbState.selectedSupply, { silent: true }),
      wbLoadSupplyOrders(wbState.selectedSupply, { silent: true }),
      wbLoadAdminData(),
    ]);
    wbState.supplySettingsNotice = `Полная синхронизация: ${Number(data?.afterCount ?? data?.wbCount ?? 0)} заказов, +${Number(data?.addedCount || 0)} / −${Number(data?.removedCount || 0)}.`;
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbState.supplySettingsError = err?.message || 'Ошибка полной синхронизации';
  } finally {
    wbState.settingsBusy = false;
    render();
  }
}
