function wbRenderFbsStock() {
  const storeColumns = wbState.storeOptions.slice(0, 2);
  const progress = wbState.fbsStockProgress || { done: 0, total: 0, percent: 0, message: '', current: null };
  const currentWbBarcode = formatWbBarcodeValue(progress.current);
  return `<div class="card">
    <div class="actions-bar"><div class="actions-bar-left">
      <button class="btn btn-primary btn-sm" id="btn-fbs-refresh" ${wbState.fbsStockLoading || wbState.fbsStockRefreshing ? 'disabled' : ''}>${wbState.fbsStockRefreshing ? 'ОБНОВЛЯЕМ...' : 'ОБНОВИТЬ'}</button>
      <span class="hint">Склад: <strong>${esc(wbState.fbsStockWarehouseName)}</strong>${wbState.fbsStockUpdatedAt ? ` • ${esc(wbState.fbsStockUpdatedAt.toLocaleTimeString('ru-RU'))}` : ''}${wbState.fbsStockRefreshing ? ' • идет обновление' : ''}</span>
    </div><div class="actions-bar-right">
      <span class="pill">Всего: ${wbState.fbsStockTotals.all}</span><span class="pill">ОК: ${wbState.fbsStockTotals.ok}</span><span class="pill">Дефицит: ${wbState.fbsStockTotals.shortage}</span><span class="pill">Ошибки: ${wbState.fbsStockTotals.errors}</span>
    </div></div>
    ${wbState.fbsStockRefreshing ? `<div class="card" style="margin:12px 0 0 0">
      <div class="section-header"><div class="section-title">${esc(progress.message || 'Обновляем проверку остатков...')}</div><div class="section-subtitle">${formatNumber(progress.done || 0)}${progress.total > 0 ? ` / ${formatNumber(progress.total)}` : ''} • ${Math.round(Number(progress.percent || 0))}%</div></div>
      <div class="progress-bar"><div class="progress-bar-fill" style="width:${Math.max(0, Math.min(100, Number(progress.percent || 0)))}%"></div></div>
      <div class="hint" style="padding:12px 14px 0 14px">${currentWbBarcode !== '\u2014' ? `Сейчас: ${esc(progress.current?.productName || '—')} • Баркод WB: ${esc(currentWbBarcode)} • нужно ${formatNumber(progress.current?.requiredQty || 0)}` : 'Подготавливаем данные...'}</div>
    </div>` : ''}
    ${wbState.fbsStockError ? `<div class="alert alert-error">${esc(wbState.fbsStockError)}</div>` : ''}
    <table class="tbl fbs-stock-table"><thead><tr><th>Название</th><th>Баркод WB</th><th>Артикул</th><th class="r">${esc(storeColumns[0]?.name || 'Магазин 1')}</th><th class="r">${esc(storeColumns[1]?.name || 'Магазин 2')}</th><th class="r">Нужно</th><th class="r">Остаток</th><th>Ячейка</th><th>Статус</th></tr></thead>
    <tbody>${(wbState.fbsStockLoading || (wbState.fbsStockRefreshing && wbState.fbsStockItems.length === 0)) ? '<tr><td colspan="9" class="tbl-empty">Загрузка проверки остатков...</td></tr>' : wbState.fbsStockItems.length === 0 ? '<tr><td colspan="9" class="tbl-empty">Нет данных для проверки</td></tr>' : wbState.fbsStockItems.map(item => `<tr class="${item.msStatus === 'insufficient' ? 'fbs-row-shortage' : item.msStatus !== 'ok' ? 'fbs-row-error' : ''}">
      <td><div class="cell-primary">${esc(item.productName || '—')}</div><div class="cell-muted">WB: ${esc(formatFbsValueList(item.nmIds?.length ? item.nmIds : item.nmId))}</div></td>
      <td class="cell-mono">${esc(formatWbBarcodeValue(item))}</td>
      <td class="cell-mono">${esc(formatFbsValueList(item.articles?.length ? item.articles : item.article))}</td>
      <td class="r">${formatNumber(storeColumns[0] ? item.byStore?.[storeColumns[0].id] || 0 : 0)}</td>
      <td class="r">${formatNumber(storeColumns[1] ? item.byStore?.[storeColumns[1].id] || 0 : 0)}</td>
      <td class="r">${formatNumber(item.requiredQty || 0)}</td>
      <td class="r">${item.msStockQty == null ? '—' : formatNumber(item.msStockQty || 0)}</td>
      <td class="cell-mono">${esc(formatFbsCells(item.msCells))}</td>
      <td>${item.msStatus === 'ok' ? '<span class="pill">OK</span>' : item.msStatus === 'insufficient' ? `<span class="stock-qty danger">Нехватка: ${formatNumber(item.requiredQty || 0)} / ${formatNumber(item.msStockQty || 0)}</span>` : `<span class="stock-qty warning">${esc(item.msError || 'Ошибка проверки')}</span>`}${Array.isArray(item.msMatches) && item.msMatches.length > 1 ? `<div class="cell-muted">${esc(item.msMatches.map(match => [match.article, match.name].filter(Boolean).join(' • ')).filter(Boolean).join(' | '))}</div>` : ''}</td>
    </tr>`).join('')}</tbody></table>
  </div>`;
}

