let lastRenderViewKey = '';

function getRenderViewKey() {
  if (!shared.authChecked) return 'auth:checking';
  if (!shared.currentUser) return 'auth:login';
  if (!shared.marketplace) return 'selector';
  const tab = shared.marketplace === 'oz' ? ozState.tab : shared.marketplace === 'wb' ? wbState.tab : ymState.tab;
  return `${shared.currentUser.role}:${shared.marketplace}:${tab}`;
}

function captureRenderUiState() {
  const collectScroll = (selector) => Array.from(document.querySelectorAll(selector)).map((el) => ({
    top: el.scrollTop,
    left: el.scrollLeft,
  }));
  const active = document.activeElement;
  const focusState = active && active.id && ['INPUT', 'TEXTAREA', 'SELECT'].includes(active.tagName)
    ? {
        id: active.id,
        start: typeof active.selectionStart === 'number' ? active.selectionStart : null,
        end: typeof active.selectionEnd === 'number' ? active.selectionEnd : null,
      }
    : null;
  return {
    windowX: window.scrollX,
    windowY: window.scrollY,
    focusState,
    mainContentScroll: collectScroll('.main-content'),
    modalBodyScroll: collectScroll('.modal-body'),
  };
}

function restoreRenderUiState(snapshot) {
  if (!snapshot) return;
  requestAnimationFrame(() => {
    const restoreScroll = (selector, entries) => {
      Array.from(document.querySelectorAll(selector)).forEach((el, index) => {
        const entry = entries[index];
        if (!entry) return;
        el.scrollTop = entry.top;
        el.scrollLeft = entry.left;
      });
    };

    window.scrollTo(snapshot.windowX, snapshot.windowY);
    restoreScroll('.main-content', snapshot.mainContentScroll || []);
    restoreScroll('.modal-body', snapshot.modalBodyScroll || []);

    if (snapshot.focusState?.id) {
      const next = document.getElementById(snapshot.focusState.id);
      if (next && typeof next.focus === 'function') {
        next.focus({ preventScroll: true });
        if (typeof snapshot.focusState.start === 'number' && typeof next.setSelectionRange === 'function') {
          next.setSelectionRange(snapshot.focusState.start, snapshot.focusState.end ?? snapshot.focusState.start);
        }
      }
    }
  });
}

function closeOzCreateUserModal() {
  ozState.createUserOpen = false;
  ozState.createExternalUserId = '';
  ozState.userActionError = '';
}

function closeWbCreateUserModal() {
  wbState.createUserOpen = false;
  wbState.createExternalUserId = '';
  wbState.userActionError = '';
}

async function ozHandleCreateUser() {
  const externalUserId = Number(ozState.createExternalUserId);
  ozState.userActionError = '';
  if (!Number.isFinite(externalUserId) || externalUserId < 1) {
    ozState.userActionError = 'Выберите сотрудника из общей базы.';
    render();
    return;
  }
  ozState.userBusy = true;
  render();
  try {
    await fetchJson(`${getApiBase()}/users`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ externalUserId, role: 'employee' }),
    });
    closeOzCreateUserModal();
    showToast('Сотрудник добавлен.');
    await Promise.all([ozLoadUsers(), ozLoadUserDirectory()]);
  } catch (err) {
    if (ozHandleAuthError(err)) return;
    ozState.userActionError = err?.message || 'Не удалось создать пользователя.';
  } finally {
    ozState.userBusy = false;
    render();
  }
}

