async function ozHandleEmployeeTableConfirm() {
  const assembly = ozState.employeeSelectedAssembly;
  const tableNo = getEmployeeWorkflowTableNo(ozState.employeeAssemblySession?.workflow, ozState.employeeAssemblySession?.session);
  if (!assembly?.id || ozState.employeePickFinishBusy) return;
  const API_BASE = getApiBase();
  ozState.employeePickFinishBusy = true;
  ozState.employeePickFinishError = '';
  render();
  try {
    await fetchJson(`${API_BASE}/employee/assemblies/${encodeURIComponent(assembly.id)}/table-confirm`, {
      method: 'POST',
    });
    ozSuppressLiveRefresh();
    await ozLoadEmployeeAssemblies({ silent: true });
    ozEmployeeCloseAssembly();
    showToast(tableNo ? `Товар передан на стол ${tableNo}.` : 'Товар передан упаковщику.');
  } catch (err) {
    if (ozHandleAuthError(err)) return;
    ozState.employeePickFinishError = err?.message || 'Не удалось подтвердить стол.';
  } finally {
    ozState.employeePickFinishBusy = false;
    render();
  }
}

