  const supply = wbState.employeeSelectedSupply;
  const tableNo = getEmployeeWorkflowTableNo(wbState.employeeSupplySession?.workflow, wbState.employeeSupplySession?.session);
  if (!supply?.id || wbState.employeePickFinishBusy) return;
