function wbRender() {
  const app = document.getElementById('app');
  if (!app) return;
  const user = shared.currentUser;
  if (!user) return;
  const isSuper = user.role === 'super_admin';
  const isAdmin = user.role === 'admin';
  const isEmployee = user.role === 'employee';
  const topbar = wbRenderTopbar();

  if (isSuper) {
    app.innerHTML = topbar + '<div class="main-content">' + wbRenderSuperAdmin() + '</div>' + wbRenderStatusbar();
    wbBindSuperAdmin();
    return;
  }
  if (isAdmin) {
    let adminModals = '';
    if (wbState.createOpen) adminModals += wbRenderCreateSupplyModal();
    if (wbState.excludePicker && wbState.excludePicker.open) adminModals += wbRenderExcludePicker();
    if (wbState.createUserOpen) adminModals += renderCreateUserModalClassic(wbState);
    if (wbState.selectedSupply) adminModals += wbRenderSupplyModal();
    if (wbState.employeeStatsUser) adminModals += renderEmployeeStatsModalClassic(wbState);
    if (wbState.historyOpen) adminModals += wbRenderHistoryModal();
    app.innerHTML = topbar + wbRenderAdminTabs() + '<div class="main-content">' + wbRenderAdminContent() + '</div>' + wbRenderStatusbar() + adminModals;
    wbBindAdmin();
    wbBindSupplyExtras();
    return;
  }
  if (isEmployee) {
    app.innerHTML = topbar + '<div class="main-content">' + wbRenderEmployee() + '</div>' + wbRenderStatusbar() + wbRenderEmployeeModals();
    wbBindEmployee();
  }
}

async function wbHandleAutoFixScanIssue(id) {
  if (!id || wbState.scanIssueActionBusyId) return;
  const issue = wbState.scanIssues.find((item) => Number(item.id) === Number(id));
  if (!issue || !window.confirm(`Добавить штрихкод ${issue.confirmationScannedBarcode || issue.scannedBarcode || ''} в складскую карточку ${issue.warehouseArticle || issue.marketplaceArticle || ''}?`)) return;
  wbState.scanIssueActionBusyId = id; render();
  try { await wbAdminFetch(`${getApiBase()}/settings/scan-issues/${id}/auto-fix`, { method: 'POST' }); wbState.scanIssues = wbState.scanIssues.filter(i => i.id !== id); }
  catch (err) { if (wbHandleAuthError(err)) return; wbState.scanIssuesError = err?.message || 'Не удалось добавить штрихкод.'; }
  finally { wbState.scanIssueActionBusyId = null; render(); }
}

async function wbLoadEmployeePickIssues() {
  const supply = wbState.employeeSelectedSupply;
  if (!supply?.id || wbState.employeePickIssuesLoading) return;
  wbState.employeePickIssuesLoading = true;
  wbState.employeePickIssuesError = '';
  render();
  try {
    const data = await fetchJson(`${getApiBase()}/employee/supplies/${encodeURIComponent(supply.id)}/pick-issues`);
    wbState.employeePickIssues = Array.isArray(data?.issues) ? data.issues : [];
  } catch (err) {
    if (wbHandleAuthError(err)) return;
    wbState.employeePickIssuesError = err?.message || 'Не удалось загрузить статусы.';
  } finally {
    wbState.employeePickIssuesLoading = false;
    render();
  }
}

// ================================================================
// SECTION 6C: YANDEX MARKET · FBS
// ================================================================

function ymResetTransient() {
  ymState.error = '';
  ymState.employeeError = '';
  ymState.employeeScanError = '';
}

function ymImageUrl(value) {
  const url = String(value || '').trim();
  return url ? `${YM_API}/images/product?url=${encodeURIComponent(url)}` : '';
}

function ymCleanup() {
  ymResetTransient();
  document.onkeydown = null;
}

function ymPendingWriteStorageKey() {
  return `ym-pending-write-v1:${shared.currentUser?.id || 'anonymous'}`;
}

function ymCreateRequestId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(bytes);
  else for (let index = 0; index < bytes.length; index += 1) bytes[index] = Math.floor(Math.random() * 256);
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = [...bytes].map((value) => value.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function ymReadPendingWrite() {
  try {
    const value = JSON.parse(localStorage.getItem(ymPendingWriteStorageKey()) || 'null');
    return value?.url && value?.body?.requestId ? value : null;
  } catch {
    return null;
  }
}

function ymStorePendingWrite(value) {
  try {
    if (value) localStorage.setItem(ymPendingWriteStorageKey(), JSON.stringify(value));
    else localStorage.removeItem(ymPendingWriteStorageKey());
  } catch {}
}

async function ymSendPendingWrite(pending) {
  let lastError = null;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    try {
      return await fetchJson(pending.url, {
        method: 'POST',
        timeoutMs: 30000,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(pending.body),
      });
    } catch (error) {
      lastError = error;
      if (!isTransientWriteTimeout(error) || attempt === 3) throw error;
      await wait(500 * (attempt + 1));
    }
  }
  throw lastError || new Error('Не удалось подтвердить сканирование');
}

async function ymIdempotentScan(url, body) {
  const signature = JSON.stringify([url, String(body?.barcode || '')]);
  const unresolved = ymReadPendingWrite();
  if (unresolved) {
    const recovered = await ymSendPendingWrite(unresolved);
    ymStorePendingWrite(null);
    if (unresolved.signature === signature) return recovered;
  }
  const pending = { url, signature, body: { ...body, requestId: ymCreateRequestId() }, createdAt: new Date().toISOString() };
  ymStorePendingWrite(pending);
  try {
    const result = await ymSendPendingWrite(pending);
    ymStorePendingWrite(null);
    return result;
  } catch (error) {
    if (!isTransientWriteTimeout(error)) ymStorePendingWrite(null);
    throw error;
  }
}

async function ymInit() {
  if (isAdminUser()) {
    await ymLoadDashboard();
    if (!ymState.waitingLoaded || ymState.dashboard?.waitingStatus?.loading) ymLoadWaiting();
  }
  else if (isEmployeeUser()) await ymLoadEmployeeAssemblies();
}

async function ymLoadDashboard({ silent = false } = {}) {
  if (ymState.loading) return;
  ymState.loading = true;
  if (!silent) ymState.error = '';
  render();
  try {
    ymState.dashboard = await fetchJson(`${YM_API}/dashboard`, { timeoutMs: 60000, retryCount: 1 });
    ymState.waitingLoaded = Boolean(ymState.dashboard?.waitingStatus?.cachedAt);
    ymState.waitingError = ymState.dashboard?.waitingStatus?.error || '';
    const available = new Set((ymState.dashboard?.waiting || []).map((order) => String(order.id)));
    ymState.selectedOrderIds = new Set([...ymState.selectedOrderIds].filter((id) => available.has(String(id))));
  } catch (error) {
    ymState.error = error?.message || 'Не удалось загрузить Яндекс Маркет';
  } finally {
    ymState.loading = false;
    render();
  }
}

async function ymLoadWaiting({ force = false } = {}) {
  if (ymState.waitingLoading) return;
  ymState.waitingLoading = true;
  ymState.waitingError = '';
  render();
  try {
    const data = await fetchJson(`${YM_API}/waiting${force ? '?force=1' : ''}`, { timeoutMs: 90000, retryCount: 1 });
    if (!ymState.dashboard) ymState.dashboard = { waiting: [], assemblies: [], employees: [] };
    ymState.dashboard.waiting = data?.orders || [];
    ymState.dashboard.waitingStatus = { cachedAt: data?.cachedAt || null, loading: false, error: data?.error || '' };
    ymState.waitingLoaded = true;
    const available = new Set(ymState.dashboard.waiting.map((order) => String(order.id)));
    ymState.selectedOrderIds = new Set([...ymState.selectedOrderIds].filter((id) => available.has(String(id))));
  } catch (error) {
    ymState.waitingError = error?.message || 'Не удалось загрузить новые заказы Яндекса';
  } finally {
    ymState.waitingLoading = false;
    render();
  }
}

async function ymRefreshAdmin() {
  await ymLoadDashboard({ silent: true });
  await ymLoadWaiting({ force: true });
}

async function ymSyncAll() {
  if (ymState.syncBusy) return;
  ymState.syncBusy = true;
  ymState.error = '';
  render();
  try {
    const result = await fetchJson(`${YM_API}/sync`, { method: 'POST', timeoutMs: 90000 });
    showToast(`Сверено заказов: ${result.checked || 0}. Проблем: ${result.problems || 0}.`, result.problems ? 'warning' : 'success');
    await ymLoadDashboard({ silent: true });
    await ymLoadWaiting({ force: true });
    if (ymState.selectedAssemblyId) await ymLoadAssembly(ymState.selectedAssemblyId);
  } catch (error) {
    ymState.error = error?.message || 'Не удалось синхронизировать Яндекс Маркет';
  } finally {
    ymState.syncBusy = false;
    render();
  }
}

