async function ymResolveExternalOrder(orderId) {
  if (!orderId || !ymState.selectedAssemblyId || ymState.syncBusy) return;
  if (!window.confirm(`Сверить и исправить проблемный заказ #${orderId}? Если заказ уже собран вне приложения или отменён, он будет удалён из внутренней сборки.`)) return;
  ymState.syncBusy = true;
  ymState.error = '';
  render();
  try {
    const result = await fetchJson(`${YM_API}/assemblies/${encodeURIComponent(ymState.selectedAssemblyId)}/orders/${encodeURIComponent(orderId)}/resolve`, {
      method: 'POST', timeoutMs: 90000,
    });
    showToast(result.action === 'removed' ? 'Неактуальный заказ удалён из сборки' : 'Состав заказа обновлён', 'success');
    await ymLoadAssembly(ymState.selectedAssemblyId);
    await ymLoadDashboard({ silent: true });
  } catch (error) {
    ymState.error = error?.message || 'Не удалось исправить заказ';
  } finally {
    ymState.syncBusy = false;
    render();
  }
}

async function ymLoadAssembly(id) {
  if (!id || ymState.assemblyLoading) return;
  const changedAssembly = String(id) !== String(ymState.selectedAssemblyId);
  ymState.selectedAssemblyId = String(id);
  if (changedAssembly) {
    ymState.assemblyTab = 'settings';
    ymState.assemblyDetail = null;
    ymState.assemblyShipments = [];
    ymState.assemblyShipmentsError = '';
  }
  ymState.assemblyLoading = true;
  ymState.error = '';
  render();
  try {
    ymState.assemblyDetail = await fetchJson(`${YM_API}/assemblies/${encodeURIComponent(id)}`, { timeoutMs: 30000 });
    ymState.assignmentUserIds = new Set((ymState.assemblyDetail?.assignment?.userIds || []).map(String));
  } catch (error) {
    ymState.error = error?.message || 'Не удалось открыть сборку';
    ymState.selectedAssemblyId = '';
    ymState.assemblyDetail = null;
  } finally {
    ymState.assemblyLoading = false;
    render();
  }
}

async function ymLoadAssemblyShipments({ silent = false } = {}) {
  if (!ymState.selectedAssemblyId || ymState.assemblyShipmentsLoading) return;
  ymState.assemblyShipmentsLoading = true;
  if (!silent) ymState.assemblyShipmentsError = '';
  render();
  try {
    const data = await fetchJson(`${YM_API}/assemblies/${encodeURIComponent(ymState.selectedAssemblyId)}/shipments`, { timeoutMs: 60000, retryCount: 1 });
    ymState.assemblyShipments = data?.shipments || [];
    for (const shipment of ymState.assemblyShipments) {
      if (ymState.shipmentPlaceDrafts[shipment.id] == null) {
        ymState.shipmentPlaceDrafts[shipment.id] = String(Number(shipment.plannedPlaces || shipment.palletsCount?.planned || 0) || 1);
      }
    }
  } catch (error) {
    ymState.assemblyShipmentsError = error?.message || 'Не удалось загрузить отгрузки сборки';
  } finally {
    ymState.assemblyShipmentsLoading = false;
    render();
  }
}

