async function ymSetShipmentPlaces(shipmentId) {
  const placesCount = Number(ymState.shipmentPlaceDrafts[shipmentId]);
  if (!Number.isInteger(placesCount) || placesCount < 1 || placesCount > 200) {
    showToast('Укажите количество транспортных упаковок от 1 до 200', 'error');
    return;
  }
  ymState.shipmentsLoading = true;
  ymState.shipmentsError = '';
  render();
  try {
    await fetchJson(`${YM_API}/shipments/${encodeURIComponent(shipmentId)}/places`, {
      method: 'POST', timeoutMs: 60000,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ placesCount }),
    });
    showToast('Количество упаковок сохранено. Теперь скачайте ярлыки.', 'success');
    ymState.shipmentsLoading = false;
    await ymLoadShipments({ silent: true });
    if (ymState.selectedAssemblyId) await ymLoadAssemblyShipments({ silent: true });
  } catch (error) {
    ymState.shipmentsError = error?.message || 'Не удалось сохранить количество упаковок';
  } finally {
    ymState.shipmentsLoading = false;
    render();
  }
}

async function ymCreateAssembly() {
  if (ymState.createBusy) return;
  const selectedOrders = ymSelectedOrders();
  if (!selectedOrders.length) return;
  const fallbackCampaignId = Number(ymState.dashboard?.shop?.campaignId || 0);
  const groups = new Map();
  for (const order of selectedOrders) {
    const campaignId = Number(order.campaignId || fallbackCampaignId);
    if (!groups.has(campaignId)) groups.set(campaignId, []);
    groups.get(campaignId).push(Number(order.id));
  }
  ymState.createBusy = true;
  ymState.error = '';
  render();
  try {
    const created = [];
    for (const [campaignId, orderIds] of groups) {
      const baseName = ymState.createName.trim();
      const name = groups.size > 1 && baseName ? `${baseName} · ${ymCampaignName(campaignId)}` : baseName;
      created.push(await fetchJson(`${YM_API}/assemblies`, {
        method: 'POST',
        timeoutMs: 90000,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ orderIds, name, allowZeroStock: ymState.createAllowZeroStock, allowNoScan: ymState.createAllowNoScan, draft: true }),
      }));
    }
    ymState.createOpen = false;
    ymState.createName = '';
    ymState.createUserIds.clear();
    ymState.createAllowZeroStock = false;
    ymState.createAllowNoScan = true;
    ymState.selectedOrderIds.clear();
    showToast(created.length === 1
      ? `Сборка «${created[0].name || 'Яндекс'}» создана. Настройте сотрудников и запустите её.`
      : `Создано сборок по магазинам: ${created.length}. Настройте сотрудников и запустите их.`, 'success');
    await ymLoadDashboard({ silent: true });
    ymState.tab = 'assemblies';
    navigate('ym', 'assemblies');
    ymLoadWaiting({ force: true });
    if (created.length === 1) await ymLoadAssembly(created[0].id);
  } catch (error) {
    ymState.error = error?.message || 'Не удалось создать сборку';
  } finally {
    ymState.createBusy = false;
    render();
  }
}

async function ymConfirmShipment(shipmentId) {
  const shipment = [...ymState.shipments, ...ymState.assemblyShipments].find((entry) => String(entry.id) === String(shipmentId));
  if (!shipment) return;
  if ((shipment.availableActions || []).includes('CHANGE_PALLETS_COUNT') && !shipment.packageLabelsSaved) {
    showToast('Сначала сохраните количество упаковок и откройте PDF ярлыков', 'error');
    return;
  }
  const warning = `ВНИМАНИЕ: после подтверждения отгрузки #${shipmentId} изменить заказы, число коробов и получить новый ярлык будет нельзя. Заказов: ${(shipment.orderIds || []).length}. Упаковок: ${Number(shipment.plannedPlaces || 0)}.`;
  if (!window.confirm(warning)) return;
  if (!window.confirm('Ярлыки уже распечатаны и наклеены. Необратимо подтвердить отгрузку?')) return;
  ymState.shipmentsLoading = true;
  render();
  try {
    await fetchJson(`${YM_API}/shipments/${encodeURIComponent(shipmentId)}/confirm`, {
      method: 'POST',
      timeoutMs: 90000,
    });
    showToast('Отгрузка подтверждена', 'success');
    ymState.shipmentsLoading = false;
    await ymLoadShipments({ silent: true });
    if (ymState.selectedAssemblyId) await ymLoadAssemblyShipments({ silent: true });
  } catch (error) {
    ymState.shipmentsError = error?.message || 'Не удалось подтвердить отгрузку';
  } finally {
    ymState.shipmentsLoading = false;
    render();
  }
}

