async function ymEmployeePickScan(value) {
  const barcode = String(value || '').trim();
  if (!barcode || ymState.employeeScanBusy) return;
  ymState.employeeScanBusy = true;
  ymState.employeeScanError = '';
  try {
    await ymIdempotentScan(`${YM_API}/employee/assemblies/${encodeURIComponent(ymState.employeeAssemblyId)}/pick-scan`, { barcode });
    playTone('success');
    await ymRefreshEmployeeDetail();
  } catch (error) {
    playTone('error');
    ymState.employeeScanError = isTransientWriteTimeout(error)
      ? 'Связь оборвалась после скана. Повторите этот же штрихкод: система проверит прежнюю операцию и не засчитает товар дважды.'
      : (error?.message || 'Штрихкод не принят');
  } finally {
    ymState.employeeScanBusy = false;
    render();
  }
}

