  $$('[data-ym-assignment-user]').forEach((input) => input.onchange = () => {
    if (input.checked) ymState.assignmentUserIds.add(String(input.dataset.ymAssignmentUser));
    else ymState.assignmentUserIds.delete(String(input.dataset.ymAssignmentUser));
    render();
  });
