  const syncAssembly = $('#btn-ym-sync-assembly'); if (syncAssembly) syncAssembly.onclick = () => ymSyncAssembly(ymState.selectedAssemblyId);
  const ordersSync = $('#btn-ym-orders-sync'); if (ordersSync) ordersSync.onclick = () => ymSyncAssembly(ymState.selectedAssemblyId);
  const pickList = $('#btn-ym-pick-list'); if (pickList) pickList.onclick = () => window.open(`${YM_API}/assemblies/${encodeURIComponent(ymState.selectedAssemblyId)}/documents/pick-list`, '_blank', 'noopener');
