  const refreshAssemblyShipments = $('#btn-ym-refresh-assembly-shipments'); if (refreshAssemblyShipments) refreshAssemblyShipments.onclick = () => ymLoadAssemblyShipments();
  const refreshShipments = $('#btn-ym-refresh-shipments'); if (refreshShipments) refreshShipments.onclick = () => ymLoadShipments();
  $$('[data-ym-place-input]').forEach((input) => input.oninput = () => { ymState.shipmentPlaceDrafts[input.dataset.ymPlaceInput] = input.value; });
  $$('[data-ym-save-places]').forEach((button) => button.onclick = () => ymSetShipmentPlaces(button.dataset.ymSavePlaces));
  $$('[data-ym-confirm-shipment]').forEach((button) => button.onclick = () => ymConfirmShipment(button.dataset.ymConfirmShipment));
