  $$('[data-ym-employee-assembly]').forEach((button) => button.onclick = () => ymOpenEmployeeAssembly(button.dataset.ymEmployeeAssembly));
  const employeeBack = $('#btn-ym-employee-back'); if (employeeBack) employeeBack.onclick = () => { ymState.employeeAssemblyId = ''; ymState.employeeDetail = null; ymState.employeeSelectedOrderId = ''; ymState.employeeShipments = []; ymLoadEmployeeAssemblies(); };
  const finishPicking = $('#btn-ym-finish-picking'); if (finishPicking) finishPicking.onclick = ymEmployeeFinishPicking;
