  $$('[data-ym-employee-act]').forEach((button) => button.onclick = () => window.open(`${YM_API}/employee/assemblies/${encodeURIComponent(ymState.employeeAssemblyId)}/shipments/${encodeURIComponent(button.dataset.ymEmployeeAct)}/act`, '_blank', 'noopener'));
  ymBindScanInput('#ym-pick-scan', ymEmployeePickScan);
