// ================================================================
// Красивые выпадающие списки поверх нативных <select>.
// Нативный select остаётся в DOM (value + change работают как раньше),
// поверх рисуется bembox-дропдаун; на телефонах — шторка снизу.
// ================================================================
let ddOpenMenu = null;

function ddClose() {
  if (!ddOpenMenu) return;
  ddOpenMenu.menu.remove();
  if (ddOpenMenu.backdrop) ddOpenMenu.backdrop.remove();
  if (ddOpenMenu.trigger) ddOpenMenu.trigger.classList.remove('is-open');
  ddOpenMenu = null;
}

function ddOpen(select, trigger) {
  ddClose();
  const options = [...select.options].filter((o) => !o.hidden);
  const isMobile = window.innerWidth <= 768;
  const menu = document.createElement('div');
  menu.className = `dd-menu${isMobile ? ' dd-sheet' : ''}`;

  let backdrop = null;
  if (isMobile) {
    backdrop = document.createElement('div');
    backdrop.className = 'dd-backdrop';
    backdrop.onclick = ddClose;
    document.body.appendChild(backdrop);
    const label = select.closest('.field')?.querySelector('span')?.textContent
      || select.closest('.store-select')?.querySelector('span')?.textContent
      || '';
    if (label) {
      const head = document.createElement('div');
      head.className = 'dd-sheet-head';
      head.textContent = label.replace(/:\s*$/, '');
      menu.appendChild(head);
    }
  }

  const list = document.createElement('div');
  list.className = 'dd-list';

  const renderItems = (filter) => {
    const q = String(filter || '').trim().toLowerCase();
    list.innerHTML = '';
    let shown = 0;
    options.forEach((opt) => {
      if (q && !opt.text.toLowerCase().includes(q)) return;
      shown += 1;
      const item = document.createElement('button');
      item.type = 'button';
      item.className = `dd-item${opt.value === select.value ? ' is-selected' : ''}${opt.disabled ? ' is-disabled' : ''}`;
      item.innerHTML = `<span class="dd-item-text"></span><span class="dd-item-check">${opt.value === select.value ? '&#10003;' : ''}</span>`;
      item.querySelector('.dd-item-text').textContent = opt.text;
      if (!opt.disabled) {
        item.onclick = () => {
          const changed = select.value !== opt.value;
          select.value = opt.value;
          if (trigger) trigger.querySelector('.dd-trigger-text').textContent = opt.text;
          ddClose();
          if (changed) select.dispatchEvent(new Event('change', { bubbles: true }));
        };
      }
      list.appendChild(item);
    });
    if (!shown) list.innerHTML = '<div class="dd-empty">Ничего не найдено</div>';
  };

  if (options.length > 8) {
    const search = document.createElement('input');
    search.className = 'dd-search';
    search.placeholder = 'Поиск...';
    search.oninput = () => renderItems(search.value);
    menu.appendChild(search);
  }
  renderItems('');
  menu.appendChild(list);
  document.body.appendChild(menu);

  if (!isMobile) {
    const r = trigger.getBoundingClientRect();
    const menuH = Math.min(menu.offsetHeight, 320);
    const below = window.innerHeight - r.bottom;
    menu.style.left = `${Math.max(8, Math.min(r.left, window.innerWidth - menu.offsetWidth - 8))}px`;
    menu.style.minWidth = `${r.width}px`;
    if (below < menuH + 12 && r.top > menuH + 12) {
      menu.style.top = `${r.top - menuH - 6}px`;
    } else {
      menu.style.top = `${r.bottom + 6}px`;
    }
  }
  trigger.classList.add('is-open');
  ddOpenMenu = { menu, backdrop, trigger, select };
  const selected = list.querySelector('.dd-item.is-selected');
  if (selected) selected.scrollIntoView({ block: 'nearest' });
}

document.addEventListener('pointerdown', (e) => {
  if (!ddOpenMenu) return;
  if (ddOpenMenu.menu.contains(e.target) || ddOpenMenu.trigger?.contains(e.target)) return;
  ddClose();
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') ddClose(); });
window.addEventListener('resize', ddClose);

function enhanceAllSelects() {
  ddClose();
  document.querySelectorAll('select').forEach((select) => {
    if (select.multiple || select.dataset.native === '1' || select.dataset.ddEnhanced === '1') return;
    select.dataset.ddEnhanced = '1';
    select.classList.add('dd-native-hidden');
    const trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.className = 'dd-trigger input';
    trigger.innerHTML = '<span class="dd-trigger-text"></span><span class="dd-trigger-arrow"></span>';
    trigger.querySelector('.dd-trigger-text').textContent = select.selectedOptions[0]?.text || select.options[0]?.text || '';
    if (select.disabled) trigger.classList.add('is-disabled');
    trigger.onclick = (e) => {
      e.preventDefault();
      if (select.disabled) return;
      if (ddOpenMenu && ddOpenMenu.select === select) { ddClose(); return; }
      ddOpen(select, trigger);
    };
    select.insertAdjacentElement('afterend', trigger);
  });
}

function render() {
  renderCore();
  try { enhanceAllSelects(); } catch (e) { console.error('dd enhance failed', e); }
  try { bindPhotoThumbs(); } catch (e) {}
}

function renderCore() {
  const app = document.getElementById('app');
  if (!app) return;
  const nextViewKey = getRenderViewKey();
  const uiSnapshot = lastRenderViewKey === nextViewKey ? captureRenderUiState() : null;

  if (!shared.authChecked) {
    lastRenderViewKey = nextViewKey;
    app.innerHTML = '<div class="login-screen"><div class="login-card"><div class="hint" style="text-align:center">Проверка авторизации...</div></div></div>';
    return;
  }

  if (!shared.currentUser) {
    lastRenderViewKey = nextViewKey;
    app.innerHTML = renderLoginScreen();
    bindLoginScreen();
    restoreRenderUiState(uiSnapshot);
    return;
  }

  if (shared.marketplace === 'settings') {
    lastRenderViewKey = nextViewKey;
    app.innerHTML = renderGlobalSettingsPage();
    bindGlobalSettingsPage();
    restoreRenderUiState(uiSnapshot);
    syncRouteFromState(true);
    return;
  }

  if (!shared.marketplace) {
    lastRenderViewKey = nextViewKey;
    app.innerHTML = renderMarketplaceSelector();
    bindMarketplaceSelector();
    restoreRenderUiState(uiSnapshot);
    syncRouteFromState(true);
    return;
  }

  if (shared.marketplace === 'oz') {
    lastRenderViewKey = nextViewKey;
    ozRender();
    restoreRenderUiState(uiSnapshot);
    syncRouteFromState(true);
    return;
  }

  if (shared.marketplace === 'wb') {
    lastRenderViewKey = nextViewKey;
    wbRender();
    restoreRenderUiState(uiSnapshot);
    syncRouteFromState(true);
    return;
  }

  if (shared.marketplace === 'ym') {
    lastRenderViewKey = nextViewKey;
    ymRender();
    restoreRenderUiState(uiSnapshot);
    syncRouteFromState(true);
    return;
  }
}


