setInterval(() => {
  const el = document.getElementById('status-clock');
  if (el) el.textContent = new Date().toLocaleTimeString('ru-RU');
}, 1000);


// ================================================================
// SECTION 8: INITIALIZATION
// ================================================================

initAudio();
render();

function applyBootAuth(data) {
  shared.loginError = '';
  shared.currentUser = data?.user || null;
  if (isEmployeeUser(shared.currentUser)) loadEmployeeCoinSummary({ silent: true });
  else resetEmployeeCoinState();
  if (!shared.currentUser) resetEarningsState();
  shared.authChecked = true;
  _loginCompletedAt = Date.now();
  const route = parseRoute();
  const mp = route.marketplace || localStorage.getItem('sborka_marketplace') || '';
  const tab = route.tab || '';
  if (shared.currentUser && mp) {
    applyRoute(mp, tab || 'new', route.marketplace ? route : null);
  } else {
    clearPendingDeepRoute();
    render();
  }
}

// If the first auth check fails (server restart, network blip), don't strand the
// user: show the login screen right away and quietly keep re-checking the session
// in the background — the moment the server is back, the app enters by itself.
function bootAuthRetry(attempt) {
  if (shared.currentUser || attempt >= 40) return;
  setTimeout(() => {
    if (shared.currentUser) return;
    fetchJson(`${AUTH_API}/auth/me`, { timeoutMs: 5000, retryCount: 0 })
      .then((data) => {
        if (shared.currentUser) return;
        if (data?.user) applyBootAuth(data);
        // 200 with no user = real logged-out state: stay on the login screen.
      })
      .catch(() => bootAuthRetry(attempt + 1));
  }, 3000);
}

window.addEventListener('desktop-auth-refresh', () => {
  fetchJson(`${AUTH_API}/auth/me`, { timeoutMs: 5000, retryCount: 0 })
    .then((data) => {
      if (data?.user) {
        applyBootAuth(data);
      } else {
        shared.currentUser = null;
        shared.authChecked = true;
        render();
      }
    })
    .catch(() => {
      shared.authChecked = true;
      shared.loginError = 'Нет связи с сервером — переподключаемся автоматически…';
      render();
      bootAuthRetry(0);
    });
});

// Оболочка (ПК без сканера) просит сразу показать форму входа по логину/паролю.
window.addEventListener('desktop-show-password-login', () => {
  shared.showPasswordLogin = true;
  shared.loginError = '';
  shared._fpNudgeSent = true; // не пинать оболочку обратно на экран отпечатка
  render();
});

fetchJson(`${AUTH_API}/auth/me`, { timeoutMs: 4000, retryCount: 0 })
  .then(applyBootAuth)
  .catch(() => {
    shared.authChecked = true;
    shared.loginError = 'Нет связи с сервером — переподключаемся автоматически…';
    render();
    bootAuthRetry(0);
  });

// ================================================================
// SECTION 9: СТАТУС СЕТИ + ГЛОБАЛЬНЫЕ ХОТКЕИ СОТРУДНИКА — 04.08.2026
// ================================================================
(function setupNetStatusAndHotkeys() {
  const style = document.createElement('style');
  style.textContent = [
    '.net-status{position:fixed;left:12px;bottom:12px;z-index:2147483000;display:flex;align-items:center;gap:7px;padding:6px 10px;border-radius:22px;font:600 12px/1 Onest,system-ui,sans-serif;box-shadow:0 3px 12px rgba(0,0,0,.18);user-select:none;transition:background .2s,color .2s}',
    '.net-status .net-dot{width:9px;height:9px;border-radius:50%;background:currentColor;flex:0 0 auto}',
    '.net-status.net-online{background:#e7f7ec;color:#1a7f37}',
    '.net-status.net-offline{background:#fdeaea;color:#c62828;animation:netpulse 1s infinite}',
    '@keyframes netpulse{0%,100%{opacity:1}50%{opacity:.5}}',
    '.net-status .net-reload{border:none;background:transparent;color:inherit;font-size:16px;cursor:pointer;padding:0 2px;line-height:1;border-radius:6px}',
    '.net-status .net-reload:hover{background:rgba(0,0,0,.1)}',
    '.hotkey-holding{position:relative;overflow:hidden}',
    '.hotkey-holding::after{content:"";position:absolute;left:0;top:0;bottom:0;width:calc(var(--hold,0)*100%);background:rgba(255,255,255,.4);pointer-events:none;transition:width .04s linear;z-index:1}',
    '.btn.is-printing{opacity:.85}',
    '.btn.is-printed{background:#1a7f37 !important;border-color:#1a7f37 !important;color:#fff !important;cursor:default}',
    '.employee-confirm-overlay{z-index:2147482000;display:flex !important;align-items:center !important;justify-content:center !important;padding:16px}',
    '.employee-confirm-overlay .modal-panel{width:min(420px,92vw) !important;max-width:92vw !important;min-width:0 !important;height:auto !important;max-height:82vh !important;margin:auto !important;border-radius:14px !important;overflow:auto}',
    '.confirm-items-list{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}',
    '.confirm-item-row{display:flex;justify-content:space-between;gap:10px;padding:8px 10px;background:#f4f6f9;border-radius:8px;font-size:14px}',
    '.confirm-item-main{display:flex;align-items:center;gap:6px;min-width:0}',
    '.confirm-item-name{font-weight:600}',
    '.confirm-item-badge{display:inline-flex;align-items:center;flex:0 0 auto;border-radius:999px;padding:2px 7px;background:#fff0e8;color:#b84d1a;font-size:11px;font-weight:800;text-transform:uppercase}',
    '.confirm-item-qty{color:#FF7547;font-weight:700;white-space:nowrap}',
    '.confirm-total{font-size:14px;color:#333}',
    '.confirm-warning{margin-bottom:10px}',
    '.collected-orders-list{display:flex;flex-direction:column;gap:6px}',
    '.collected-order-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 10px;background:#f4f6f9;border-radius:8px}',
    '.collected-order-name{font-weight:600;font-size:14px}',
    '.collected-order-id{font-size:12px;color:#888}',
    '.collected-reprint{flex:0 0 auto}',
    '.login-card-fp{text-align:center}',
    '.login-fp-icon{font-size:56px;line-height:1;margin-bottom:8px}',
    '.login-fp-hint{margin-top:10px;color:#888;font-size:13px}',
  ].join('');
  document.head.appendChild(style);

  const bar = document.createElement('div');
  bar.className = 'net-status net-online';
  bar.innerHTML = '<span class="net-dot"></span><span class="net-text">В сети</span><button type="button" class="net-reload" title="Перезагрузить приложение (Ctrl+Shift+R)">&#8635;</button>';
  const mount = () => { const host = document.fullscreenElement || document.body; if (host && !host.contains(bar)) host.appendChild(bar); };
  if (document.body) mount(); else document.addEventListener('DOMContentLoaded', mount);
  document.addEventListener('fullscreenchange', mount);
  document.addEventListener('webkitfullscreenchange', mount);
  const setNet = (ok) => {
    bar.classList.toggle('net-online', ok);
    bar.classList.toggle('net-offline', !ok);
    const t = bar.querySelector('.net-text'); if (t) t.textContent = ok ? 'В сети' : 'Нет сети';
  };
  const doReload = () => { try { location.reload(); } catch (_e) {} };
  bar.querySelector('.net-reload').onclick = doReload;
  setNet(navigator.onLine !== false);
  window.addEventListener('online', () => setNet(true));
  window.addEventListener('offline', () => setNet(false));
  async function pingServer() {
    try {
      const ctrl = new AbortController();
      const to = setTimeout(() => ctrl.abort(), 6000);
      const r = await fetch('/sborka/health', { cache: 'no-store', signal: ctrl.signal });
      clearTimeout(to); setNet(!!(r && r.ok));
    } catch (_e) { setNet(false); }
  }
  pingServer();
  setInterval(pingServer, 12000);

  // Перезагрузка: Ctrl+Shift+R (Win+R зарезервирован Windows) либо Shift+Meta+R
  window.addEventListener('keydown', (e) => {
    const rKey = e.code === 'KeyR' || e.key === 'r' || e.key === 'R' || e.key === 'к' || e.key === 'К';
    if (rKey && e.shiftKey && (e.ctrlKey || e.metaKey)) { e.preventDefault(); doReload(); }
  }, true);

  // Хоткеи сотрудника: Alt(слева)=печать этикетки, Пробел(удержать 3с)=завершить заказ
  const inField = () => {
    const el = document.activeElement; if (!el) return false;
    const tag = (el.tagName || '').toLowerCase();
    return tag === 'input' || tag === 'textarea' || tag === 'select' || el.isContentEditable;
  };
  const orderOpen = () => shared.marketplace === 'oz' ? !!ozState.employeeSelectedOrder
    : shared.marketplace === 'wb' ? !!wbState.employeeSelectedOrder
    : shared.marketplace === 'ym' ? !!ymState.employeeSelectedOrderId : false;
  const printBtn = () => document.getElementById(shared.marketplace === 'oz' ? 'btn-oz-employee-open-label' : shared.marketplace === 'ym' ? 'btn-ym-print-label' : 'btn-employee-open-label');
  const completeBtn = () => shared.marketplace === 'oz'
    ? (document.getElementById('btn-oz-employee-complete-confirm') || document.getElementById('btn-oz-employee-complete-noscan'))
    : shared.marketplace === 'ym' ? document.getElementById('btn-ym-complete-order')
    : (document.getElementById('btn-wb-employee-complete-confirm') || document.getElementById('btn-employee-complete-noscan'));
  const HOLD_MS = 1300;
  let holdTimer = null, holdBtn = null, holdStart = 0;
  const cancelHold = () => {
    if (holdTimer) { clearInterval(holdTimer); holdTimer = null; }
    if (holdBtn) { holdBtn.style.removeProperty('--hold'); holdBtn.classList.remove('hotkey-holding'); holdBtn = null; }
  };
  window.addEventListener('keydown', (e) => {
    if (!orderOpen() || inField()) return;
    if (e.code === 'AltLeft' && !e.repeat) { e.preventDefault(); const b = printBtn(); if (b && !b.disabled) b.click(); return; }
    if (e.code === 'Space') {
      e.preventDefault();
      if (holdTimer) return;
      const b = completeBtn(); if (!b || b.disabled) return;
      holdBtn = b; holdStart = Date.now(); b.classList.add('hotkey-holding');
      holdTimer = setInterval(() => {
        const pct = Math.min(1, (Date.now() - holdStart) / HOLD_MS);
        if (holdBtn) holdBtn.style.setProperty('--hold', String(pct));
        if (pct >= 1) {
          const target = holdBtn; cancelHold();
          if (target && !target.disabled) {
            if (shared.marketplace === 'oz') { if (typeof ozEmployeeCompleteTrigger === 'function') ozEmployeeCompleteTrigger(); }
            else if (shared.marketplace === 'ym') ymEmployeeCompleteOrder();
            else if (typeof wbEmployeeCompleteTrigger === 'function') wbEmployeeCompleteTrigger();
            else if (typeof wbHandleEmployeeCompleteNoScan === 'function') wbHandleEmployeeCompleteNoScan();
          }
        }
      }, 40);
    }
  });
  window.addEventListener('keyup', (e) => { if (e.code === 'Space') cancelHold(); });
  window.addEventListener('blur', cancelHold);

  // TAB — открыть ВЕРХНИЙ заказ из текущего (отсортированного) списка сотрудника.
  // Мышкой можно открыть любой; TAB всегда берёт первый по текущей сортировке.
  window.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab' || e.ctrlKey || e.altKey || e.metaKey || e.shiftKey) return;
    if (inField()) return;
    const mp = shared.marketplace;
    if (mp !== 'oz' && mp !== 'wb' && mp !== 'ym') return;
    if (orderOpen()) return; // уже внутри заказа
    if (mp === 'ym') {
      const first = (ymState.employeeDetail?.orders || []).find((order) => order.local_state !== 'completed');
      if (!first) return;
      e.preventDefault();
      ymState.employeeSelectedOrderId = String(first.order_id);
      render();
      return;
    }
    if (!document.querySelector('[data-employee-order-posting],[data-employee-order-id]')) return; // только на списке сотрудника
    e.preventDefault();
    const orders = mp === 'oz' ? ozEmployeeSortedOrders() : wbEmployeeSortedOrders();
    if (orders && orders[0]) empOpenOrder(mp, orders[0]);
  }, true);

  // Ctrl (короткое одиночное нажатие) — показать/скрыть фото товара во весь экран внутри заказа.
  // Отслеживаем «чистый тап» по Ctrl: если между down и up нажали другую клавишу (напр. Ctrl+Shift+R) — не срабатывает.
  let ctrlTap = false;
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Control') { if (!e.repeat) ctrlTap = orderOpen() && !inField(); return; }
    ctrlTap = false;
  }, true);
  window.addEventListener('keyup', (e) => {
    if (e.key !== 'Control' || !ctrlTap) return;
    ctrlTap = false;
    if (closePhotoFullscreen()) return;
    if (!orderOpen()) return;
    const url = empCurrentOrderPhoto();
    if (url) openPhotoFullscreen(url);
  }, true);
})();


